  ('2027-12-25', 'Christmas Day')
on conflict (day) do nothing;

-- ==== 20260930001000_service_api.sql ====

-- 0010  Service API: what the Edge Functions do to the database, as small functions.
--
-- Why functions and not table writes from the Edge Functions?
--  * The rules that matter (one vote per phone, a code that locks after five tries, a payment that
--    settles exactly once, an alert that needs a second person) live in ONE place, next to the data,
--    and are covered by the offline database tests.
--  * The Edge Functions stay thin: validate, rate-limit, talk to the outside world (SMS, M-Pesa, KRA,
--    the AI provider), then call one of these.
--
-- Every `svc_*` function is SECURITY DEFINER and executable by the service role ONLY. Residents and staff
-- can not call them, even with a valid session; the tests check that.
-- The `ai_*` functions at the end are the opposite: SECURITY INVOKER, run with the asker's own permissions.

alter table private.outbox add column claimed_at timestamptz;

-- ---- abuse control -------------------------------------------------------------------------------------------

create function public.svc_rate_limit(p_key text, p_window_seconds int, p_max int)
returns boolean
language sql
security definer
set search_path = ''
as $$ select private.rate_limit_hit(p_key, p_window_seconds, p_max); $$;

-- Housekeeping: expired codes and old counters do not need to live in the database.
create function public.svc_cleanup()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from private.otp_codes  where created_at < now() - interval '1 day';
  delete from private.rate_limits where window_start < now() - interval '2 days';
  delete from private.outbox     where status in ('sent', 'failed') and created_at < now() - interval '90 days';
$$;

-- ---- one-time codes ---------------------------------------------------------------------------------------------
-- The function never sees a plain code: it stores and compares keyed hashes computed by the Edge Function.

create function public.svc_otp_issue(p_phone text, p_phone_hash bytea, p_purpose text, p_code_hash bytea, p_ttl_seconds int default 300)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  -- Only the newest code works: retire any earlier one for the same phone and purpose.
  update private.otp_codes set consumed_at = now()
   where phone_hash = p_phone_hash and purpose = p_purpose and consumed_at is null;
  insert into private.otp_codes (phone_hash, phone_e164, code_hash, purpose, expires_at)
  values (p_phone_hash, p_phone, p_code_hash, p_purpose, now() + make_interval(secs => p_ttl_seconds))
  returning id into v_id;
  return v_id;
end;
$$;

-- 'ok' | 'invalid' | 'expired' | 'locked'. A code is single-use and locks after too many wrong tries.
create function public.svc_otp_verify(p_phone_hash bytea, p_purpose text, p_code_hash bytea, p_max_attempts int default 5)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  r private.otp_codes;
begin
  select * into r from private.otp_codes
   where phone_hash = p_phone_hash and purpose = p_purpose and consumed_at is null
   order by created_at desc limit 1
   for update;
  if not found then return 'invalid'; end if;
  if r.expires_at < now() then
    update private.otp_codes set consumed_at = now() where id = r.id;
    return 'expired';
  end if;
  if r.attempts >= p_max_attempts then return 'locked'; end if;
  update private.otp_codes set attempts = attempts + 1 where id = r.id;
  if r.code_hash = p_code_hash then
    update private.otp_codes set consumed_at = now() where id = r.id;
    return 'ok';
  end if;
  return 'invalid';
end;
$$;

-- ---- participation ------------------------------------------------------------------------------------------------

-- 'ok' | 'duplicate' | 'closed' | 'invalid_option'. The voter is only ever a keyed hash.
create function public.svc_cast_vote(p_cycle text, p_ward text, p_option text, p_channel text, p_voter_hash bytea)
returns text
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.budget_cycles c
                  where c.id = p_cycle and c.status = 'open' and now() between c.starts_at and c.ends_at) then
    return 'closed';
  end if;
  if not exists (select 1 from public.project_options o
                  where o.id = p_option and o.cycle_id = p_cycle and o.ward_id = p_ward) then
    return 'invalid_option';
  end if;
  insert into public.votes (cycle_id, ward_id, option_id, channel, voter_hash)
  values (p_cycle, p_ward, p_option, p_channel, p_voter_hash);
  return 'ok';
exception when unique_violation then
  return 'duplicate';
end;
$$;

create function public.svc_subscribe(p_phone text, p_ward text, p_frequency text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into private.subscribers (phone_e164, ward_id, frequency, verified_at)
  values (p_phone, p_ward, p_frequency, now())
  on conflict (phone_e164, ward_id)
    do update set frequency = excluded.frequency, verified_at = now(), opted_out_at = null;
$$;

-- STOP: leave one ward, or every ward when p_ward is null. Returns how many subscriptions were switched off.
create function public.svc_unsubscribe(p_phone text, p_ward text default null)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  n int;
begin
  update private.subscribers set opted_out_at = now()
   where phone_e164 = p_phone and opted_out_at is null and (p_ward is null or ward_id = p_ward);
  get diagnostics n = row_count;
  return n;
end;
$$;

-- The caller chooses the id so it can compute the author's supporter hash for THIS idea, the same way it will for
-- everyone else; otherwise the author could back their own idea a second time.
create function public.svc_submit_proposal(p_id uuid, p_ward text, p_kind text, p_title text, p_body text, p_voter_hash bytea)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  insert into public.proposals (id, ward_id, kind, title, body)
  values (coalesce(p_id, gen_random_uuid()), p_ward, p_kind, p_title, p_body) returning id into v_id;
  -- the author is the first supporter
  insert into public.proposal_supports (proposal_id, voter_hash) values (v_id, p_voter_hash);
  return v_id;
end;
$$;

-- 'ok' | 'duplicate' | 'closed' | 'not_found'
create function public.svc_support_proposal(p_id uuid, p_voter_hash bytea)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_status text;
begin
  select status into v_status from public.proposals where id = p_id;
  if not found then return 'not_found'; end if;
  if v_status not in ('submitted', 'under_review') then return 'closed'; end if;
  insert into public.proposal_supports (proposal_id, voter_hash) values (p_id, p_voter_hash);
  return 'ok';
exception when unique_violation then
  return 'duplicate';
end;
$$;

-- ---- reports ----------------------------------------------------------------------------------------------------------
-- Idempotent on client_key, so an offline queue that retries never creates a second case.
-- Routing, priority and both SLA timers are stamped by the trigger on insert.

create function public.svc_create_report(
  p_id uuid, p_client_key uuid, p_ward text, p_category text, p_description text,
  p_lat numeric, p_lng numeric, p_language text, p_channel text,
  p_callback_phone text default null, p_photo_paths text[] default '{}'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.reports;
  p text;
begin
  if p_client_key is not null then
    select * into r from public.reports where client_key = p_client_key;
    if found then
      return jsonb_build_object('reference', r.reference, 'ward_id', r.ward_id, 'status', r.status, 'duplicate', true);
    end if;
  end if;

  insert into public.reports (id, client_key, ward_id, category_id, description, lat, lng, language, channel)
  values (coalesce(p_id, gen_random_uuid()), p_client_key, p_ward, p_category, p_description, p_lat, p_lng, p_language, p_channel)
  returning * into r;

  foreach p in array coalesce(p_photo_paths, '{}') loop
    insert into public.report_photos (report_id, storage_path) values (r.id, p);
  end loop;
  if p_callback_phone is not null then
    insert into private.report_contacts (report_id, phone_e164) values (r.id, p_callback_phone);
  end if;
  return jsonb_build_object('reference', r.reference, 'ward_id', r.ward_id, 'status', r.status, 'duplicate', false);
exception when unique_violation then
  -- a concurrent retry of the same client_key won the race
  select * into r from public.reports where client_key = p_client_key;
  if found then
    return jsonb_build_object('reference', r.reference, 'ward_id', r.ward_id, 'status', r.status, 'duplicate', true);
  end if;
  raise;
end;
$$;

-- ---- payments ---------------------------------------------------------------------------------------------------------
-- The server decides what is owed. The browser only says WHICH application to pay for.

create function public.svc_payment_prepare(p_application uuid, p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  a public.applications;
  v_service text;
begin
  select * into a from public.applications where id = p_application and applicant_id = p_user;
  if not found then return jsonb_build_object('status', 'not_found'); end if;
  if a.status <> 'awaiting_payment' or a.amount <= 0 then return jsonb_build_object('status', 'not_payable'); end if;
  if exists (select 1 from public.payments p
              where p.application_id = a.id and p.status = 'pending' and p.created_at > now() - interval '2 minutes') then
    return jsonb_build_object('status', 'pending_exists');
  end if;
  select name into v_service from public.services where id = a.service_id;
  return jsonb_build_object('status', 'ok', 'reference', a.reference, 'amount', a.amount, 'service', v_service);
end;
$$;

create function public.svc_payment_record(p_application uuid, p_user uuid, p_checkout text, p_amount numeric, p_last4 text)
returns uuid
language sql
security definer
set search_path = ''
as $$
  insert into public.payments (application_id, payer_id, checkout_request_id, amount, phone_last4, status, stream)
  values (p_application, p_user, p_checkout, p_amount, p_last4, 'pending', 'services')
  returning id;
$$;

-- Called by the M-Pesa callback. 'completed' | 'failed' | 'already' | 'unknown' | 'amount_mismatch' | 'invalid'.
-- Idempotent: Safaricom retries callbacks, and a second delivery must change nothing.
create function public.svc_payment_settle(p_checkout text, p_result_code int, p_receipt text, p_amount numeric, p_last4 text default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  p public.payments;
  a public.applications;
begin
  select * into p from public.payments where checkout_request_id = p_checkout for update;
  if not found then return 'unknown'; end if;
  if p.status <> 'pending' then return 'already'; end if;
  if p.application_id is not null then select * into a from public.applications where id = p.application_id; end if;

  if p_result_code <> 0 then
    update public.payments set status = case when p_result_code = 1037 then 'timeout' else 'failed' end where id = p.id;
    if a.id is not null then
      insert into public.notifications (user_id, title, message, kind, link)
      values (a.applicant_id, 'Payment not completed',
              'We did not receive your M-Pesa payment for ' || a.reference || '. You can try again from the application.',
              'warning', '/services/applications/' || a.id);
    end if;
    return 'failed';
  end if;

  if p_receipt is null or p_amount is null then return 'invalid'; end if;

  -- Money arrived but not the amount we asked for: leave the payment pending and put the receipt in front of finance.
  if p_amount is distinct from p.amount then
    insert into public.revenue_entries (reference, amount, stream, source, reconciled)
    values (p_receipt, p_amount, 'unallocated', 'mpesa', false)
    on conflict (reference) do nothing;
    return 'amount_mismatch';
  end if;

  begin
    update public.payments
       set status = 'completed', mpesa_receipt = p_receipt, phone_last4 = coalesce(p_last4, phone_last4), completed_at = now()
     where id = p.id;
  exception when unique_violation then
    return 'already';   -- the same receipt was already recorded
  end;

  insert into public.revenue_entries (reference, amount, stream, source, payment_id, reconciled)
  values (p_receipt, p.amount, p.stream, 'mpesa', p.id, true)
  on conflict (reference) do nothing;

  if a.id is not null and a.status = 'awaiting_payment' then
    update public.applications set status = 'submitted' where id = a.id;
    insert into public.notifications (user_id, title, message, kind, link)
    values (a.applicant_id, 'Payment received',
            'KES ' || to_char(p.amount, 'FM999,999,990') || ' received. Your application ' || a.reference || ' is now with the county.',
            'success', '/services/applications/' || a.id);
  end if;
  return 'completed';
end;
$$;

-- Paybill (C2B) confirmation. If the account number is an application reference that is waiting for exactly this
-- amount, the application is paid. Anything else is recorded as unallocated revenue for finance to place.
-- 'matched' | 'recorded' | 'duplicate'
create function public.svc_c2b_record(p_trans_id text, p_amount numeric, p_bill_ref text, p_payer_name text default null, p_time timestamptz default now())
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  a public.applications;
  v_pay uuid;
begin
  if exists (select 1 from public.revenue_entries where reference = p_trans_id) then return 'duplicate'; end if;

  select * into a from public.applications
   where reference = upper(trim(coalesce(p_bill_ref, ''))) and status = 'awaiting_payment'
   for update;
  if found and a.amount = p_amount then
    insert into public.payments (application_id, payer_id, amount, status, mpesa_receipt, stream, completed_at)
    values (a.id, a.applicant_id, p_amount, 'completed', p_trans_id, 'services', now())
    returning id into v_pay;
    insert into public.revenue_entries (reference, amount, payer_name, stream, source, payment_id, reconciled, received_at)
    values (p_trans_id, p_amount, p_payer_name, 'services', 'mpesa', v_pay, true, p_time);
    update public.applications set status = 'submitted' where id = a.id;
    insert into public.notifications (user_id, title, message, kind, link)
    values (a.applicant_id, 'Payment received',
            'KES ' || to_char(p_amount, 'FM999,999,990') || ' received. Your application ' || a.reference || ' is now with the county.',
            'success', '/services/applications/' || a.id);
    return 'matched';
  end if;

  insert into public.revenue_entries (reference, amount, payer_name, stream, source, reconciled, received_at)
  values (p_trans_id, p_amount, p_payer_name, 'unallocated', 'mpesa', false, p_time);
  return 'recorded';
end;
$$;

-- ---- outgoing messages -------------------------------------------------------------------------------------------------

create function public.svc_outbox_claim(p_limit int default 25)
returns table (id uuid, channel text, recipient text, subject text, body text, attempts int, related jsonb)
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- give back anything a crashed worker left half-sent
  update private.outbox set status = 'queued' where status = 'sending' and claimed_at < now() - interval '10 minutes';
  return query
  with due as (
    select o.id from private.outbox o
     where o.status = 'queued' and o.run_after <= now()
     order by o.created_at
     limit greatest(p_limit, 1)
     for update skip locked
  )
  update private.outbox o set status = 'sending', claimed_at = now()
    from due where o.id = due.id
  returning o.id, o.channel, o.recipient, o.subject, o.body, o.attempts, o.related;
end;
$$;

-- Success, or a failure that is retried with a growing delay and abandoned after five attempts.
create function public.svc_outbox_done(p_id uuid, p_ok boolean, p_error text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  n int;
begin
  if p_ok then
    update private.outbox set status = 'sent', sent_at = now(), last_error = null where id = p_id;
    return;
  end if;
  select attempts + 1 into n from private.outbox where id = p_id;
  update private.outbox
     set attempts = n,
         last_error = left(p_error, 300),
         status = case when n >= 5 then 'failed' else 'queued' end,
         run_after = now() + make_interval(mins => (5 * n * n))
   where id = p_id;
end;
$$;

-- An approved alert goes to every verified subscriber of its ward (everyone, if it is county-wide).
-- Official alerts ignore the subscriber's digest frequency: a water shut-off is not a weekly summary.
create function public.svc_dispatch_alerts()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  a public.alerts;
  n int;
  total int := 0;
  v_name text;
begin
  select c.name into v_name from public.county c limit 1;
  for a in select * from public.alerts where status = 'approved' order by created_at for update skip locked loop
    insert into private.outbox (channel, recipient, body, related)
    select 'sms', s.phone_e164, left(coalesce(v_name, 'County') || ': ' || a.body || ' Reply STOP to opt out.', 480), jsonb_build_object('alert_id', a.id)
      from (select distinct x.phone_e164 from private.subscribers x
             where x.verified_at is not null and x.opted_out_at is null
               and (a.ward_id is null or x.ward_id = a.ward_id)) s;
    get diagnostics n = row_count;
    update public.alerts set status = 'sent', sent_at = now(), recipients = n where id = a.id;
    total := total + n;
  end loop;
  return total;
end;
$$;

-- Short SMS summaries for people who chose "daily" or "weekly" instead of instant alerts.
create function public.svc_ward_updates(p_frequency text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_days int := case p_frequency when 'daily' then 1 when 'weekly' then 7 else null end;
  v_name text;
  v_url text;
  w record;
  n int;
  total int := 0;
begin
  if v_days is null then return 0; end if;
  select c.name, c.settings ->> 'web_url' into v_name, v_url from public.county c limit 1;
  for w in
    select ward.id, ward.name,
           (select count(*) from public.reports r where r.ward_id = ward.id and r.resolved_at >= now() - make_interval(days => v_days)) as fixed,
           (select count(*) from public.reports r where r.ward_id = ward.id and r.status not in ('resolved', 'closed', 'rejected')) as open_now
      from public.wards ward
     where exists (select 1 from private.subscribers s
                    where s.ward_id = ward.id and s.frequency = p_frequency and s.verified_at is not null and s.opted_out_at is null)
  loop
    insert into private.outbox (channel, recipient, body, related)
    select 'sms', s.phone_e164,
           left(format('%s, %s %s: %s problem%s fixed, %s still open.%s Reply STOP to opt out.',
                       w.name, coalesce(v_name, 'County'), case p_frequency when 'daily' then 'today' else 'this week' end,
                       w.fixed, case when w.fixed = 1 then '' else 's' end, w.open_now,
                       case when v_url is null then '' else ' ' || v_url end), 480),
           jsonb_build_object('ward_id', w.id, 'frequency', p_frequency)
      from private.subscribers s
     where s.ward_id = w.id and s.frequency = p_frequency and s.verified_at is not null and s.opted_out_at is null;
    get diagnostics n = row_count;
    total := total + n;
  end loop;
  return total;
end;
$$;

-- ---- escalation ladder: run it, then tell the right people ------------------------------------------------------------

create function public.svc_escalate()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  e record;
  r public.reports;
  w public.wards;
  v_name text;
  v_url text;
  v_cat text;
  v_ref text;
  v_msg text;
  n int;
  total int := 0;
begin
  select c.name, c.settings ->> 'console_url' into v_name, v_url from public.county c limit 1;
  for e in select * from public.run_escalations() loop
    select * into r from public.reports where id = e.report_id;
    select * into w from public.wards where id = r.ward_id;
    select name into v_cat from public.report_categories where id = r.category_id;
    v_ref := format('%s (%s, %s)', r.reference, coalesce(v_cat, 'Report'), w.name);
    v_msg := case e.level
      when 1 then 'Reminder: case ' || v_ref || ' has not been acknowledged yet.'
      when 2 then 'Case ' || v_ref || ' has waited more than 5 working days without being acknowledged.'
      when 3 then 'Case ' || v_ref || ' has passed its target date.'
      else        'Case ' || v_ref || ' is more than 30 days past its target date and has been escalated to the CEC member and Assembly committee.'
    end || case when v_url is null then '' else ' ' || v_url || '/cases/' || r.id end;

    with recips as (
      select distinct s.user_id
        from public.staff_roles s
       where s.active and (s.expires_at is null or s.expires_at > now())
         and (   (e.level = 1 and r.assigned_to is not null and s.user_id = r.assigned_to)
              or (e.level = 1 and s.role = 'ward_admin' and s.ward_id = r.ward_id)
              or (e.level = 1 and r.assigned_to is null and s.role = 'officer' and s.department_id = r.department_id)
              or (e.level = 2 and s.role = 'sub_county_admin' and s.sub_county_id = w.sub_county_id)
              or (e.level = 3 and s.role = 'chief_officer' and s.department_id = r.department_id)
              or (e.level >= 4 and s.role in ('admin', 'assembly_member')))
    ), contacts as (
      -- email where they have one; otherwise the phone they signed in with (assembly members)
      select 'email' as channel, u.email as recipient from recips join auth.users u on u.id = recips.user_id where u.email is not null
      union
      select 'sms', p.phone from recips join public.profiles p on p.id = recips.user_id
       where p.phone is not null and not exists (select 1 from auth.users u where u.id = recips.user_id and u.email is not null)
    )
    insert into private.outbox (channel, recipient, subject, body, related)
    select c.channel, c.recipient,
           case when c.channel = 'email' then format('[%s] %s', coalesce(v_name, 'County'), 'Case ' || r.reference || ' needs attention') end,
           case when c.channel = 'sms' then left(coalesce(v_name, 'County') || ': ' || v_msg, 320) else v_msg end,
           jsonb_build_object('report_id', r.id, 'level', e.level)
      from contacts c;
    get diagnostics n = row_count;
    total := total + n;
  end loop;
  return total;
end;
$$;

-- ---- digests to oversight bodies ---------------------------------------------------------------------------------------------
-- kind: assembly | controller_of_budget | auditor_general | executive (| ward | department, no recipients).
-- Recipients come from county.settings.digest_recipients = { "<kind>": ["email", ...] }.
-- Assembly and executive digests name the officer holding a case that is 30+ days late; the two audit bodies
-- see departments only. Each recipient gets a link that records when it was opened.
create function public.svc_build_digest(p_kind text, p_start date, p_end date)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_name text;
  v_named boolean := p_kind in ('assembly', 'executive');
  v_received int; v_resolved int; v_open int; v_overdue int;
  v_apps_in int; v_apps_out int;
  v_stalled int; v_over_budget int;
  v_rev numeric; v_unmatched int;
  v_dept text; v_top text; v_body text;
  v_emails jsonb;
  v_tok record;
begin
  select id into v_id from public.digests where kind = p_kind and period_start = p_start and period_end = p_end;
  if found then return v_id; end if;
  select c.name, c.settings -> 'digest_recipients' -> p_kind into v_name, v_emails from public.county c limit 1;

  select count(*) filter (where created_at::date between p_start and p_end),
         count(*) filter (where resolved_at::date between p_start and p_end),
         count(*) filter (where status not in ('resolved', 'closed', 'rejected')),
         count(*) filter (where status not in ('resolved', 'closed', 'rejected') and resolve_due_at < now())
    into v_received, v_resolved, v_open, v_overdue
    from public.reports;
  select count(*) filter (where created_at::date between p_start and p_end),
         count(*) filter (where decided_at::date between p_start and p_end)
    into v_apps_in, v_apps_out from public.applications;
  select count(*) filter (where status = 'stalled'), count(*) filter (where spent > budget * 1.02)
    into v_stalled, v_over_budget from public.projects where published;
  select coalesce(sum(amount), 0), count(*) filter (where not reconciled)
    into v_rev, v_unmatched from public.revenue_entries where received_at::date between p_start and p_end;

  select coalesce(string_agg(format('- %s: %s overdue, longest wait %s days', d.name, x.n, x.longest), E'\n' order by x.n desc), '- None')
    into v_dept
    from (select r.department_id, count(*) n, max(extract(day from now() - r.resolve_due_at))::int longest
            from public.reports r
           where r.status not in ('resolved', 'closed', 'rejected') and r.resolve_due_at < now() group by r.department_id) x
    join public.departments d on d.id = x.department_id;

  select coalesce(string_agg(format('- %s · %s · %s · %s days late · %s', r.reference, coalesce(c.name, 'Report'), w.name,
                                    extract(day from now() - r.resolve_due_at)::int,
                                    case when v_named then coalesce(nullif(pr.name, ''), d.name, 'unassigned') else coalesce(d.name, 'unassigned') end),
                           E'\n' order by r.resolve_due_at), '- None')
    into v_top
    from public.reports r
    join public.wards w on w.id = r.ward_id
    left join public.report_categories c on c.id = r.category_id
    left join public.departments d on d.id = r.department_id
    left join public.profiles pr on pr.id = r.assigned_to
   where r.status not in ('resolved', 'closed', 'rejected') and r.resolve_due_at < now() - interval '30 days';

  v_body := format(E'# %s County service digest, %s to %s\n\n', coalesce(v_name, 'County'), p_start, p_end)
         || format(E'**Cases:** %s received, %s resolved, %s open, **%s overdue**.\n', v_received, v_resolved, v_open, v_overdue)
         || format(E'**Applications:** %s received, %s decided.\n', v_apps_in, v_apps_out)
         || format(E'**Projects:** %s stalled, %s over budget.\n', v_stalled, v_over_budget)
         || format(E'**Revenue:** KES %s collected, %s payments not yet matched.\n\n', to_char(v_rev, 'FM999,999,999,990'), v_unmatched)
         || format(E'## Overdue by department\n%s\n\n## More than 30 days late\n%s\n', v_dept, v_top);

  insert into public.digests (kind, period_start, period_end, body_md, payload)
  values (p_kind, p_start, p_end, v_body,
          jsonb_build_object('received', v_received, 'resolved', v_resolved, 'open', v_open, 'overdue', v_overdue,
                             'applications_received', v_apps_in, 'applications_decided', v_apps_out,
                             'stalled_projects', v_stalled, 'over_budget_projects', v_over_budget, 'revenue', v_rev))
  returning id into v_id;

  if v_emails is not null and jsonb_typeof(v_emails) = 'array' then
    for v_tok in
      with ins as (
        insert into public.digest_recipients (digest_id, email)
        select v_id, lower(trim(e)) from jsonb_array_elements_text(v_emails) e where position('@' in e) > 1
        returning email, open_token
      ) select * from ins
    loop
      insert into private.outbox (channel, recipient, subject, body, related)
      values ('email', v_tok.email, format('[%s] Service digest %s to %s', coalesce(v_name, 'County'), p_start, p_end),
              v_body || E'\nOpen the full digest: {{open_url}}\n', jsonb_build_object('digest_id', v_id, 'open_token', v_tok.open_token));
    end loop;
  end if;
  return v_id;
end;
$$;

-- The link in a digest email: counts the open, and says which recipient it was.
create function public.svc_digest_opened(p_token uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.digest_recipients
     set open_count = open_count + 1, first_opened_at = coalesce(first_opened_at, now())
   where open_token = p_token;
  return found;
end;
$$;

-- ---- staff accounts created outside the console ---------------------------------------------------------------------------------

-- Same rule as private.mfa_ok(), but for a session the Edge Function has already verified
-- (it passes the token's `aal` claim). Returns true if the user holds any of the roles.
create function public.svc_staff_check(p_user uuid, p_roles text[], p_aal text default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.staff_roles r
     where r.user_id = p_user and r.active and (r.expires_at is null or r.expires_at > now())
       and r.role = any (p_roles)
       and (coalesce((select c.settings ->> 'require_staff_mfa' from public.county c limit 1), 'false') <> 'true' or p_aal = 'aal2')
  );
$$;

create function public.svc_invite_create(p_token_hash bytea, p_email text, p_org text, p_days int, p_created_by uuid)
returns uuid
language sql
security definer
set search_path = ''
as $$
  insert into public.auditor_invites (token_hash, email, organisation, expires_at, created_by)
  values (p_token_hash, lower(trim(p_email)), p_org, now() + make_interval(days => p_days), p_created_by)
  returning id;
$$;

create function public.svc_invite_check(p_token_hash bytea, p_email text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.auditor_invites i
                  where i.token_hash = p_token_hash and i.used_at is null and i.expires_at > now()
                    and i.email = lower(trim(p_email)));
$$;

-- Uses the invitation (once) and gives the new account a time-limited auditor role.
create function public.svc_accept_invite(p_token_hash bytea, p_email text, p_user uuid, p_access_days int)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  update public.auditor_invites set used_at = now()
   where token_hash = p_token_hash and used_at is null and expires_at > now() and email = lower(trim(p_email))
  returning id into v_id;
  if v_id is null then return false; end if;
  perform public.grant_staff_role(p_user, 'auditor', null, null, null, now() + make_interval(days => p_access_days));
  return true;
end;
$$;

create function public.svc_kra_record(p_contractor uuid, p_compliant boolean)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.contractors set kra_compliant = p_compliant, kra_checked_at = now() where id = p_contractor;
$$;

-- ---- AI spend control ---------------------------------------------------------------------------------------------------------------

-- The department a staff member's AI use is billed to: the department on their role, else the county-wide pool.
create function public.svc_ai_department(p_user uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select r.department_id from public.staff_roles r
   where r.user_id = p_user and r.active and (r.expires_at is null or r.expires_at > now()) and r.department_id is not null
   order by r.created_at limit 1;
$$;

-- Cap for this month: the department's own budget, else the county-wide one, else settings.ai_default_cap_kes, else nothing.
create function public.svc_ai_check(p_department uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_month date := date_trunc('month', now())::date;
  v_cap numeric;
  v_spent numeric;
begin
  select cap_kes into v_cap from public.ai_budgets where department_id is not distinct from p_department and month = v_month;
  if v_cap is null then select cap_kes into v_cap from public.ai_budgets where department_id is null and month = v_month; end if;
  if v_cap is null then
    select coalesce((c.settings ->> 'ai_default_cap_kes')::numeric, 0) into v_cap from public.county c limit 1;
  end if;
  v_spent := private.ai_spend_mtd(p_department);
  return jsonb_build_object('spent', v_spent, 'cap', coalesce(v_cap, 0), 'allowed', v_spent < coalesce(v_cap, 0));
end;
$$;

create function public.svc_ai_log(p_task text, p_model text, p_side text, p_department uuid, p_actor uuid,
                                  p_tokens_in int, p_tokens_out int, p_cost_kes numeric, p_ok boolean, p_redactions int)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.ai_calls (task, model, side, department_id, actor_id, tokens_in, tokens_out, cost_kes, ok, redactions)
  values (p_task, p_model, p_side, p_department, p_actor, p_tokens_in, p_tokens_out, p_cost_kes, p_ok, p_redactions);
$$;

-- ---- grants: service role only --------------------------------------------------------------------------------------------------------------

do $$
declare
  f regprocedure;
begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'public' and p.proname like 'svc\_%' loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end $$;

-- ---- the AI assistant's questions ---------------------------------------------------------------------------------------------------------
-- The model never writes SQL. It picks one of these named questions and fills in the parameters; the gateway
-- runs it as the person asking, so row-level security decides what they may see. Small, fixed, read-only.

create function public.ai_cases_by_ward(p_category text default null, p_open_only boolean default true, p_limit int default 10)
returns table (ward text, cases bigint)
language sql
stable
set search_path = ''
as $$
  select w.name, count(*)
    from public.reports r join public.wards w on w.id = r.ward_id
   where (p_category is null or r.category_id = p_category)
     and (not p_open_only or r.status not in ('resolved', 'closed', 'rejected'))
   group by w.name order by 2 desc, 1
   limit least(greatest(p_limit, 1), 50);
$$;

create function public.ai_overdue_by_department(p_min_days int default 1)
returns table (department text, overdue bigint, longest_days int)
language sql
stable
set search_path = ''
as $$
  select coalesce(d.name, 'Unassigned'), count(*), max(extract(day from now() - r.resolve_due_at))::int
    from public.reports r left join public.departments d on d.id = r.department_id
   where r.status not in ('resolved', 'closed', 'rejected')
     and r.resolve_due_at < now() - make_interval(days => greatest(p_min_days, 0))
   group by d.name order by 2 desc;
$$;

create function public.ai_revenue_by_stream(p_days int default 30)
returns table (stream text, collected numeric, payments bigint)
language sql
stable
set search_path = ''
as $$
  select e.stream, sum(e.amount), count(*)
    from public.revenue_entries e
   where e.received_at >= now() - make_interval(days => least(greatest(p_days, 1), 366))
   group by e.stream order by 2 desc;
$$;

create function public.ai_sla_performance(p_days int default 30)
returns table (category text, received bigint, resolved_on_time_pct numeric, median_hours_to_acknowledge numeric)
language sql
stable
set search_path = ''
as $$
  select coalesce(c.name, r.category_id, 'Uncategorised'),
         count(*),
         round(100.0 * count(*) filter (where r.resolved_at is not null and r.resolved_at <= r.resolve_due_at) / nullif(count(*) filter (where r.resolved_at is not null), 0), 1),
         round((percentile_cont(0.5) within group (order by extract(epoch from (r.acknowledged_at - r.created_at)) / 3600))::numeric, 1)
    from public.reports r left join public.report_categories c on c.id = r.category_id
   where r.created_at >= now() - make_interval(days => least(greatest(p_days, 1), 366))
   group by 1 order by 2 desc;
$$;

create function public.ai_projects_by_status()
returns table (status text, projects bigint, budget numeric, spent numeric)
language sql
stable
set search_path = ''
as $$
  select p.status, count(*), sum(p.budget), sum(p.spent) from public.projects p group by p.status order by 2 desc;
$$;

revoke all on function public.ai_cases_by_ward(text, boolean, int), public.ai_overdue_by_department(int),
  public.ai_revenue_by_stream(int), public.ai_sla_performance(int), public.ai_projects_by_status() from public, anon;
grant execute on function public.ai_cases_by_ward(text, boolean, int), public.ai_overdue_by_department(int),
  public.ai_revenue_by_stream(int), public.ai_sla_performance(int), public.ai_projects_by_status() to authenticated;

-- ==== 20260930001100_admin_ops.sql ====

-- 0011  Administration: services scoped to their department, a guard on the two-factor switch, AI spend for administrators.

-- ---- services: a chief officer edits their own department's services, not everyone's ------------------------------------------
drop policy "services: staff write" on public.services;
create policy "services: staff write" on public.services for all to authenticated
  using (private.is_admin()
         or exists (select 1 from public.staff_roles r
                     where r.user_id = (select auth.uid()) and private.mfa_ok() and r.active
                       and (r.expires_at is null or r.expires_at > now())
                       and r.role = 'chief_officer' and r.department_id = services.department_id))
  with check (private.is_admin()
         or exists (select 1 from public.staff_roles r
                     where r.user_id = (select auth.uid()) and private.mfa_ok() and r.active
                       and (r.expires_at is null or r.expires_at > now())
                       and r.role = 'chief_officer' and r.department_id = services.department_id));

-- ---- the two-factor switch cannot lock the county out --------------------------------------------------------------------------
-- Turning "require_staff_mfa" on makes every staff permission need a second factor. The person turning it on must
-- therefore be signed in with one, otherwise they would lock themselves out in the same click.
-- (The SQL editor and the service role have no signed-in user and are not affected.)
create function private.guard_mfa_switch()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(new.settings ->> 'require_staff_mfa', 'false') = 'true'
     and coalesce(old.settings ->> 'require_staff_mfa', 'false') <> 'true'
     and (select auth.uid()) is not null
     and coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'aal', '') <> 'aal2' then
    raise exception 'Sign in with your authenticator app before turning on two-factor for everyone' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger county_mfa_switch before update on public.county
  for each row execute function private.guard_mfa_switch();

-- ---- AI spend, for administrators ----------------------------------------------------------------------------------------------------
-- Per department for the current month: what was spent, the cap that applies, and the number of calls.
-- Runs as the caller, so it returns nothing to anyone who may not read ai_calls / ai_budgets.
create function public.ai_usage()
returns table (department_id uuid, department text, spent_kes numeric, cap_kes numeric, calls bigint)
language sql
stable
set search_path = ''
as $$
  with m as (select date_trunc('month', now())::date as month),
  base as (select null::uuid as id, 'County-wide pool'::text as name
           union all select d.id, d.name from public.departments d),
  spend as (select c.department_id as id, sum(c.cost_kes) as spent, count(*) as calls
              from public.ai_calls c where c.side = 'county' and c.at >= (select month from m) group by c.department_id)
  select b.id, b.name, coalesce(s.spent, 0), coalesce(
           (select x.cap_kes from public.ai_budgets x where x.department_id is not distinct from b.id and x.month = (select month from m)),
           (select x.cap_kes from public.ai_budgets x where x.department_id is null and x.month = (select month from m)),
           (select (c.settings ->> 'ai_default_cap_kes')::numeric from public.county c limit 1), 0),
         coalesce(s.calls, 0)
    from base b left join spend s on s.id is not distinct from b.id
   where private.has_role(array['super_admin', 'admin', 'auditor'])
   order by (b.id is not null), b.name;
$$;

-- Set (or clear, with null) this month's cap for one department, or for the county-wide pool when p_department is null.
create function public.set_ai_budget(p_department uuid, p_cap numeric)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_month date := date_trunc('month', now())::date;
begin
  if p_cap is null then
    delete from public.ai_budgets where department_id is not distinct from p_department and month = v_month;
  else
    if p_cap < 0 or p_cap > 10000000 then raise exception 'Cap out of range' using errcode = '22023'; end if;
    insert into public.ai_budgets (department_id, month, cap_kes) values (p_department, v_month, p_cap)
    on conflict (department_id, month) do update set cap_kes = excluded.cap_kes;
  end if;
end;
$$;

revoke all on function public.ai_usage(), public.set_ai_budget(uuid, numeric) from public, anon;
grant execute on function public.ai_usage(), public.set_ai_budget(uuid, numeric) to authenticated;

-- ==== 20260930001200_procurement_watch.sql ====

-- 0012  Procurement watch: who wins county money, how, and which patterns deserve a closer look.
--
-- Based on the open-contracting "red flag" approach (open-contracting.org/redflags) and Ukraine's Prozorro risk indicators:
-- rules over public procurement data that point at patterns, never at people. A flag is a prompt for scrutiny, not a finding.
-- Everything here reads data that is already public (tenders, projects, contractor names). Reviewing a flag is a staff action
-- and the response is published next to it.

-- ---- what a tender record needs so it can be analysed ----------------------------------------------------------------
alter table public.tenders
  add column procurement_method text not null default 'open_tender'
    check (procurement_method in ('open_tender', 'restricted', 'request_for_quotation', 'direct', 'framework')),
  add column award_amount numeric(16, 2) check (award_amount is null or award_amount >= 0),
  add column awarded_at timestamptz;

create or replace view public.public_tenders as
select t.id, t.reference, t.title, t.ward_id, w.name as ward_name, t.sector, t.status,
       t.estimated_budget, t.applicants_count, c.name as awarded_to, t.published_at, t.closes_at,
       t.procurement_method, t.award_amount, t.awarded_at, t.awarded_contractor_id as contractor_id
  from public.tenders t
  left join public.wards w on w.id = t.ward_id
  left join public.contractors c on c.id = t.awarded_contractor_id
 where t.status <> 'draft';

-- ---- flags that have been seen, and what the county said about them -----------------------------------------------------
create table public.procurement_flags (
  id            uuid primary key default gen_random_uuid(),
  code          text not null,
  subject_key   text not null,
  severity      text not null check (severity in ('info', 'watch', 'high')),
  subject_kind  text not null check (subject_kind in ('county', 'contractor', 'tender', 'project')),
  subject_label text not null,
  title         text not null,
  detail        text not null,
  metrics       jsonb not null default '{}'::jsonb,
  status        text not null default 'open' check (status in ('open', 'reviewing', 'explained', 'referred', 'cleared')),
  response      text,                                -- published beside the flag
  reviewed_by   uuid references auth.users (id),
  reviewed_at   timestamptz,
  first_seen    timestamptz not null default now(),
  last_seen     timestamptz not null default now(),
  unique (code, subject_key)
);
alter table public.procurement_flags enable row level security;
create policy "flags: staff read" on public.procurement_flags for select to authenticated using (private.is_staff());
grant select on public.procurement_flags to authenticated;
create trigger audit_procurement_flags after insert or update or delete on public.procurement_flags
  for each row execute function private.audit_row();

-- ---- the awarded tenders, one row each ------------------------------------------------------------------------------------
create function private.awards()
returns table (id uuid, reference text, title text, ward_id text, sector text, method text, bids int, estimate numeric,
               amount numeric, at timestamptz, published_at timestamptz, closes_at timestamptz,
               cid uuid, cname text, kra_compliant boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select t.id, t.reference, t.title, t.ward_id, t.sector, t.procurement_method, t.applicants_count, t.estimated_budget,
         coalesce(t.award_amount, t.estimated_budget), coalesce(t.awarded_at, t.published_at, t.created_at),
         t.published_at, t.closes_at, c.id, c.name, c.kra_compliant
    from public.tenders t
    join public.contractors c on c.id = t.awarded_contractor_id
   where t.status = 'awarded';
$$;

-- ---- the rules ------------------------------------------------------------------------------------------------------------------
-- Thresholds are deliberately plain and published on the Open County page. Money shown as whole shillings.
create function private.procurement_flags_now()
returns table (code text, severity text, subject_kind text, subject_key text, subject_label text, title text, detail text, metrics jsonb)
language sql
stable
security definer
set search_path = ''
as $$
  with aw as (select * from private.awards()),
  tot as (
    select count(*)::numeric as n, coalesce(sum(amount), 0) as v, count(distinct cid)::int as suppliers,
           coalesce(sum(amount) filter (where method in ('direct', 'restricted')), 0) as nc_value,
           count(*) filter (where bids <= 1) as single,
           count(*) filter (where published_at is not null and closes_at is not null and closes_at - published_at < interval '7 days') as short
      from aw
  ),
  per as (
    select cid, cname, count(*) as wins, sum(amount) as value,
           count(*) filter (where method in ('direct', 'restricted')) as non_open,
           count(*) filter (where bids <= 1) as single_bid,
           coalesce(bool_or(kra_compliant is false), false) as kra_bad
      from aw group by cid, cname
  ),
  shares as (
    select per.*, case when tot.v > 0 then round(100 * per.value / tot.v, 1) else 0 end as share_value,
           round(100 * per.wins / tot.n, 1) as share_count
      from per cross join tot
  ),
  ranked as (select s.*, row_number() over (order by s.value desc, s.cname) as rk from shares s),
  top3 as (select coalesce(sum(share_value), 0) as share from ranked where rk <= 3),
  anchor as (
    select a.id, a.cid, a.cname, a.ward_id, a.sector, count(b.id) as n
      from aw a
      join aw b on b.cid = a.cid and b.ward_id is not distinct from a.ward_id and b.sector = a.sector
               and b.at >= a.at and b.at < a.at + interval '30 days'
     group by a.id, a.cid, a.cname, a.ward_id, a.sector
  ),
  split as (select cid, cname, ward_id, sector, max(n) as n from anchor where n >= 3 group by cid, cname, ward_id, sector)

  select 'dominant_supplier', case when r.share_value >= 40 then 'high' else 'watch' end, 'contractor', r.cid::text, r.cname,
         format('%s holds %s%% of awarded value', r.cname, r.share_value),
         format('%s of %s awards, worth KES %s of the KES %s awarded in total. One supplier holding more than a quarter of awarded value is a common reason to look at how work is being shared.',
                r.wins, tot.n, to_char(r.value, 'FM999,999,999,990'), to_char(tot.v, 'FM999,999,999,990')),
         jsonb_build_object('wins', r.wins, 'value', r.value, 'share_value', r.share_value)
    from ranked r cross join tot where r.share_value >= 25 and r.wins >= 2
  union all
  select 'repeat_winner', 'watch', 'contractor', r.cid::text, r.cname,
         format('%s won %s awards, %s%% of all', r.cname, r.wins, r.share_count),
         'Winning four or more awards and a fifth of all awards can be entirely legitimate, and is also what repeated favouritism looks like. Worth checking that the tenders were genuinely competitive.',
         jsonb_build_object('wins', r.wins, 'share_count', r.share_count)
    from ranked r where r.wins >= 4 and r.share_count >= 20
  union all
  select 'top3_concentration', case when top3.share >= 75 then 'high' else 'watch' end, 'county', 'county', 'County procurement',
         format('Three suppliers hold %s%% of awarded value', top3.share),
         format('Across %s suppliers and KES %s awarded, the top three received %s%%. A market this concentrated leaves little competitive pressure on price and quality.',
                tot.suppliers, to_char(tot.v, 'FM999,999,999,990'), top3.share),
         jsonb_build_object('top3_share', top3.share, 'suppliers', tot.suppliers)
    from top3 cross join tot where tot.suppliers >= 4 and top3.share >= 60
  union all
  select 'non_competitive_share', case when tot.nc_value * 2 >= tot.v then 'high' else 'watch' end, 'county', 'county', 'County procurement',
         format('%s%% of awarded value skipped open tendering', round(100 * tot.nc_value / tot.v, 1)),
         format('KES %s was awarded by direct or restricted procurement. These methods have legitimate uses, such as emergencies, and should stay a small share.',
                to_char(tot.nc_value, 'FM999,999,999,990')),
         jsonb_build_object('non_competitive_value', tot.nc_value, 'share', round(100 * tot.nc_value / tot.v, 1))
    from tot where tot.v > 0 and tot.n >= 4 and tot.nc_value * 10 >= tot.v * 3
  union all
  select 'contractor_direct_reliance', 'watch', 'contractor', r.cid::text, r.cname,
         format('%s: %s of %s awards were not openly tendered', r.cname, r.non_open, r.wins),
         'Most of this supplier''s awards came through direct or restricted procurement rather than open competition.',
         jsonb_build_object('wins', r.wins, 'non_open', r.non_open)
    from ranked r where r.wins >= 2 and r.non_open * 10 >= r.wins * 6
  union all
  select 'single_bidder_share', 'watch', 'county', 'county', 'County procurement',
         format('%s%% of awarded tenders had one bidder or none', round(100 * tot.single / tot.n, 1)),
         'Tenders with a single bidder cannot show that the price was tested. Few bids is one of the most widely used procurement warning signs.',
         jsonb_build_object('single_bid', tot.single, 'awarded', tot.n)
    from tot where tot.n >= 4 and tot.single * 4 >= tot.n
  union all
  select 'contractor_single_bid', 'watch', 'contractor', r.cid::text, r.cname,
         format('%s won %s tenders with a single bidder', r.cname, r.single_bid),
         'Winning several tenders where nobody else bid deserves a look at how the tender was advertised and who could realistically apply.',
         jsonb_build_object('single_bid', r.single_bid)
    from ranked r where r.single_bid >= 2
  union all
  select 'short_tender_period', 'watch', 'county', 'county', 'County procurement',
         format('%s awarded tenders were open for under a week', tot.short),
         'Very short tendering periods limit who can respond in time and are a standard procurement warning sign.',
         jsonb_build_object('short_tenders', tot.short)
    from tot where tot.short >= 3 and tot.short * 5 >= tot.n
  union all
  select 'award_above_estimate', case when a.amount >= a.estimate * 1.3 then 'high' else 'watch' end, 'tender', a.id::text, a.reference || ' ' || a.title,
         format('%s was awarded at %s%% of its estimate', a.reference, round(100 * a.amount / a.estimate)),
         format('Estimate KES %s, award KES %s to %s. A large gap between estimate and award can mean a poor estimate or a price that was not tested.',
                to_char(a.estimate, 'FM999,999,999,990'), to_char(a.amount, 'FM999,999,999,990'), a.cname),
         jsonb_build_object('estimate', a.estimate, 'award', a.amount)
    from aw a where a.estimate > 0 and a.amount > a.estimate * 1.15
  union all
  select 'split_awards', 'watch', 'contractor', s.cid::text || ':' || coalesce(s.ward_id, '-') || ':' || s.sector, s.cname,
         format('%s received %s %s awards within 30 days%s', s.cname, s.n, s.sector, coalesce(' in ' || (select w.name from public.wards w where w.id = s.ward_id), '')),
         'Several awards to one supplier for the same kind of work in the same place in a short time can indicate a larger job split up to stay under a tendering threshold.',
         jsonb_build_object('awards', s.n)
    from split s
  union all
  select 'kra_noncompliant', 'watch', 'contractor', r.cid::text, r.cname,
         format('%s failed its last tax compliance check', r.cname),
         'The supplier holds county awards while its most recent KRA tax compliance check was negative. Public bodies are expected to award only to compliant suppliers.',
         jsonb_build_object('wins', r.wins)
    from ranked r where r.kra_bad
  union all
  select 'project_overrun', case when p.spent > p.budget * 1.25 then 'high' else 'watch' end, 'project', p.id::text, p.title,
         format('%s has spent %s%% of its budget', p.title, round(100 * p.spent / p.budget)),
         format('Budget KES %s, spent KES %s. Spending above budget should come with an approved variation and a public explanation.',
                to_char(p.budget, 'FM999,999,999,990'), to_char(p.spent, 'FM999,999,999,990')),
         jsonb_build_object('budget', p.budget, 'spent', p.spent)
    from public.projects p where p.published and p.budget > 0 and p.spent > p.budget * 1.1
  union all
  select 'stalled_after_spend', 'watch', 'project', p.id::text, p.title,
         format('%s is stalled after %s%% of its budget was spent', p.title, round(100 * p.spent / p.budget)),
         'Money has left but the work has stopped. Residents should be told why and when it will resume.',
         jsonb_build_object('budget', p.budget, 'spent', p.spent)
    from public.projects p where p.published and p.status = 'stalled' and p.budget > 0 and p.spent >= p.budget * 0.5
  union all
  select 'project_late', 'info', 'project', p.id::text, p.title,
         format('%s is %s days past its expected date', p.title, current_date - p.expected_at),
         'The project has not reached completion by the date the county published.',
         jsonb_build_object('expected_at', p.expected_at)
    from public.projects p where p.published and p.status in ('procurement', 'in_progress') and p.expected_at is not null and p.expected_at < current_date - 60;
$$;

-- ---- what the public page reads ------------------------------------------------------------------------------------------------
create function public.procurement_watch()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_summary jsonb;
  v_contractors jsonb;
  v_methods jsonb;
  v_flags jsonb;
begin
  with aw as (select * from private.awards()),
  tot as (select count(*)::numeric as n, coalesce(sum(amount), 0) as v, count(distinct cid)::int as suppliers,
                 coalesce(sum(amount) filter (where method in ('direct', 'restricted')), 0) as nc_value,
                 count(*) filter (where bids <= 1) as single,
                 round(avg(bids), 1) as avg_bids,
                 round(avg(extract(epoch from (closes_at - published_at)) / 86400) filter (where published_at is not null and closes_at is not null)::numeric, 1) as avg_days
            from aw),
  per as (select cid, sum(amount) as value from aw group by cid),
  sh as (select cid, case when tot.v > 0 then 100 * value / tot.v else 0 end as s from per cross join tot),
  rk as (select s, row_number() over (order by s desc) as r from sh)
  select jsonb_build_object(
           'awarded_count', tot.n, 'awarded_value', tot.v, 'suppliers', tot.suppliers,
           'hhi', (select coalesce(round(sum(s * s)), 0) from sh),
           'hhi_band', case when (select coalesce(sum(s * s), 0) from sh) >= 2500 then 'high'
                            when (select coalesce(sum(s * s), 0) from sh) >= 1500 then 'moderate' else 'low' end,
           'top1_share', (select coalesce(round(sum(s), 1), 0) from rk where r <= 1),
           'top3_share', (select coalesce(round(sum(s), 1), 0) from rk where r <= 3),
           'top5_share', (select coalesce(round(sum(s), 1), 0) from rk where r <= 5),
           'non_competitive_share', case when tot.v > 0 then round(100 * tot.nc_value / tot.v, 1) else 0 end,
           'single_bid_share', case when tot.n > 0 then round(100 * tot.single / tot.n, 1) else 0 end,
           'avg_bids', tot.avg_bids, 'avg_tender_days', tot.avg_days)
    into v_summary from tot;

  select coalesce(jsonb_agg(x order by (x ->> 'value')::numeric desc), '[]'::jsonb) into v_contractors from (
    select jsonb_build_object('id', a.cid, 'name', a.cname, 'wins', count(*), 'value', sum(a.amount),
             'share_value', case when t.v > 0 then round(100 * sum(a.amount) / t.v, 1) else 0 end,
             'share_count', round(100 * count(*)::numeric / t.n, 1),
             'non_open', count(*) filter (where a.method in ('direct', 'restricted')),
             'single_bid', count(*) filter (where a.bids <= 1),
             'last_award', max(a.at)) as x
      from private.awards() a
      cross join (select count(*)::numeric as n, coalesce(sum(amount), 0) as v from private.awards()) t
     group by a.cid, a.cname, t.n, t.v
     order by sum(a.amount) desc limit 15) q;

  select coalesce(jsonb_agg(jsonb_build_object('method', m.method, 'awards', m.awards, 'value', m.value) order by m.value desc), '[]'::jsonb) into v_methods from (
    select method, count(*) as awards, sum(amount) as value from private.awards() group by method) m;

  select coalesce(jsonb_agg(jsonb_build_object(
           'code', f.code, 'severity', f.severity, 'subject_kind', f.subject_kind, 'subject_key', f.subject_key,
           'subject_label', f.subject_label, 'title', f.title, 'detail', f.detail, 'metrics', f.metrics,
           'status', coalesce(s.status, 'open'), 'response', s.response, 'first_seen', s.first_seen)
           order by case f.severity when 'high' then 0 when 'watch' then 1 else 2 end, f.title), '[]'::jsonb)
    into v_flags
    from private.procurement_flags_now() f
    left join public.procurement_flags s on s.code = f.code and s.subject_key = f.subject_key;

  return jsonb_build_object('generated_at', now(), 'summary', v_summary, 'contractors', v_contractors, 'methods', v_methods, 'flags', v_flags);
end;
$$;
grant execute on function public.procurement_watch() to anon, authenticated;

-- ---- staff review: the response is public -----------------------------------------------------------------------------------
create function public.flag_review(p_code text, p_key text, p_status text, p_response text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.has_role(array['super_admin', 'admin']) then
    raise exception 'Only a county administrator can review a flag' using errcode = '42501';
  end if;
  if p_status not in ('open', 'reviewing', 'explained', 'referred') then
    raise exception 'Unknown status' using errcode = '22023';
  end if;
  if p_status in ('explained', 'referred') and length(trim(coalesce(p_response, ''))) < 10 then
    raise exception 'Write a short public response first' using errcode = '22023';
  end if;
  insert into public.procurement_flags (code, subject_key, severity, subject_kind, subject_label, title, detail, metrics)
  select f.code, f.subject_key, f.severity, f.subject_kind, f.subject_label, f.title, f.detail, f.metrics
    from private.procurement_flags_now() f where f.code = p_code and f.subject_key = p_key
  on conflict (code, subject_key) do nothing;
  update public.procurement_flags
     set status = p_status, response = nullif(trim(coalesce(p_response, '')), ''), reviewed_by = (select auth.uid()), reviewed_at = now()
   where code = p_code and subject_key = p_key;
  if not found then raise exception 'That flag no longer applies' using errcode = 'P0002'; end if;
end;
$$;
revoke all on function public.flag_review(text, text, text, text) from public, anon;
grant execute on function public.flag_review(text, text, text, text) to authenticated;

-- ---- the daily scan: remember flags, tell the right people about new serious ones -------------------------------------------
create function public.svc_procurement_scan()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  fl record;
  n_new int := 0;
  v_name text;
  v_url text;
begin
  select c.name, c.settings ->> 'console_url' into v_name, v_url from public.county c limit 1;
  for fl in select * from private.procurement_flags_now() loop
    if exists (select 1 from public.procurement_flags s where s.code = fl.code and s.subject_key = fl.subject_key) then
      update public.procurement_flags s
         set severity = fl.severity, title = fl.title, detail = fl.detail, metrics = fl.metrics, subject_label = fl.subject_label, last_seen = now(),
             status = case when s.status = 'cleared' then 'open' else s.status end
       where s.code = fl.code and s.subject_key = fl.subject_key;
    else
      insert into public.procurement_flags (code, subject_key, severity, subject_kind, subject_label, title, detail, metrics)
      values (fl.code, fl.subject_key, fl.severity, fl.subject_kind, fl.subject_label, fl.title, fl.detail, fl.metrics);
      n_new := n_new + 1;
      if fl.severity = 'high' then
        insert into private.outbox (channel, recipient, subject, body, related)
        select 'email', u.email, format('[%s] New procurement flag: %s', coalesce(v_name, 'County'), fl.title),
               format(E'A new high-priority pattern was found in county procurement:\n\n%s\n\n%s\n\nThis is a prompt for review, not a finding. Review it and publish a response: %s',
                      fl.title, fl.detail, coalesce(v_url, '') || '/procurement'),
               jsonb_build_object('flag', fl.code, 'subject', fl.subject_key)
          from (select distinct r.user_id from public.staff_roles r
                 where r.active and (r.expires_at is null or r.expires_at > now()) and r.role in ('super_admin', 'admin', 'auditor')) x
          join auth.users u on u.id = x.user_id and u.email is not null;
      end if;
    end if;
  end loop;
  -- a flag whose condition no longer holds is closed, unless someone has already reviewed it
  update public.procurement_flags s set status = 'cleared'
   where s.status = 'open'
     and not exists (select 1 from private.procurement_flags_now() f where f.code = s.code and f.subject_key = s.subject_key);
  return n_new;
end;
$$;
revoke all on function public.svc_procurement_scan() from public, anon, authenticated;
grant execute on function public.svc_procurement_scan() to service_role;

-- ---- the staff assistant can ask about it (runs as the person asking) ---------------------------------------------------------
create function public.ai_procurement_flags(p_min_severity text default 'watch')
returns table (severity text, subject text, title text, status text)
language sql
stable
set search_path = ''
as $$
  select f ->> 'severity', f ->> 'subject_label', f ->> 'title', f ->> 'status'
    from jsonb_array_elements(public.procurement_watch() -> 'flags') f
   where (f ->> 'severity') = any (case when p_min_severity = 'high' then array['high']
                                        when p_min_severity = 'info' then array['high', 'watch', 'info']
                                        else array['high', 'watch'] end)
   limit 50;
$$;
revoke all on function public.ai_procurement_flags(text) from public, anon;
grant execute on function public.ai_procurement_flags(text) to authenticated;

-- ==== 20260930001300_resident_loop.sql ====

-- The resident loop (migration 0013): "Was it fixed?" feedback and reopening, SMS when a case or application moves,
-- and verification codes for permits and receipts.

-- ---- "Was it fixed?" ----------------------------------------------------------------------------------------------

alter table public.reports add column reopened_count int not null default 0;

alter table public.report_events drop constraint report_events_kind_check;
alter table public.report_events add constraint report_events_kind_check
  check (kind in ('created', 'triaged', 'assigned', 'status', 'note', 'public_message', 'reminder', 'escalated', 'merged', 'feedback', 'reopened'));

create table public.case_feedback (
  id         uuid primary key default gen_random_uuid(),
  report_id  uuid not null references public.reports (id) on delete cascade,
  fixed      boolean not null,
  comment    text check (char_length(comment) <= 500),
  created_at timestamptz not null default now()
);
create index case_feedback_report_idx on public.case_feedback (report_id, created_at);
alter table public.case_feedback enable row level security;
-- No policies: nobody reads or writes this table directly. Staff see the totals below; the public sees the totals too.

-- Called only by the case-feedback Edge Function. 'ok' | 'not_found' | 'not_resolved' | 'duplicate'.
-- A "no, still not fixed" answer reopens the case, puts it back with its team and starts a new target.
create function public.svc_case_feedback(p_reference text, p_fixed boolean, p_comment text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r public.reports;
  v_comment text := nullif(left(trim(coalesce(p_comment, '')), 500), '');
begin
  select r.* into v_r from public.reports r where r.reference = upper(trim(p_reference)) for update;
  if not found then return 'not_found'; end if;
  if v_r.status not in ('resolved', 'closed') then return 'not_resolved'; end if;
  if exists (select 1 from public.case_feedback f where f.report_id = v_r.id and f.created_at >= coalesce(v_r.resolved_at, v_r.created_at)) then
    return 'duplicate';
  end if;

  insert into public.case_feedback (report_id, fixed, comment) values (v_r.id, p_fixed, v_comment);
  insert into public.report_events (report_id, kind, is_public, message, data)
  values (v_r.id, 'feedback', true,
          case when p_fixed then 'The resident confirmed it was fixed.' else 'The resident says it is not fixed.' end
            || coalesce(' "' || v_comment || '"', ''),
          jsonb_build_object('fixed', p_fixed));

  if not p_fixed then
    update public.reports
       set status = 'in_progress', resolved_at = null, reopened_count = reopened_count + 1,
           resolve_due_at = private.add_sla(now(), 72, 'hours'), escalation_level = 0, last_escalated_at = null
     where id = v_r.id;
    insert into public.report_events (report_id, kind, is_public, message, data)
    values (v_r.id, 'reopened', true, 'Reopened at the resident''s request.', jsonb_build_object('status', 'in_progress'));
  end if;
  return 'ok';
end;
$$;
revoke all on function public.svc_case_feedback(text, boolean, text) from public, anon, authenticated;

-- How often the county's "resolved" turns out to be true, county-wide and by ward. Public.
create function public.fix_confirmation_stats()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'responses', (select count(*) from public.case_feedback),
    'fixed', (select count(*) from public.case_feedback where fixed),
    'reopened', (select count(*) from public.case_feedback where not fixed),
    'by_ward', coalesce((
      select jsonb_agg(x order by x.responses desc, x.ward)
      from (
        select w.id as ward_id, w.name as ward, count(*) as responses, count(*) filter (where f.fixed) as fixed
        from public.case_feedback f
        join public.reports r on r.id = f.report_id
        join public.wards w on w.id = r.ward_id
        group by w.id, w.name
      ) x), '[]'::jsonb));
$$;
grant execute on function public.fix_confirmation_stats() to anon, authenticated;

-- The public status page now also says whether feedback has been given for the latest resolution.
create or replace function public.case_status(p_reference text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'reference', r.reference,
    'status', r.status,
    'category_id', r.category_id,
    'category', c.name,
    'category_sw', c.name_sw,
    'ward', w.name,
    'ward_id', r.ward_id,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'resolve_due_at', r.resolve_due_at,
    'project_slug', p.slug,
    'reopened_count', r.reopened_count,
    'feedback_given', exists (select 1 from public.case_feedback f where f.report_id = r.id and f.created_at >= coalesce(r.resolved_at, r.created_at) and r.status in ('resolved', 'closed')),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('kind', e.kind, 'message', e.message, 'at', e.created_at) order by e.created_at)
      from public.report_events e where e.report_id = r.id and e.is_public), '[]'::jsonb))
  from public.reports r
  join public.wards w on w.id = r.ward_id
  left join public.report_categories c on c.id = r.category_id
  left join public.projects p on p.id = r.project_id and p.published
  where r.reference = upper(trim(p_reference));
$$;

-- ---- SMS when a case moves ----------------------------------------------------------------------------------------
-- One rule for every path (staff action, escalation, reopening): a public timeline event reaches the reporter.

create function private.notify_report_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text;
  v_ref text;
  v_url text;
  v_line text;
begin
  if not new.is_public or new.kind not in ('status', 'public_message', 'reopened') then return new; end if;
  select c.phone_e164 into v_phone from private.report_contacts c where c.report_id = new.report_id;
  if v_phone is null then return new; end if;
  select r.reference into v_ref from public.reports r where r.id = new.report_id;
  select c.settings ->> 'web_url' into v_url from public.county c limit 1;
  v_line := case
    when new.kind = 'status' then initcap(replace(coalesce(new.data ->> 'status', 'updated'), '_', ' '))
    else null end;
  insert into private.outbox (channel, recipient, body, related)
  values ('sms', v_phone,
          'County update ' || v_ref || ': ' || coalesce(v_line, '') || case when v_line is not null and new.message is not null then ' - ' else '' end
            || coalesce(new.message, '') || case when v_url is not null then ' ' || v_url || '/case/' || v_ref else '' end,
          jsonb_build_object('report_id', new.report_id, 'event', new.kind));
  return new;
end;
$$;
create trigger report_events_notify after insert on public.report_events
  for each row execute function private.notify_report_event();

-- case_transition no longer sends its own SMS (the trigger above does, for every path).
create or replace function public.case_transition(
  p_report uuid,
  p_status text,
  p_message text default null,
  p_public boolean default false
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r public.reports;
begin
  if p_status not in ('triaged', 'assigned', 'in_progress', 'resolved', 'closed', 'rejected') then
    raise exception 'Invalid status %', p_status using errcode = '22023';
  end if;
  select r.* into v_r from public.reports r where r.id = p_report for update;
  if not found then raise exception 'Case not found' using errcode = 'P0002'; end if;
  if not private.can_work_case(v_r.ward_id, v_r.department_id, v_r.assigned_to) then
    raise exception 'Not allowed to work this case' using errcode = '42501';
  end if;

  update public.reports
     set status = p_status,
         acknowledged_at = coalesce(acknowledged_at, now()),
         resolved_at = case when p_status in ('resolved', 'closed') then coalesce(resolved_at, now()) else resolved_at end
   where id = p_report;

  insert into public.report_events (report_id, kind, actor_id, is_public, message, data)
  values (p_report, 'status', (select auth.uid()), p_public, p_message, jsonb_build_object('status', p_status));
end;
$$;

-- ---- permits and receipts you can check ---------------------------------------------------------------------------

alter table public.applications
  add column verify_code text unique,
  add column revoked_at timestamptz,
  add column revoked_reason text;

-- Short, readable, no look-alike characters: CY-XXXX-XXXX.
create function private.new_verify_code()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_code text;
  v_bytes bytea;
begin
  loop
    v_bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    v_code := 'CY-' || (select string_agg(substr(alphabet, 1 + (get_byte(v_bytes, i) % 31), 1), '' order by i) from generate_series(0, 3) i)
              || '-' || (select string_agg(substr(alphabet, 1 + (get_byte(v_bytes, i) % 31), 1), '' order by i) from generate_series(4, 7) i);
    exit when not exists (select 1 from public.applications a where a.verify_code = v_code);
  end loop;
  return v_code;
end;
$$;

create function private.applications_verify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and not private.is_staff()
     and (new.verify_code is distinct from old.verify_code or new.revoked_at is distinct from old.revoked_at or new.revoked_reason is distinct from old.revoked_reason) then
    raise exception 'Protected application fields cannot be changed' using errcode = '42501';
  end if;
  if new.status = 'approved' and old.status is distinct from 'approved' and new.verify_code is null then
    new.verify_code := private.new_verify_code();
  end if;
  return new;
end;
$$;
create trigger applications_verify before update on public.applications
  for each row execute function private.applications_verify();

-- Anyone holding a code (printed on a permit or receipt, or scanned from its QR) can check it. Reveals only what is
-- printed on the document: no ID numbers, no phone numbers.
create function public.verify_document(p_code text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_code text := upper(trim(coalesce(p_code, '')));
  v_a record;
  v_p record;
begin
  if char_length(v_code) < 6 or char_length(v_code) > 40 then return jsonb_build_object('valid', false, 'kind', null); end if;

  select a.reference, a.business_name, a.decided_at, a.revoked_at, a.revoked_reason, a.status, s.name as service, w.name as ward
    into v_a
    from public.applications a
    join public.services s on s.id = a.service_id
    left join public.wards w on w.id = a.ward_id
   where a.verify_code = v_code;
  if found then
    return jsonb_build_object(
      'kind', 'permit',
      'valid', v_a.status = 'approved' and v_a.revoked_at is null,
      'state', case when v_a.revoked_at is not null then 'revoked' when v_a.status = 'approved' then 'valid' else 'not_valid' end,
      'service', v_a.service, 'holder', v_a.business_name, 'ward', v_a.ward, 'issued_at', v_a.decided_at,
      'reference', v_a.reference, 'revoked_at', v_a.revoked_at, 'revoked_reason', v_a.revoked_reason);
  end if;

  select p.mpesa_receipt, p.amount, p.stream, p.completed_at, p.status into v_p
    from public.payments p where p.mpesa_receipt = v_code;
  if found then
    return jsonb_build_object(
      'kind', 'receipt', 'valid', v_p.status = 'completed', 'state', case when v_p.status = 'completed' then 'valid' else 'not_valid' end,
      'amount', v_p.amount, 'stream', v_p.stream, 'issued_at', v_p.completed_at, 'reference', v_p.mpesa_receipt);
  end if;

  return jsonb_build_object('valid', false, 'kind', null, 'state', 'unknown');
end;
$$;
grant execute on function public.verify_document(text) to anon, authenticated;

-- An administrator can withdraw a permit (fraud, error). The holder is told and the code then reads "revoked".
create function public.revoke_document(p_application uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_a public.applications;
begin
  if not private.is_admin() then raise exception 'Only an administrator can revoke a permit' using errcode = '42501'; end if;
  if char_length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'Say why' using errcode = '22023'; end if;
  select a.* into v_a from public.applications a where a.id = p_application for update;
  if not found or v_a.verify_code is null then raise exception 'No issued permit' using errcode = 'P0002'; end if;
  update public.applications set revoked_at = now(), revoked_reason = trim(p_reason) where id = p_application;
  insert into public.notifications (user_id, title, message, kind, link)
  values (v_a.applicant_id, 'Permit ' || v_a.reference, 'This permit was withdrawn: ' || trim(p_reason), 'error', '/services/applications/' || v_a.id);
end;
$$;
grant execute on function public.revoke_document(uuid, text) to authenticated;

-- ---- SMS when an application moves --------------------------------------------------------------------------------

create function private.notify_application_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text;
  v_url text;
  v_text text;
begin
  v_text := case new.status
    when 'approved' then 'approved. Verify it with code ' || coalesce(new.verify_code, '')
    when 'rejected' then 'not approved' || coalesce(': ' || new.decision_note, '')
    when 'changes_requested' then 'waiting for changes' || coalesce(': ' || new.decision_note, '')
    when 'under_review' then 'under review'
    else null end;
  if v_text is null then return new; end if;
  select p.phone into v_phone from public.profiles p where p.id = new.applicant_id;
  if v_phone is null or v_phone !~ '^\+[1-9][0-9]{7,14}$' then return new; end if;
  select c.settings ->> 'web_url' into v_url from public.county c limit 1;
  insert into private.outbox (channel, recipient, body, related)
  values ('sms', v_phone, 'County application ' || new.reference || ' is ' || v_text || case when v_url is not null then '. ' || v_url || '/services/applications/' || new.id else '' end,
          jsonb_build_object('application_id', new.id));
  return new;
end;
$$;
create trigger applications_notify after update of status on public.applications
  for each row when (old.status is distinct from new.status) execute function private.notify_application_change();

-- ==== 20260930001400_participation_and_follows.sql ====

-- 0014  Ward budget results and quarterly rounds, and following a supplier, a project or a place.

-- ---- what the ward decided ----------------------------------------------------------------------------------------
-- Every option in a round with its votes, and a running total in vote order within its ward: an option is funded while
-- the running total stays inside the ward's envelope.
create function private.option_tally(p_cycle text)
returns table (ward_id text, id text, title text, sector text, amount numeric, votes bigint, running numeric)
language sql
stable
security definer
set search_path = ''
as $$
  select x.ward_id, x.id, x.title, x.sector, x.amount, x.votes,
         sum(x.amount) over (partition by x.ward_id order by x.votes desc, x.title, x.id) as running
    from (
      select o.ward_id, o.id, o.title, o.sector, o.amount,
             (select count(*) from public.votes v where v.option_id = o.id) as votes
        from public.project_options o where o.cycle_id = p_cycle
    ) x;
$$;

create function private.published_cycles()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'title', c.title) order by c.ends_at desc), '[]'::jsonb)
    from public.budget_cycles c where c.published_results and c.status <> 'draft';
$$;

-- Published results for one round (the latest one when none is named). Only rounds staff have published are visible.
create function public.budget_results(p_cycle text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_c public.budget_cycles;
begin
  if p_cycle is null then
    select c.* into v_c from public.budget_cycles c where c.published_results and c.status <> 'draft' order by c.ends_at desc limit 1;
  else
    select c.* into v_c from public.budget_cycles c where c.id = p_cycle and c.published_results and c.status <> 'draft';
  end if;
  if not found then return jsonb_build_object('cycle', null, 'wards', '[]'::jsonb, 'cycles', private.published_cycles()); end if;

  return jsonb_build_object(
    'cycle', jsonb_build_object('id', v_c.id, 'title', v_c.title, 'starts_at', v_c.starts_at, 'ends_at', v_c.ends_at, 'status', v_c.status),
    'cycles', private.published_cycles(),
    'total_votes', (select count(*) from public.votes v where v.cycle_id = v_c.id),
    'wards', coalesce((
      select jsonb_agg(jsonb_build_object(
               'ward_id', w.id, 'ward', w.name,
               'envelope', coalesce(e.amount, 0),
               'votes', (select coalesce(sum(t.votes), 0) from private.option_tally(v_c.id) t where t.ward_id = w.id),
               'options', (select jsonb_agg(jsonb_build_object(
                             'id', t.id, 'title', t.title, 'sector', t.sector, 'amount', t.amount, 'votes', t.votes,
                             'funded', t.running <= coalesce(e.amount, 0)) order by t.votes desc, t.title)
                           from private.option_tally(v_c.id) t where t.ward_id = w.id))
             order by w.name)
      from public.wards w
      left join public.ward_budget_envelopes e on e.cycle_id = v_c.id and e.ward_id = w.id
      where exists (select 1 from public.project_options o where o.cycle_id = v_c.id and o.ward_id = w.id)
    ), '[]'::jsonb));
end;
$$;
grant execute on function public.budget_results(text) to anon, authenticated;

-- ---- a round every quarter ----------------------------------------------------------------------------------------
-- Draft the next quarter's round: same ward envelopes as the latest round, no options yet (wards propose those), voting
-- for the first two weeks of the quarter. Idempotent per quarter. Returns the round id, or null if it already exists.
create function private.draft_quarterly_round()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_start date := (date_trunc('quarter', now() + interval '3 months'))::date;
  v_id text := to_char(v_start, 'YYYY') || '-q' || to_char(v_start, 'Q');
  v_prev text;
begin
  if exists (select 1 from public.budget_cycles c where c.id = v_id) then return null; end if;
  select c.id into v_prev from public.budget_cycles c
   where exists (select 1 from public.ward_budget_envelopes e where e.cycle_id = c.id) order by c.ends_at desc limit 1;
  insert into public.budget_cycles (id, title, status, starts_at, ends_at, published_results)
  values (v_id, 'Ward budget, ' || to_char(v_start, 'YYYY') || ' quarter ' || to_char(v_start, 'Q'), 'draft',
          v_start::timestamptz, (v_start + 14)::timestamptz, false);
  if v_prev is not null then
    insert into public.ward_budget_envelopes (cycle_id, ward_id, amount)
    select v_id, e.ward_id, e.amount from public.ward_budget_envelopes e where e.cycle_id = v_prev;
  end if;
  return v_id;
end;
$$;

-- Daily: rounds open on their start date and close on their end date; the next quarter's draft appears in the last
-- month of a quarter. Publishing results stays a human decision.
create function public.svc_round_scheduler()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_opened int;
  v_closed int;
  v_drafted text;
begin
  update public.budget_cycles set status = 'closed' where status = 'open' and ends_at < now();
  get diagnostics v_closed = row_count;
  update public.budget_cycles set status = 'open' where status = 'draft' and starts_at <= now() and ends_at > now()
     and exists (select 1 from public.project_options o where o.cycle_id = budget_cycles.id);
  get diagnostics v_opened = row_count;
  if extract(month from now())::int % 3 = 0 then v_drafted := private.draft_quarterly_round(); end if;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed, 'drafted', v_drafted);
end;
$$;
revoke all on function public.svc_round_scheduler() from public, anon, authenticated;
grant execute on function public.svc_round_scheduler() to service_role;

-- The same drafting, on demand, for an administrator.
create function public.draft_next_round()
returns text
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_admin() then raise exception 'Only an administrator can schedule a round' using errcode = '42501'; end if;
  return private.draft_quarterly_round();
end;
$$;
grant execute on function public.draft_next_round() to authenticated;

-- ---- follow a supplier, a project or a place -----------------------------------------------------------------------
create table public.follows (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  kind       text not null check (kind in ('supplier', 'project', 'ward_tenders', 'sector')),
  key        text not null check (char_length(key) between 1 and 80),
  label      text not null check (char_length(label) between 1 and 160),
  created_at timestamptz not null default now(),
  unique (user_id, kind, key)
);
create index follows_lookup_idx on public.follows (kind, key);
alter table public.follows enable row level security;
create policy "follows: own" on public.follows for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant select, insert, delete on public.follows to authenticated;

create function private.follows_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select count(*) from public.follows f where f.user_id = new.user_id) >= 40 then
    raise exception 'You can follow up to 40 things' using errcode = '54000';
  end if;
  return new;
end;
$$;
create trigger follows_limit before insert on public.follows for each row execute function private.follows_limit();

create function private.tell_followers(p_kind text, p_key text, p_title text, p_message text, p_link text, p_tone text default 'info')
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, title, message, kind, link)
  select f.user_id, p_title, p_message, p_tone, p_link from public.follows f where f.kind = p_kind and f.key = p_key;
$$;

-- New tenders, awards and status changes reach the people who follow that place, sector or supplier.
create function private.follows_on_tender()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_link text := '/tenders';
  v_name text;
begin
  if new.status = 'open' and (tg_op = 'INSERT' or old.status is distinct from 'open') then
    if new.ward_id is not null then
      perform private.tell_followers('ward_tenders', new.ward_id, 'New tender in your ward', new.reference || ': ' || new.title, v_link);
    end if;
    perform private.tell_followers('sector', lower(new.sector), 'New ' || new.sector || ' tender', new.reference || ': ' || new.title, v_link);
  elsif new.status = 'awarded' and (tg_op = 'INSERT' or old.status is distinct from 'awarded') then
    select c.name into v_name from public.contractors c where c.id = new.awarded_contractor_id;
    if new.awarded_contractor_id is not null then
      perform private.tell_followers('supplier', new.awarded_contractor_id::text, coalesce(v_name, 'A supplier you follow') || ' won a tender',
                                     new.reference || ': ' || new.title, v_link);
    end if;
    if new.ward_id is not null then
      perform private.tell_followers('ward_tenders', new.ward_id, 'Tender awarded in your ward',
                                     new.reference || ' went to ' || coalesce(v_name, 'a supplier'), v_link);
    end if;
  end if;
  return new;
end;
$$;
create trigger tenders_follows after insert or update of status on public.tenders
  for each row execute function private.follows_on_tender();

create function private.follows_on_project()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.published and (old.status is distinct from new.status or old.spent is distinct from new.spent and new.spent > old.spent) then
    perform private.tell_followers('project', new.id::text, new.title,
      case when old.status is distinct from new.status then 'Now ' || replace(new.status, '_', ' ') || '.' else 'Spending updated.' end,
      '/projects/' || new.slug,
      case when new.status = 'stalled' then 'warning' when new.status = 'completed' then 'success' else 'info' end);
  end if;
  return new;
end;
$$;
create trigger projects_follows after update on public.projects
  for each row execute function private.follows_on_project();

-- A new red flag reaches followers of the supplier or project it names.
create function private.follows_on_flag()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.severity = 'info' then return new; end if;
  if new.subject_kind = 'contractor' then
    perform private.tell_followers('supplier', split_part(new.subject_key, ':', 1), 'New flag on ' || new.subject_label, new.title, '/open', 'warning');
  elsif new.subject_kind = 'project' then
    perform private.tell_followers('project', new.subject_key, 'New flag on ' || new.subject_label, new.title, '/open', 'warning');
  end if;
  return new;
end;
$$;
create trigger flags_follows after insert on public.procurement_flags
  for each row execute function private.follows_on_flag();

-- ==== 20260930001500_open_data.sql ====

-- 0015  Views for County Assembly committees and ward scorecards, and open contracting data for researchers.
-- All of it is aggregate or already-public information; nothing here exposes a resident.

-- ---- committees ---------------------------------------------------------------------------------------------------
-- A committee oversees departments (for cases) and sectors (for projects and tenders). Editable by administrators.
create table public.assembly_committees (
  code         text primary key,
  name         text not null,
  name_sw      text,
  departments  text[] not null default '{}',   -- departments.code
  sectors      text[] not null default '{}',   -- lower-case sector names used on projects and tenders
  sort         int not null default 0
);
alter table public.assembly_committees enable row level security;
create policy "committees: public read" on public.assembly_committees for select to anon, authenticated using (true);
create policy "committees: admin write" on public.assembly_committees for all to authenticated using (private.is_admin()) with check (private.is_admin());
grant select on public.assembly_committees to anon, authenticated;
grant insert, update, delete on public.assembly_committees to authenticated;
create trigger audit_assembly_committees after insert or update or delete on public.assembly_committees
  for each row execute function private.audit_row();

insert into public.assembly_committees (code, name, name_sw, departments, sectors, sort) values
  ('roads',       'Roads, Transport and Public Works',   'Barabara, Uchukuzi na Kazi za Umma',   '{roads}',                 '{roads,transport,public works}', 1),
  ('water',       'Water, Environment and Sanitation',   'Maji, Mazingira na Usafi',             '{water,environment}',     '{water,sanitation,drainage,environment,waste}', 2),
  ('health',      'Health',                              'Afya',                                 '{health}',                '{health}', 3),
  ('education',   'Education and Social Services',       'Elimu na Huduma za Jamii',             '{education}',             '{education,social}', 4),
  ('trade',       'Trade, Markets and Licensing',        'Biashara, Masoko na Leseni',           '{trade}',                 '{markets,trade}', 5),
  ('planning',    'Planning, Lands and Housing',         'Mipango, Ardhi na Makazi',             '{planning}',              '{planning,housing,lands}', 6),
  ('safety',      'Public Safety and Disaster',          'Usalama wa Umma na Maafa',             '{safety}',                '{safety,disaster}', 7),
  ('finance',     'Finance and Budget',                  'Fedha na Bajeti',                      '{finance,integrity}',     '{finance}', 8);

-- One payload for every committee: what residents reported in its area and how the county responded, the projects and
-- tenders in its sectors, and open procurement flags on them. Last 90 days for cases.
create function public.assembly_dashboard()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'code', c.code, 'name', c.name, 'name_sw', c.name_sw,
    'cases', (
      select jsonb_build_object(
        'received_90d', count(*) filter (where r.created_at >= now() - interval '90 days'),
        'open', count(*) filter (where r.status not in ('resolved', 'closed', 'rejected')),
        'overdue', count(*) filter (where r.status not in ('resolved', 'closed', 'rejected') and r.resolve_due_at < now()),
        'resolved_90d', count(*) filter (where r.status in ('resolved', 'closed') and r.resolved_at >= now() - interval '90 days'),
        'reopened', coalesce(sum(r.reopened_count), 0),
        'median_days', round((percentile_cont(0.5) within group (order by extract(epoch from (r.resolved_at - r.created_at)) / 86400)
                              filter (where r.resolved_at >= now() - interval '90 days'))::numeric, 1))
      from public.reports r join public.departments d on d.id = r.department_id where d.code = any (c.departments)),
    'projects', (
      select jsonb_build_object('count', count(*), 'budget', coalesce(sum(p.budget), 0), 'spent', coalesce(sum(p.spent), 0),
                                'stalled', count(*) filter (where p.status = 'stalled'),
                                'completed', count(*) filter (where p.status = 'completed'))
      from public.projects p where p.published and lower(p.sector) = any (c.sectors)),
    'tenders', (
      select jsonb_build_object('open', count(*) filter (where t.status = 'open'),
                                'awarded', count(*) filter (where t.status = 'awarded'),
                                'awarded_value', coalesce(sum(coalesce(t.award_amount, t.estimated_budget)) filter (where t.status = 'awarded'), 0))
      from public.tenders t where lower(t.sector) = any (c.sectors)),
    'flags', (
      select count(*) from public.procurement_flags f
       where f.status <> 'cleared' and f.severity <> 'info'
         and ((f.subject_kind = 'project' and exists (select 1 from public.projects p where p.id::text = f.subject_key and lower(p.sector) = any (c.sectors)))
           or (f.subject_kind = 'tender' and exists (select 1 from public.tenders t where t.id::text = f.subject_key and lower(t.sector) = any (c.sectors))))),
    'attention', (
      select coalesce(jsonb_agg(jsonb_build_object('slug', p.slug, 'title', p.title, 'status', p.status, 'budget', p.budget, 'spent', p.spent) order by p.spent desc), '[]'::jsonb)
      from (select * from public.projects p2 where p2.published and lower(p2.sector) = any (c.sectors) and (p2.status = 'stalled' or p2.spent > p2.budget)
             order by p2.spent desc limit 5) p)
  ) order by c.sort), '[]'::jsonb)
  from public.assembly_committees c;
$$;
grant execute on function public.assembly_dashboard() to anon, authenticated;

-- ---- ward scorecard -----------------------------------------------------------------------------------------------
-- What one ward can hold its representatives to: how quickly problems are fixed and whether residents agree they were
-- fixed, what is being built and spent, what was tendered, and how many people took part in the budget vote.
create function public.ward_scorecard(p_ward text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'ward_id', w.id, 'ward', w.name, 'constituency', w.constituency, 'population', w.population,
    'sub_county', (select s.name from public.sub_counties s where s.id = w.sub_county_id),
    'generated_at', now(),
    'cases', (
      select jsonb_build_object(
        'received_90d', count(*) filter (where r.created_at >= now() - interval '90 days'),
        'resolved_90d', count(*) filter (where r.status in ('resolved', 'closed') and r.resolved_at >= now() - interval '90 days'),
        'open', count(*) filter (where r.status not in ('resolved', 'closed', 'rejected')),
        'overdue', count(*) filter (where r.status not in ('resolved', 'closed', 'rejected') and r.resolve_due_at < now()),
        'median_days', round((percentile_cont(0.5) within group (order by extract(epoch from (r.resolved_at - r.created_at)) / 86400)
                              filter (where r.resolved_at >= now() - interval '90 days'))::numeric, 1),
        'reopened', coalesce(sum(r.reopened_count), 0))
      from public.reports r where r.ward_id = w.id),
    'confirmed', (
      select jsonb_build_object('responses', count(*), 'fixed', count(*) filter (where f.fixed))
      from public.case_feedback f join public.reports r on r.id = f.report_id where r.ward_id = w.id),
    'top_categories', (
      select coalesce(jsonb_agg(x order by (x ->> 'count')::int desc), '[]'::jsonb) from (
        select jsonb_build_object('category', coalesce(c.name, 'Other'), 'category_sw', c.name_sw, 'count', count(*)) as x
          from public.reports r left join public.report_categories c on c.id = r.category_id
         where r.ward_id = w.id and r.created_at >= now() - interval '90 days'
         group by c.name, c.name_sw order by count(*) desc limit 4) t),
    'projects', (
      select jsonb_build_object('count', count(*), 'budget', coalesce(sum(p.budget), 0), 'spent', coalesce(sum(p.spent), 0),
                                'stalled', count(*) filter (where p.status = 'stalled'),
                                'completed', count(*) filter (where p.status = 'completed'))
      from public.projects p where p.ward_id = w.id and p.published),
    'tenders', (
      select jsonb_build_object('open', count(*) filter (where t.status = 'open'), 'awarded', count(*) filter (where t.status = 'awarded'),
                                'awarded_value', coalesce(sum(coalesce(t.award_amount, t.estimated_budget)) filter (where t.status = 'awarded'), 0))
      from public.tenders t where t.ward_id = w.id and t.status <> 'draft'),
    'budget', (
      select jsonb_build_object('cycle', c.title, 'votes', (select count(*) from public.votes v where v.cycle_id = c.id and v.ward_id = w.id),
                                'envelope', (select e.amount from public.ward_budget_envelopes e where e.cycle_id = c.id and e.ward_id = w.id))
      from public.budget_cycles c where c.status <> 'draft' order by c.ends_at desc limit 1)
  )
  from public.wards w where w.id = p_ward;
$$;
grant execute on function public.ward_scorecard(text) to anon, authenticated;

-- ---- open contracting data ----------------------------------------------------------------------------------------
-- Tenders and awards as an Open Contracting Data Standard release package (https://standard.open-contracting.org),
-- so journalists and researchers can load the county's data into the same tools used for other governments.
create function public.ocds_releases(p_limit int default 100, p_offset int default 0)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'uri', coalesce((select c.settings ->> 'web_url' from public.county c limit 1), '') || '/open/api',
    'version', '1.1',
    'publishedDate', now(),
    'publisher', jsonb_build_object('name', coalesce((select c.name from public.county c limit 1), 'County') || ' County Government'),
    'license', 'https://creativecommons.org/licenses/by/4.0/',
    'releases', coalesce((
      select jsonb_agg(r order by r ->> 'date' desc) from (
        select jsonb_strip_nulls(jsonb_build_object(
          'ocid', 'ocds-ke-' || lower(coalesce((select c.slug from public.county c limit 1), 'county')) || '-' || lower(t.reference),
          'id', t.id::text || '-' || t.status,
          'date', coalesce(t.awarded_at, t.published_at, t.created_at),
          'tag', jsonb_build_array(case t.status when 'awarded' then 'award' when 'cancelled' then 'tenderCancellation' else 'tender' end),
          'initiationType', 'tender',
          'language', 'en',
          'buyer', jsonb_build_object('name', coalesce((select c.name from public.county c limit 1), 'County') || ' County Government'),
          'tender', jsonb_build_object(
            'id', t.reference, 'title', t.title,
            'status', case t.status when 'open' then 'active' when 'evaluating' then 'active' when 'awarded' then 'complete' when 'cancelled' then 'cancelled' else 'planned' end,
            'value', jsonb_build_object('amount', t.estimated_budget, 'currency', 'KES'),
            'procurementMethod', case t.procurement_method when 'open_tender' then 'open' when 'restricted' then 'selective' else 'limited' end,
            'procurementMethodDetails', t.procurement_method,
            'mainProcurementCategory', lower(t.sector),
            'numberOfTenderers', t.applicants_count,
            'tenderPeriod', jsonb_build_object('startDate', t.published_at, 'endDate', t.closes_at),
            'deliveryAddresses', case when t.ward_id is null then null else jsonb_build_array(jsonb_build_object('region', t.ward_id)) end),
          'awards', case when t.status = 'awarded' and t.awarded_contractor_id is not null then jsonb_build_array(jsonb_build_object(
            'id', t.reference || '-award', 'status', 'active', 'date', t.awarded_at,
            'value', jsonb_build_object('amount', coalesce(t.award_amount, t.estimated_budget), 'currency', 'KES'),
            'suppliers', jsonb_build_array(jsonb_build_object('id', t.awarded_contractor_id::text, 'name', c.name)))) else null end
        )) as r
        from public.tenders t
        left join public.contractors c on c.id = t.awarded_contractor_id
        where t.status <> 'draft'
        order by coalesce(t.awarded_at, t.published_at, t.created_at) desc
        limit least(greatest(coalesce(p_limit, 100), 1), 500) offset greatest(coalesce(p_offset, 0), 0)
      ) x), '[]'::jsonb));
$$;
grant execute on function public.ocds_releases(int, int) to anon, authenticated;

-- ==== 20260930001600_advisor_fixes.sql ====

-- 0016  Clear the Supabase security and performance advisor findings, without changing who can see or do what.
--
-- 1. The public statistics views (public_ward_stats and friends) deliberately run with their owner's rights: they show
--    counts and totals from tables residents cannot read row by row. They now live in the `internal` schema, which the
--    API does not expose, and `public` keeps a thin SECURITY INVOKER view of the same name on top. Same data, same
--    names for the app, and no owner-rights view in the exposed schema.
-- 2. The same for the API functions that run as their owner (case_status, decide_application, grant_staff_role ...):
--    each body moves to `internal` unchanged, with every permission check it had, and `public` keeps a SECURITY INVOKER
--    wrapper with the same name, arguments and grants. auth.uid() still identifies the caller inside.
-- 3. Tables that nobody reads directly (votes, case_feedback, ...) get an explicit "no direct access" policy.
-- 4. Write policies that also covered SELECT are split into insert / update / delete, so each read is checked once.
-- 5. private.audit_immutable gets a fixed search_path; pg_net moves out of the public schema.

create schema if not exists internal;
revoke all on schema internal from public;
grant usage on schema internal to anon, authenticated, service_role;

-- ---- 1. statistics views ------------------------------------------------------------------------------------------
do $$
declare
  v text;
begin
  foreach v in array array['public_county_summary', 'public_overdue_counts', 'public_projects', 'public_report_aggregates',
                           'public_tenders', 'public_vote_tally', 'public_ward_stats'] loop
    if exists (select 1 from pg_views where schemaname = 'public' and viewname = v) then
      execute format('alter view public.%I set schema internal', v);
      execute format('create view public.%I with (security_invoker = true) as select * from internal.%I', v, v);
      execute format('grant select on internal.%I to anon, authenticated', v);
      execute format('grant select on public.%I to anon, authenticated', v);
    end if;
  end loop;
end;
$$;

-- ---- 2. owner-rights API functions --------------------------------------------------------------------------------
do $$
declare
  f record;
  call_args text;
  body text;
  role_name text;
begin
  for f in
    select p.oid, p.proname, p.provolatile, p.proretset, p.prorettype,
           pg_get_function_arguments(p.oid) as args,
           pg_get_function_identity_arguments(p.oid) as ident,
           pg_get_function_result(p.oid) as result,
           p.proargnames, p.proargmodes, p.pronargs
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.prosecdef
       and p.prokind = 'f'
       and p.prorettype <> 'trigger'::regtype
       and p.proname not like 'svc\_%'
       and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'))
  loop
    -- named arguments, so defaults keep working through the wrapper
    select coalesce(string_agg(format('%1$I => %1$I', a.name), ', ' order by a.i), '')
      into call_args
      from unnest(f.proargnames[1:f.pronargs]) with ordinality as a(name, i);

    execute format('alter function public.%I(%s) set schema internal', f.proname, f.ident);

    body := case
      when f.prorettype = 'void'::regtype then format('select internal.%I(%s)', f.proname, call_args)
      when f.proretset then format('select * from internal.%I(%s)', f.proname, call_args)
      else format('select internal.%I(%s)', f.proname, call_args)
    end;

    execute format(
      'create function public.%I(%s) returns %s language sql %s security invoker set search_path = '''' as %L',
      f.proname, f.args, f.result,
      case f.provolatile when 's' then 'stable' when 'i' then 'immutable' else 'volatile' end,
      body);

    execute format('revoke all on function public.%I(%s) from public', f.proname, f.ident);
    foreach role_name in array array['anon', 'authenticated'] loop
      if has_function_privilege(role_name, f.oid, 'execute') then  -- the moved function keeps its oid and grants
        execute format('grant execute on function public.%I(%s) to %I', f.proname, f.ident, role_name);
      end if;
    end loop;
    execute format('grant execute on function public.%I(%s) to service_role', f.proname, f.ident);
  end loop;
end;
$$;

-- ---- 3. tables only the database itself touches -------------------------------------------------------------------
do $$
declare
  t text;
begin
  for t in
    select c.relname
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity
       and not exists (select 1 from pg_policy p where p.polrelid = c.oid)
  loop
    execute format('create policy "no direct access" on public.%I for select to anon, authenticated using (false)', t);
  end loop;
end;
$$;

-- ---- 4. one policy per action ---------------------------------------------------------------------------------------
-- A FOR ALL write policy also applies to SELECT, so tables with a separate read policy evaluated two policies on
-- every read. Each FOR ALL policy on such a table becomes insert / update / delete with the same conditions.
do $$
declare
  p record;
  roles text;
begin
  for p in
    select pol.tablename, pol.policyname, pol.roles, pol.qual, pol.with_check
      from pg_policies pol
     where pol.schemaname = 'public' and pol.cmd = 'ALL'
       and exists (select 1 from pg_policies r
                    where r.schemaname = 'public' and r.tablename = pol.tablename
                      and r.cmd = 'SELECT' and r.roles && pol.roles)
  loop
    select string_agg(quote_ident(r), ', ') into roles from unnest(p.roles) r;
    execute format('drop policy %I on public.%I', p.policyname, p.tablename);
    execute format('create policy %I on public.%I for insert to %s with check (%s)',
                   p.policyname || ' (insert)', p.tablename, roles, coalesce(p.with_check, p.qual));
    execute format('create policy %I on public.%I for update to %s using (%s) with check (%s)',
                   p.policyname || ' (update)', p.tablename, roles, p.qual, coalesce(p.with_check, p.qual));
    execute format('create policy %I on public.%I for delete to %s using (%s)',
                   p.policyname || ' (delete)', p.tablename, roles, p.qual);
  end loop;
end;
$$;

-- ---- 5. small ones ----------------------------------------------------------------------------------------------------
alter function private.audit_immutable() set search_path = '';

-- pg_net keeps its functions in the `net` schema wherever the extension itself is registered, so moving the
-- registration changes nothing for the scheduled jobs. Only on a live project (tests have no pg_net).
do $$
begin
  if exists (select 1 from pg_extension e join pg_namespace n on n.oid = e.extnamespace
              where e.extname = 'pg_net' and n.nspname = 'public') then
    drop extension pg_net;
    create extension pg_net with schema extensions;
  end if;
end;
$$;

-- ==== 20260930001700_metoo_and_meetings.sql ====

-- 0017  "Me too" on open reports, and the public participation calendar.

-- ---- me too -----------------------------------------------------------------------------------------------------------
-- A neighbour who has the same problem adds their voice instead of filing a duplicate. Only a keyed hash of who they
-- are is kept (the same kind of hash as a vote), one per person per report. Ten or more voices raise the priority.
alter table public.reports add column supporters int not null default 0;

create table private.report_supporters (
  report_id      uuid not null references public.reports (id) on delete cascade,
  supporter_hash bytea not null,
  created_at     timestamptz not null default now(),
  primary key (report_id, supporter_hash)
);

-- Called only by the case-feedback Edge Function. 'ok' | 'duplicate' | 'not_found' | 'closed'.
create function public.svc_case_metoo(p_reference text, p_supporter bytea)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r public.reports;
begin
  select r.* into v_r from public.reports r where r.reference = upper(trim(p_reference)) for update;
  if not found then return 'not_found'; end if;
  if v_r.status in ('resolved', 'closed', 'rejected') then return 'closed'; end if;
  begin
    insert into private.report_supporters (report_id, supporter_hash) values (v_r.id, p_supporter);
  exception when unique_violation then
    return 'duplicate';
  end;
  update public.reports set supporters = supporters + 1 where id = v_r.id;
  if v_r.supporters + 1 = 10 and v_r.priority in ('low', 'normal') then
    update public.reports set priority = 'high' where id = v_r.id;
    insert into public.report_events (report_id, kind, is_public, message, data)
    values (v_r.id, 'note', false, 'Ten residents report the same problem. Priority raised to high.', jsonb_build_object('supporters', 10));
  end if;
  return 'ok';
end;
$$;
revoke all on function public.svc_case_metoo(text, bytea) from public, anon, authenticated;

-- The public status page also shows how many people have the same problem.
create or replace function internal.case_status(p_reference text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'reference', r.reference,
    'status', r.status,
    'category_id', r.category_id,
    'category', c.name,
    'category_sw', c.name_sw,
    'ward', w.name,
    'ward_id', r.ward_id,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'resolve_due_at', r.resolve_due_at,
    'project_slug', p.slug,
    'reopened_count', r.reopened_count,
    'supporters', r.supporters,
    'feedback_given', exists (select 1 from public.case_feedback f where f.report_id = r.id and f.created_at >= coalesce(r.resolved_at, r.created_at) and r.status in ('resolved', 'closed')),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('kind', e.kind, 'message', e.message, 'at', e.created_at) order by e.created_at)
      from public.report_events e where e.report_id = r.id and e.is_public), '[]'::jsonb))
  from public.reports r
  join public.wards w on w.id = r.ward_id
  left join public.report_categories c on c.id = r.category_id
  left join public.projects p on p.id = r.project_id and p.published
  where r.reference = upper(trim(p_reference));
$$;

-- ---- public participation calendar ----------------------------------------------------------------------------------
-- The Constitution (Art. 196) and the County Governments Act require the county to involve residents; this is where
-- ward barazas, budget hearings and Assembly sittings are announced, with the outcome recorded afterwards.
create table public.public_meetings (
  id          uuid primary key default gen_random_uuid(),
  ward_id     text references public.wards (id),            -- null = county-wide
  kind        text not null default 'baraza' check (kind in ('baraza', 'budget_hearing', 'assembly_sitting', 'town_hall', 'other')),
  title       text not null check (char_length(title) between 5 and 160),
  title_sw    text check (char_length(title_sw) <= 160),
  agenda      text check (char_length(agenda) <= 2000),
  venue       text not null check (char_length(venue) between 2 and 200),
  starts_at   timestamptz not null,
  ends_at     timestamptz not null,
  status      text not null default 'scheduled' check (status in ('scheduled', 'cancelled', 'held')),
  outcome     text check (char_length(outcome) <= 4000),        -- what was decided, published after the meeting
  attendance  int check (attendance >= 0),
  created_by  uuid references auth.users (id),
  created_at  timestamptz not null default now(),
  check (ends_at > starts_at)
);
create index public_meetings_when_idx on public.public_meetings (starts_at);
create index public_meetings_ward_idx on public.public_meetings (ward_id);
alter table public.public_meetings enable row level security;
create policy "meetings: public read" on public.public_meetings for select to anon, authenticated using (true);
create policy "meetings: publishers insert" on public.public_meetings for insert to authenticated
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']));
create policy "meetings: publishers update" on public.public_meetings for update to authenticated
  using (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']))
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']));
create policy "meetings: admins delete" on public.public_meetings for delete to authenticated using (private.is_admin());
grant select on public.public_meetings to anon, authenticated;
grant insert, update, delete on public.public_meetings to authenticated;
create trigger audit_public_meetings after insert or update or delete on public.public_meetings
  for each row execute function private.audit_row();

-- A new or cancelled meeting reaches the ward's followers in the app and its instant SMS subscribers.
create function private.meetings_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_what text;
  v_ward text;
begin
  if tg_op = 'INSERT' and new.status = 'scheduled' then
    v_what := 'New meeting';
  elsif tg_op = 'UPDATE' and new.status = 'cancelled' and old.status <> 'cancelled' then
    v_what := 'Meeting cancelled';
  else
    return new;
  end if;
  select w.name into v_ward from public.wards w where w.id = new.ward_id;
  if new.ward_id is not null then
    perform private.tell_followers('ward_tenders', new.ward_id, v_what || ': ' || new.title,
      to_char(new.starts_at at time zone 'Africa/Nairobi', 'Dy DD Mon, HH24:MI') || ' at ' || new.venue, '/meetings',
      case when new.status = 'cancelled' then 'warning' else 'info' end);
    insert into private.outbox (channel, recipient, body, related)
    select 'sms', s.phone_e164,
           left(v_what || ' (' || coalesce(v_ward, '') || '): ' || new.title || ', '
                || to_char(new.starts_at at time zone 'Africa/Nairobi', 'Dy DD Mon HH24:MI') || ', ' || new.venue || '. Reply STOP to stop.', 300),
           jsonb_build_object('meeting_id', new.id)
      from private.subscribers s
     where s.ward_id = new.ward_id and s.verified_at is not null and s.opted_out_at is null and s.frequency = 'instant';
  end if;
  return new;
end;
$$;
create trigger public_meetings_notify after insert or update of status on public.public_meetings
  for each row execute function private.meetings_notify();

-- ==== 20260930001800_duplicates_and_project_checks.sql ====

-- 0018  Open reports a resident can join before filing a duplicate, and community checks on published projects.

-- ---- open reports of the same kind in a ward ------------------------------------------------------------------------
-- Shown while reporting so a resident can press "me too" instead of filing again. Reveals only what the public status
-- page already shows (reference, category, status, dates, how many people joined), never the description.
create function internal.open_cases(p_ward text, p_category text default null)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by (x ->> 'supporters')::int desc, x ->> 'created_at' desc), '[]'::jsonb)
  from (
    select jsonb_build_object('reference', r.reference, 'category_id', r.category_id, 'status', r.status,
                              'created_at', r.created_at, 'supporters', r.supporters) as x
      from public.reports r
     where r.ward_id = p_ward
       and (p_category is null or r.category_id = p_category)
       and r.status not in ('resolved', 'closed', 'rejected')
       and r.duplicate_of is null
       and r.created_at > now() - interval '120 days'
     order by r.supporters desc, r.created_at desc
     limit 8
  ) t;
$$;
create function public.open_cases(p_ward text, p_category text default null)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.open_cases(p_ward => p_ward, p_category => p_category) $$;
revoke all on function public.open_cases(text, text) from public;
grant execute on function public.open_cases(text, text) to anon, authenticated, service_role;
grant execute on function internal.open_cases(text, text) to anon, authenticated, service_role;

-- ---- community checks on projects ---------------------------------------------------------------------------------
-- A resident who can see the site says whether it looks as the county describes it. One answer per person per
-- project (a keyed hash, like a vote), comments scrubbed of personal details before they arrive here.
create table private.project_checks (
  project_id  uuid not null references public.projects (id) on delete cascade,
  checker_hash bytea not null,
  verdict     text not null check (verdict in ('as_shown', 'not_as_shown')),
  comment     text check (char_length(comment) <= 400),
  created_at  timestamptz not null default now(),
  primary key (project_id, checker_hash)
);

-- Called only by the case-feedback Edge Function. 'ok' | 'duplicate' | 'not_found'.
create function public.svc_project_check(p_slug text, p_verdict text, p_comment text, p_checker bytea)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_p public.projects;
  v_no int;
begin
  if p_verdict not in ('as_shown', 'not_as_shown') then raise exception 'Invalid verdict' using errcode = '22023'; end if;
  select p.* into v_p from public.projects p where p.slug = p_slug and p.published;
  if not found then return 'not_found'; end if;
  begin
    insert into private.project_checks (project_id, checker_hash, verdict, comment)
    values (v_p.id, p_checker, p_verdict, nullif(left(trim(coalesce(p_comment, '')), 400), ''));
  exception when unique_violation then
    return 'duplicate';
  end;
  if p_verdict = 'not_as_shown' then
    select count(*) into v_no from private.project_checks c where c.project_id = v_p.id and c.verdict = 'not_as_shown';
    -- the third doubt, and every tenth after, is put in front of the people who publish projects
    if v_no = 3 or (v_no > 3 and v_no % 10 = 0) then
      insert into public.notifications (user_id, title, message, kind, link)
      select distinct r.user_id, 'Residents question a project',
             v_no || ' residents say "' || v_p.title || '" does not look as published. Check the site and update the project.',
             'warning', null
        from public.staff_roles r
       where r.active and (r.expires_at is null or r.expires_at > now())
         and (r.role in ('super_admin', 'admin', 'chief_officer') or (r.role in ('sub_county_admin', 'ward_admin') and (r.ward_id = v_p.ward_id or r.ward_id is null)));
    end if;
  end if;
  return 'ok';
end;
$$;
revoke all on function public.svc_project_check(text, text, text, bytea) from public, anon, authenticated;

-- What residents say about a project: totals and the latest comments.
create function internal.project_checks(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'as_shown', count(*) filter (where c.verdict = 'as_shown'),
    'not_as_shown', count(*) filter (where c.verdict = 'not_as_shown'),
    'comments', coalesce((
      select jsonb_agg(jsonb_build_object('verdict', c2.verdict, 'comment', c2.comment, 'at', c2.created_at) order by c2.created_at desc)
        from (select * from private.project_checks c3 where c3.project_id = p.id and c3.comment is not null order by c3.created_at desc limit 6) c2
    ), '[]'::jsonb))
  from public.projects p
  left join private.project_checks c on c.project_id = p.id
  where p.slug = p_slug and p.published
  group by p.id;
$$;
create function public.project_checks(p_slug text)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.project_checks(p_slug => p_slug) $$;
revoke all on function public.project_checks(text) from public;
grant execute on function public.project_checks(text) to anon, authenticated, service_role;
grant execute on function internal.project_checks(text) to anon, authenticated, service_role;

-- ==== 20260930001900_notices_and_commitments.sql ====

-- 0019  Service notices (water, power, roads, waste) and the county's public commitments with a status history.

-- ---- service notices ----------------------------------------------------------------------------------------------
-- "No water in Kawangware until Thursday", "Ngong Road closed at Adams", "Collection moved to Saturday". Ward staff post
-- for their own ward; county-wide notices need a county role. Followers of the ward are told in the app, and instant SMS
-- subscribers get a text when a disruption starts and when the service is back.
create table public.service_notices (
  id           uuid primary key default gen_random_uuid(),
  ward_id      text references public.wards (id),            -- null = county-wide
  kind         text not null default 'other' check (kind in ('water', 'power', 'road', 'waste', 'health', 'other')),
  severity     text not null default 'disruption' check (severity in ('info', 'disruption', 'emergency')),
  title        text not null check (char_length(title) between 5 and 160),
  title_sw     text check (char_length(title_sw) <= 160),
  body         text check (char_length(body) <= 2000),
  area         text check (char_length(area) <= 200),        -- estates, roads or landmarks affected
  starts_at    timestamptz not null default now(),
  ends_at      timestamptz,                                    -- expected end, if known
  status       text not null default 'active' check (status in ('active', 'resolved', 'cancelled')),
  resolved_at  timestamptz,
  resolved_note text check (char_length(resolved_note) <= 1000),
  created_by   uuid references auth.users (id) default auth.uid(),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  check (ends_at is null or ends_at > starts_at)
);
create index service_notices_live_idx on public.service_notices (status, starts_at desc);
create index service_notices_ward_idx on public.service_notices (ward_id);
alter table public.service_notices enable row level security;
create policy "notices: public read" on public.service_notices for select to anon, authenticated using (true);
create policy "notices: ward staff insert" on public.service_notices for insert to authenticated
  with check (case when ward_id is null then private.has_role(array['super_admin', 'admin', 'chief_officer']) else private.can_manage_ward(ward_id) end);
create policy "notices: ward staff update" on public.service_notices for update to authenticated
  using (case when ward_id is null then private.has_role(array['super_admin', 'admin', 'chief_officer']) else private.can_manage_ward(ward_id) end)
  with check (case when ward_id is null then private.has_role(array['super_admin', 'admin', 'chief_officer']) else private.can_manage_ward(ward_id) end);
create policy "notices: admins delete" on public.service_notices for delete to authenticated using (private.is_admin());
grant select on public.service_notices to anon, authenticated;
grant insert, update, delete on public.service_notices to authenticated;
create trigger audit_service_notices after insert or update or delete on public.service_notices
  for each row execute function private.audit_row();
create trigger service_notices_touch before update on public.service_notices
  for each row execute function private.touch_updated_at();

create function private.notices_stamp()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'resolved' and (tg_op = 'INSERT' or old.status <> 'resolved') then
    new.resolved_at := coalesce(new.resolved_at, now());
  elsif new.status <> 'resolved' then
    new.resolved_at := null;
  end if;
  return new;
end;
$$;
create trigger service_notices_stamp before insert or update of status on public.service_notices
  for each row execute function private.notices_stamp();

create function private.notices_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_what text;
  v_ward text;
  v_msg text;
begin
  if tg_op = 'INSERT' and new.status = 'active' then
    v_what := case new.severity when 'emergency' then 'Emergency' when 'info' then 'Notice' else 'Service disruption' end;
    v_msg := coalesce(nullif(new.area, '') || '. ', '')
             || case when new.ends_at is not null then 'Expected back ' || to_char(new.ends_at at time zone 'Africa/Nairobi', 'Dy DD Mon HH24:MI') || '.' else '' end;
  elsif tg_op = 'UPDATE' and new.status = 'resolved' and old.status = 'active' then
    v_what := 'Back to normal';
    v_msg := coalesce(new.resolved_note, 'The county says this is resolved.');
  else
    return new;
  end if;
  if new.ward_id is not null then
    select w.name into v_ward from public.wards w where w.id = new.ward_id;
    perform private.tell_followers('ward_tenders', new.ward_id, v_what || ': ' || new.title, v_msg, '/notices',
      case when v_what = 'Back to normal' then 'success' when new.severity = 'emergency' then 'warning' else 'info' end);
  end if;
  -- SMS only for things that change a resident's day: disruptions and emergencies, and the all clear after them.
  if new.severity <> 'info' then
    insert into private.outbox (channel, recipient, body, related)
    select distinct on (s.phone_e164) 'sms', s.phone_e164,
           left(v_what || coalesce(' (' || v_ward || ')', '') || ': ' || new.title || '. ' || v_msg || ' Reply STOP to stop.', 300),
           jsonb_build_object('notice_id', new.id)
      from private.subscribers s
     where s.verified_at is not null and s.opted_out_at is null and s.frequency = 'instant'
       and (s.ward_id = new.ward_id or (new.ward_id is null and new.severity = 'emergency'));
  end if;
  return new;
end;
$$;
create trigger service_notices_notify after insert or update of status on public.service_notices
  for each row execute function private.notices_notify();

-- ---- commitments: what the county promised, and whether it kept it ------------------------------------------------
create table public.commitments (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{2,78}$'),
  title       text not null check (char_length(title) between 5 and 200),
  title_sw    text check (char_length(title_sw) <= 200),
  detail      text check (char_length(detail) <= 3000),
  source      text not null check (char_length(source) between 2 and 200),   -- e.g. "CIDP 2023-2027", "Budget speech 2026"
  source_url  text check (source_url ~ '^https://'),
  made_on     date,
  due_on      date,
  sector      text check (char_length(sector) <= 60),
  ward_id     text references public.wards (id),                             -- null = county-wide
  project_id  uuid references public.projects (id) on delete set null,
  status      text not null default 'not_started' check (status in ('not_started', 'in_progress', 'delivered', 'delayed', 'dropped')),
  evidence    text check (char_length(evidence) <= 2000),                     -- what shows it was delivered, or why not
  created_by  uuid references auth.users (id) default auth.uid(),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index commitments_status_idx on public.commitments (status, due_on);
alter table public.commitments enable row level security;
create policy "commitments: public read" on public.commitments for select to anon, authenticated using (true);
create policy "commitments: county insert" on public.commitments for insert to authenticated
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer']));
create policy "commitments: county update" on public.commitments for update to authenticated
  using (private.has_role(array['super_admin', 'admin', 'chief_officer']))
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer']));
create policy "commitments: admins delete" on public.commitments for delete to authenticated using (private.is_admin());
grant select on public.commitments to anon, authenticated;
grant insert, update, delete on public.commitments to authenticated;
create trigger audit_commitments after insert or update or delete on public.commitments
  for each row execute function private.audit_row();
create trigger commitments_touch before update on public.commitments
  for each row execute function private.touch_updated_at();

-- Every status change is kept in public, so a promise cannot quietly move from "delayed" back to "not started", and a
-- due date that slips is on the record. Rows are written only by the trigger.
create table public.commitment_updates (
  id            bigint generated always as identity primary key,
  commitment_id uuid not null references public.commitments (id) on delete cascade,
  status        text not null,
  due_on        date,
  note          text,
  created_at    timestamptz not null default now()
);
create index commitment_updates_idx on public.commitment_updates (commitment_id, created_at);
alter table public.commitment_updates enable row level security;
create policy "commitment updates: public read" on public.commitment_updates for select to anon, authenticated using (true);
grant select on public.commitment_updates to anon, authenticated;

create function private.commitments_history()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' or old.status is distinct from new.status or old.due_on is distinct from new.due_on then
    insert into public.commitment_updates (commitment_id, status, due_on, note)
    values (new.id, new.status, new.due_on,
            case when tg_op = 'INSERT' then 'Published'
                 when old.due_on is distinct from new.due_on and old.status is not distinct from new.status then 'Due date changed from ' || coalesce(old.due_on::text, 'none')
                 else nullif(new.evidence, '') end);
    if tg_op = 'UPDATE' and old.status is distinct from new.status then
      perform private.tell_followers('commitment', new.slug, 'County promise updated: ' || left(new.title, 100),
        'Now ' || replace(new.status, '_', ' ') || '.', '/promises#' || new.slug,
        case when new.status = 'delivered' then 'success' when new.status in ('delayed', 'dropped') then 'warning' else 'info' end);
    end if;
  end if;
  return new;
end;
$$;
create trigger commitments_history after insert or update on public.commitments
  for each row execute function private.commitments_history();

-- Residents can follow a single promise.
alter table public.follows drop constraint follows_kind_check;
alter table public.follows add constraint follows_kind_check check (kind in ('supplier', 'project', 'ward_tenders', 'sector', 'commitment'));

-- ==== 20260930002000_rights_and_participation.sql ====

-- 0020  Rights residents already have in law, made usable:
--   * information requests under the Access to Information Act, 2016 (21 days, one 14-day extension, 48 hours when a
--     life or liberty is at stake), published with their answers so each answer serves everyone;
--   * "have your say" on draft bills, budgets and policies (Constitution art. 196, County Governments Act s. 87), with a
--     published report of what was heard;
--   * a guaranteed answer for petitions that reach a support threshold (after Taiwan's Join and Democracy Seoul);
--   * the Data Protection Act, 2019: a copy of my data on demand and an erasure request with a 14-day deadline.

-- ---- information requests ------------------------------------------------------------------------------------------
create table public.info_requests (
  id              uuid primary key default gen_random_uuid(),
  reference       text not null unique default private.new_reference('I'),
  user_id         uuid not null default auth.uid() references auth.users (id) on delete cascade,
  requester_name  text check (char_length(requester_name) <= 80),         -- shown publicly; blank shows "A resident"
  department_id   uuid references public.departments (id),
  title           text not null check (char_length(title) between 8 and 160),
  body            text not null check (char_length(body) between 20 and 4000),
  is_public       boolean not null default true,
  urgent          boolean not null default false,                         -- life or liberty: 48 hours
  urgent_reason   text check (char_length(urgent_reason) <= 500),
  status          text not null default 'submitted' check (status in ('submitted', 'extended', 'answered', 'partly_answered', 'refused', 'withdrawn')),
  due_at          timestamptz not null default now(),                     -- set by trigger, never by the client
  extended_to     timestamptz,
  extension_reason text check (char_length(extension_reason) <= 1000),
  response        text check (char_length(response) <= 10000),
  response_url    text check (response_url ~ '^https://'),
  refusal_reason  text check (char_length(refusal_reason) <= 2000),
  answered_by     uuid references auth.users (id),
  answered_at     timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  check (not urgent or urgent_reason is not null)
);
create index info_requests_status_idx on public.info_requests (status, due_at);
create index info_requests_user_idx on public.info_requests (user_id);
alter table public.info_requests enable row level security;
create policy "info requests: public read" on public.info_requests for select to anon using (is_public);
create policy "info requests: read public, own and staff" on public.info_requests for select to authenticated
  using (is_public or user_id = (select auth.uid()) or private.is_staff());
create policy "info requests: residents file their own" on public.info_requests for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "info requests: officers answer" on public.info_requests for update to authenticated
  using (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin', 'officer']))
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin', 'officer']));
-- Who asked stays private: the public never sees user_id.
revoke all on public.info_requests from anon, authenticated;
grant select (id, reference, requester_name, department_id, title, body, is_public, urgent, status, due_at, extended_to,
              extension_reason, response, response_url, refusal_reason, answered_at, created_at, updated_at)
  on public.info_requests to anon, authenticated;
grant insert (requester_name, department_id, title, body, is_public, urgent, urgent_reason) on public.info_requests to authenticated;
grant update (status, extended_to, extension_reason, response, response_url, refusal_reason) on public.info_requests to authenticated;
create trigger audit_info_requests after insert or update or delete on public.info_requests
  for each row execute function private.audit_row();
create trigger info_requests_touch before update on public.info_requests
  for each row execute function private.touch_updated_at();

-- The clock and its rules live here, so no form or officer can bend them.
create function private.info_requests_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select count(*) from public.info_requests r where r.user_id = new.user_id and r.created_at > now() - interval '1 day') >= 5 then
      raise exception 'You can file up to 5 requests a day' using errcode = '54000';
    end if;
    new.status := 'submitted';
    new.created_at := now();
    new.due_at := now() + case when new.urgent then interval '48 hours' else interval '21 days' end;
    new.extended_to := null; new.extension_reason := null; new.response := null; new.refusal_reason := null;
    new.answered_at := null; new.answered_by := null;
    return new;
  end if;
  if old.status in ('answered', 'partly_answered', 'refused', 'withdrawn') and new.status is distinct from old.status then
    raise exception 'This request is closed' using errcode = '22023';
  end if;
  if new.status = 'extended' and old.status <> 'extended' then
    if old.extended_to is not null then raise exception 'A request can be extended only once' using errcode = '22023'; end if;
    if old.urgent then raise exception 'Urgent requests cannot be extended' using errcode = '22023'; end if;
    if coalesce(trim(new.extension_reason), '') = '' then raise exception 'Give the reason for the extension' using errcode = '22023'; end if;
    new.extended_to := old.due_at + interval '14 days';
  else
    new.extended_to := old.extended_to;
    if new.extension_reason is distinct from old.extension_reason and old.status <> 'submitted' then new.extension_reason := old.extension_reason; end if;
  end if;
  if new.status in ('answered', 'partly_answered') and coalesce(trim(new.response), '') = '' and new.response_url is null then
    raise exception 'Add the answer or a link to the documents' using errcode = '22023';
  end if;
  if new.status = 'refused' and coalesce(trim(new.refusal_reason), '') = '' then
    raise exception 'A refusal must give the reason and the section of the Act relied on' using errcode = '22023';
  end if;
  if new.status in ('answered', 'partly_answered', 'refused') and old.status not in ('answered', 'partly_answered', 'refused') then
    new.answered_at := now();
    new.answered_by := auth.uid();
  end if;
  new.due_at := old.due_at;
  return new;
end;
$$;
create trigger info_requests_rules before insert or update on public.info_requests
  for each row execute function private.info_requests_rules();

create function private.info_requests_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.notifications (user_id, title, message, kind, link)
    select distinct r.user_id, 'New information request ' || new.reference,
           new.title || '. Decision due ' || to_char(new.due_at at time zone 'Africa/Nairobi', 'DD Mon YYYY HH24:MI') || '.',
           case when new.urgent then 'warning' else 'info' end, '/console/information'
      from public.staff_roles r
     where r.active and (r.expires_at is null or r.expires_at > now()) and r.role in ('super_admin', 'admin', 'chief_officer');
  elsif new.status is distinct from old.status and new.status in ('extended', 'answered', 'partly_answered', 'refused') then
    insert into public.notifications (user_id, title, message, kind, link)
    values (new.user_id,
            case new.status when 'extended' then 'More time taken on ' when 'refused' then 'Request refused: ' else 'Your request was answered: ' end || new.reference,
            case new.status when 'extended' then 'The county extended the deadline by 14 days: ' || coalesce(new.extension_reason, '')
                            when 'refused' then 'You can ask the Commission on Administrative Justice to review this decision.'
                            else new.title end,
            case new.status when 'refused' then 'warning' when 'extended' then 'info' else 'success' end,
            '/information/' || new.reference);
  end if;
  return new;
end;
$$;
create trigger info_requests_notify after insert or update of status on public.info_requests
  for each row execute function private.info_requests_notify();

-- A resident's own requests, including private ones (the table hides user_id from everyone).
create function internal.my_info_requests()
returns setof public.info_requests
language sql
stable
security definer
set search_path = ''
as $$ select * from public.info_requests r where r.user_id = (select auth.uid()) order by r.created_at desc $$;
create function public.my_info_requests()
returns setof public.info_requests language sql stable security invoker set search_path = ''
as $$ select * from internal.my_info_requests() $$;
revoke all on function public.my_info_requests() from public, anon;
revoke all on function internal.my_info_requests() from public, anon;
grant execute on function public.my_info_requests() to authenticated, service_role;
grant execute on function internal.my_info_requests() to authenticated, service_role;

-- ---- consultations: have your say on a draft -----------------------------------------------------------------------
create table public.consultations (
  id           uuid primary key default gen_random_uuid(),
  slug         text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{2,78}$'),
  kind         text not null default 'policy' check (kind in ('bill', 'budget', 'policy', 'plan', 'other')),
  title        text not null check (char_length(title) between 5 and 200),
  title_sw     text check (char_length(title_sw) <= 200),
  summary      text not null check (char_length(summary) between 20 and 4000),   -- plain-language summary
  summary_sw   text check (char_length(summary_sw) <= 4000),
  document_url text check (document_url ~ '^https://'),
  questions    text[] not null default '{}',                                    -- sections or questions residents answer
  ward_id      text references public.wards (id),
  opens_at     timestamptz not null default now(),
  closes_at    timestamptz not null,
  report       text check (char_length(report) <= 20000),                       -- what was heard and what changed
  report_url   text check (report_url ~ '^https://'),
  report_at    timestamptz,
  created_by   uuid references auth.users (id) default auth.uid(),
  created_at   timestamptz not null default now(),
  -- residents need reasonable time to read and respond: at least seven days of comments
  check (closes_at >= opens_at + interval '7 days')
);
alter table public.consultations enable row level security;
create policy "consultations: public read" on public.consultations for select to anon, authenticated using (true);
create policy "consultations: publishers insert" on public.consultations for insert to authenticated
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer']));
create policy "consultations: publishers update" on public.consultations for update to authenticated
  using (private.has_role(array['super_admin', 'admin', 'chief_officer']))
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer']));
create policy "consultations: admins delete" on public.consultations for delete to authenticated using (private.is_admin());
grant select on public.consultations to anon, authenticated;
grant insert, update, delete on public.consultations to authenticated;
create trigger audit_consultations after insert or update or delete on public.consultations
  for each row execute function private.audit_row();

create table public.consultation_comments (
  id              bigint generated always as identity primary key,
  consultation_id uuid not null references public.consultations (id) on delete cascade,
  user_id         uuid not null default auth.uid() references auth.users (id) on delete cascade,
  author_name     text check (char_length(author_name) <= 80),
  ward_id         text references public.wards (id),
  question        int check (question >= 0),                          -- index into consultations.questions
  stance          text not null default 'comment' check (stance in ('support', 'oppose', 'amend', 'comment')),
  body            text not null check (char_length(body) between 5 and 2000),
  created_at      timestamptz not null default now()
);
create index consultation_comments_idx on public.consultation_comments (consultation_id, created_at);
alter table public.consultation_comments enable row level security;
create policy "comments: public read" on public.consultation_comments for select to anon, authenticated using (true);
create policy "comments: residents while open" on public.consultation_comments for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (
    select 1 from public.consultations c where c.id = consultation_id and now() between c.opens_at and c.closes_at));
create policy "comments: admins remove abuse" on public.consultation_comments for delete to authenticated using (private.is_admin());
revoke all on public.consultation_comments from anon, authenticated;
grant select (id, consultation_id, author_name, ward_id, question, stance, body, created_at) on public.consultation_comments to anon, authenticated;
grant insert (consultation_id, author_name, ward_id, question, stance, body) on public.consultation_comments to authenticated;
grant delete on public.consultation_comments to authenticated;
create trigger audit_consultation_comments after insert or delete on public.consultation_comments
  for each row execute function private.audit_row();

create function private.consultation_comments_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.created_at := now();
  if (select count(*) from public.consultation_comments c where c.user_id = new.user_id and c.consultation_id = new.consultation_id) >= 20 then
    raise exception 'You can leave up to 20 comments on one consultation' using errcode = '54000';
  end if;
  if new.question is not null and new.question >= (select coalesce(array_length(c.questions, 1), 0) from public.consultations c where c.id = new.consultation_id) then
    new.question := null;
  end if;
  return new;
end;
$$;
create trigger consultation_comments_limit before insert on public.consultation_comments
  for each row execute function private.consultation_comments_limit();

-- Opening reaches the ward's followers; the report reaches everyone who commented.
create function private.consultations_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and new.ward_id is not null then
    perform private.tell_followers('ward_tenders', new.ward_id, 'Have your say: ' || left(new.title, 120),
      'Comments close ' || to_char(new.closes_at at time zone 'Africa/Nairobi', 'DD Mon YYYY') || '.', '/have-your-say/' || new.slug);
  end if;
  if new.report is not null and (tg_op = 'INSERT' or old.report is null) then
    new.report_at := now();
    insert into public.notifications (user_id, title, message, kind, link)
    select distinct c.user_id, 'What the county heard: ' || left(new.title, 120),
           'The report on the consultation you took part in is published.', 'success', '/have-your-say/' || new.slug
      from public.consultation_comments c where c.consultation_id = new.id;
  end if;
  return new;
end;
$$;
create trigger consultations_notify before insert or update of report on public.consultations
  for each row execute function private.consultations_notify();

-- Totals by stance and question, for the public page and the report.
create function internal.consultation_tally(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'comments', count(cc.id),
    'people', count(distinct cc.user_id),
    'wards', count(distinct cc.ward_id),
    'by_stance', coalesce((select jsonb_object_agg(s.stance, s.n) from (
        select c2.stance, count(*) n from public.consultation_comments c2 where c2.consultation_id = c.id group by c2.stance) s), '{}'::jsonb))
  from public.consultations c
  left join public.consultation_comments cc on cc.consultation_id = c.id
  where c.slug = p_slug
  group by c.id;
$$;
create function public.consultation_tally(p_slug text)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.consultation_tally(p_slug => p_slug) $$;
revoke all on function public.consultation_tally(text) from public;
grant execute on function public.consultation_tally(text) to anon, authenticated, service_role;
grant execute on function internal.consultation_tally(text) to anon, authenticated, service_role;

-- ---- petitions: enough support earns an answer ---------------------------------------------------------------------
-- 200 supporters for a ward petition, 1,000 for a county-wide one; the county then has 30 days to answer in public.
alter table public.proposals add column response_due_at timestamptz;
alter table public.proposals add column threshold_reached_at timestamptz;

create function private.petition_threshold()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_goal int := case when new.ward_id is null then 1000 else 200 end;
begin
  if new.kind = 'petition' and new.threshold_reached_at is null and new.supporters >= v_goal then
    new.threshold_reached_at := now();
    new.response_due_at := now() + interval '30 days';
    insert into public.notifications (user_id, title, message, kind, link)
    select distinct r.user_id, 'A petition needs an answer within 30 days',
           '"' || left(new.title, 120) || '" reached ' || v_goal || ' supporters.', 'warning', '/console/ideas'
      from public.staff_roles r
     where r.active and (r.expires_at is null or r.expires_at > now())
       and (r.role in ('super_admin', 'admin', 'chief_officer') or (r.role in ('sub_county_admin', 'ward_admin') and r.ward_id = new.ward_id));
  end if;
  return new;
end;
$$;
create trigger proposals_petition_threshold before update of supporters on public.proposals
  for each row execute function private.petition_threshold();

-- ---- Data Protection Act: my data, and erasure -------------------------------------------------------------------
create table private.erasure_requests (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users (id) on delete cascade,
  email        text,
  reason       text check (char_length(reason) <= 1000),
  due_at       timestamptz not null default now() + interval '14 days',
  done_at      timestamptz,
  created_at   timestamptz not null default now()
);
create unique index erasure_requests_open_idx on private.erasure_requests (user_id) where done_at is null;

-- Everything the county holds about the signed-in person, as one JSON document they can save.
create function internal.my_data()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'generated_at', now(),
    'law', 'Data Protection Act, 2019, section 26',
    'profile', (select to_jsonb(p) from public.profiles p where p.id = (select auth.uid())),
    'staff_roles', coalesce((select jsonb_agg(jsonb_build_object('role', r.role, 'ward_id', r.ward_id, 'active', r.active, 'created_at', r.created_at)) from public.staff_roles r where r.user_id = (select auth.uid())), '[]'::jsonb),
    'applications', coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.applications a where a.applicant_id = (select auth.uid())), '[]'::jsonb),
    'follows', coalesce((select jsonb_agg(jsonb_build_object('kind', f.kind, 'key', f.key, 'label', f.label, 'created_at', f.created_at)) from public.follows f where f.user_id = (select auth.uid())), '[]'::jsonb),
    'notifications', coalesce((select jsonb_agg(jsonb_build_object('title', n.title, 'message', n.message, 'created_at', n.created_at) order by n.created_at desc) from public.notifications n where n.user_id = (select auth.uid())), '[]'::jsonb),
    'information_requests', coalesce((select jsonb_agg(to_jsonb(i) - 'user_id' order by i.created_at) from public.info_requests i where i.user_id = (select auth.uid())), '[]'::jsonb),
    'consultation_comments', coalesce((select jsonb_agg(to_jsonb(c) - 'user_id' order by c.created_at) from public.consultation_comments c where c.user_id = (select auth.uid())), '[]'::jsonb),
    'erasure_requests', coalesce((select jsonb_agg(jsonb_build_object('created_at', e.created_at, 'due_at', e.due_at, 'done_at', e.done_at)) from private.erasure_requests e where e.user_id = (select auth.uid())), '[]'::jsonb),
    'not_linked_to_you', 'Reports, votes, "me too" and petition support are stored without your account, as keyed hashes or anonymous records, so they cannot be listed here.'
  )
  where (select auth.uid()) is not null;
$$;
create function public.my_data()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.my_data() $$;
revoke all on function public.my_data() from public, anon;
revoke all on function internal.my_data() from public, anon;
grant execute on function public.my_data() to authenticated, service_role;
grant execute on function internal.my_data() to authenticated, service_role;

-- Ask for the account to be erased. Admins are told and have 14 days; records the law requires the county to keep
-- (payments, permits issued) are kept and the reply says so.
create function internal.request_erasure(p_reason text default null)
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_due timestamptz;
begin
  if v_uid is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  select e.due_at into v_due from private.erasure_requests e where e.user_id = v_uid and e.done_at is null;
  if found then return v_due; end if;
  insert into private.erasure_requests (user_id, email, reason)
  values (v_uid, (select u.email from auth.users u where u.id = v_uid), left(p_reason, 1000))
  returning due_at into v_due;
  insert into public.notifications (user_id, title, message, kind, link)
  select distinct r.user_id, 'Account erasure request', 'A resident asked for their account to be erased. Due ' || to_char(v_due at time zone 'Africa/Nairobi', 'DD Mon YYYY') || '.', 'warning', '/console/admin'
    from public.staff_roles r where r.active and r.role in ('super_admin', 'admin');
  return v_due;
end;
$$;
create function public.request_erasure(p_reason text default null)
returns timestamptz language sql volatile security invoker set search_path = ''
as $$ select internal.request_erasure(p_reason => p_reason) $$;
revoke all on function public.request_erasure(text) from public, anon;
revoke all on function internal.request_erasure(text) from public, anon;
grant execute on function public.request_erasure(text) to authenticated, service_role;
grant execute on function internal.request_erasure(text) to authenticated, service_role;

-- For admins: open erasure requests, and carrying one out. Erasure removes the profile details, follows, notifications
-- and the resident's comments; the auth account itself is deleted from the dashboard (Authentication, Users).
create function internal.erasure_queue()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when private.is_admin() then coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'email', e.email, 'reason', e.reason,
    'created_at', e.created_at, 'due_at', e.due_at) order by e.due_at), '[]'::jsonb) else '[]'::jsonb end
  from private.erasure_requests e where e.done_at is null;
$$;
create function public.erasure_queue()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.erasure_queue() $$;
revoke all on function public.erasure_queue() from public, anon;
revoke all on function internal.erasure_queue() from public, anon;
grant execute on function public.erasure_queue() to authenticated, service_role;
grant execute on function internal.erasure_queue() to authenticated, service_role;

create function internal.carry_out_erasure(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
begin
  if not private.is_admin() then raise exception 'Only administrators can do this' using errcode = '42501'; end if;
  select e.user_id into v_uid from private.erasure_requests e where e.id = p_id and e.done_at is null;
  if not found then raise exception 'No open request' using errcode = 'P0002'; end if;
  update public.profiles set name = '', email = null, phone = null, national_id = null, address = null, avatar_url = null where id = v_uid;
  delete from public.follows where user_id = v_uid;
  delete from public.notifications where user_id = v_uid;
  delete from public.consultation_comments where user_id = v_uid;
  update public.info_requests set requester_name = null where user_id = v_uid;
  update private.erasure_requests set done_at = now(), email = null where id = p_id;
end;
$$;
create function public.carry_out_erasure(p_id uuid)
returns void language sql volatile security invoker set search_path = ''
as $$ select internal.carry_out_erasure(p_id => p_id) $$;
revoke all on function public.carry_out_erasure(uuid) from public, anon;
revoke all on function internal.carry_out_erasure(uuid) from public, anon;
grant execute on function public.carry_out_erasure(uuid) to authenticated, service_role;
grant execute on function internal.carry_out_erasure(uuid) to authenticated, service_role;

-- ==== 20260930002100_open311_and_deadlines.sql ====

-- 0021  Open311 GeoReport v2 (read side) and a public scoreboard of the county's legal deadlines.
--   * Open311 is the open standard FixMyStreet, SeeClickFix and many cities use, so other systems, researchers and
--     reporters can read the county's issue reports without scraping. It exposes only what the public status page
--     already shows: no descriptions, no photos, no reporter, locations rounded to about 100 metres, and nothing from
--     sensitive categories (integrity and finance reports, where whistleblowers must stay hidden).
--   * legal_deadlines(): did the county answer information requests, petitions, consultations and erasure requests
--     within the time the law (or this county's own rule) gives it?

-- ---- Open311 ------------------------------------------------------------------------------------------------------
create function internal.open311_services()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'service_code', c.id,
    'service_name', c.name,
    'description', coalesce(c.name_sw, c.name),
    'metadata', false,
    'type', 'realtime',
    'keywords', '',
    'group', coalesce(d.name, 'County services')) order by c.name), '[]'::jsonb)
  from public.report_categories c
  left join public.departments d on d.id = c.department_id
  where not c.sensitive;
$$;
create function public.open311_services()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.open311_services() $$;
revoke all on function public.open311_services() from public;
grant execute on function public.open311_services() to anon, authenticated, service_role;
grant execute on function internal.open311_services() to anon, authenticated, service_role;

-- GeoReport v2 defaults: the last 90 days, at most 1,000 requests, newest first.
create function internal.open311_requests(
  p_service_code text default null, p_status text default null,
  p_start timestamptz default null, p_end timestamptz default null, p_ids text[] default null)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by x ->> 'requested_datetime' desc), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'service_request_id', r.reference,
      'status', case when r.status in ('resolved', 'closed', 'rejected') then 'closed' else 'open' end,
      'status_notes', (select e.message from public.report_events e where e.report_id = r.id and e.is_public order by e.created_at desc limit 1),
      'service_name', c.name,
      'service_code', r.category_id,
      'description', null,
      'agency_responsible', d.name,
      'service_notice', null,
      'requested_datetime', r.created_at,
      'updated_datetime', r.updated_at,
      'expected_datetime', r.resolve_due_at,
      'address', w.name || ' ward',
      'address_id', r.ward_id,
      'zipcode', null,
      'lat', round(r.lat, 3),
      'long', round(r.lng, 3),
      'media_url', null) as x
      from public.reports r
      join public.wards w on w.id = r.ward_id
      left join public.report_categories c on c.id = r.category_id
      left join public.departments d on d.id = r.department_id
     where r.duplicate_of is null
       and not coalesce(c.sensitive, false)              -- integrity and finance reports never appear in a bulk feed
       and (p_ids is null or r.reference = any (select upper(trim(i)) from unnest(p_ids) i))
       and (p_ids is not null or r.created_at >= coalesce(p_start, now() - interval '90 days'))
       and (p_ids is not null or r.created_at <= coalesce(p_end, now()))
       and (p_service_code is null or r.category_id = any (string_to_array(p_service_code, ',')))
       and (p_status is null or (p_status = 'open') = (r.status not in ('resolved', 'closed', 'rejected')))
     order by r.created_at desc
     limit 1000
  ) t;
$$;
create function public.open311_requests(
  p_service_code text default null, p_status text default null,
  p_start timestamptz default null, p_end timestamptz default null, p_ids text[] default null)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.open311_requests(p_service_code => p_service_code, p_status => p_status, p_start => p_start, p_end => p_end, p_ids => p_ids) $$;
revoke all on function public.open311_requests(text, text, timestamptz, timestamptz, text[]) from public;
grant execute on function public.open311_requests(text, text, timestamptz, timestamptz, text[]) to anon, authenticated, service_role;
grant execute on function internal.open311_requests(text, text, timestamptz, timestamptz, text[]) to anon, authenticated, service_role;

-- ---- petitions: when was the answer given ---------------------------------------------------------------------------
alter table public.proposals add column responded_at timestamptz;
create function private.proposals_responded()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.response is not null and (tg_op = 'INSERT' or old.response is null) then new.responded_at := now(); end if;
  return new;
end;
$$;
create trigger proposals_responded before insert or update of response on public.proposals
  for each row execute function private.proposals_responded();
update public.proposals set responded_at = created_at where response is not null and responded_at is null;

-- ---- the scoreboard -----------------------------------------------------------------------------------------------
create function internal.legal_deadlines()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'generated_at', now(),
    'info', (select jsonb_build_object(
        'decided', count(*) filter (where i.answered_at is not null),
        'on_time', count(*) filter (where i.answered_at is not null and i.answered_at <= coalesce(i.extended_to, i.due_at)),
        'waiting', count(*) filter (where i.status in ('submitted', 'extended')),
        'late_now', count(*) filter (where i.status in ('submitted', 'extended') and coalesce(i.extended_to, i.due_at) < now()))
      from public.info_requests i),
    'petitions', (select jsonb_build_object(
        'due', count(*) filter (where p.response_due_at is not null),
        'answered_on_time', count(*) filter (where p.responded_at is not null and p.responded_at <= p.response_due_at),
        'answered_late', count(*) filter (where p.responded_at > p.response_due_at),
        'late_now', count(*) filter (where p.responded_at is null and p.response_due_at < now()))
      from public.proposals p where p.kind = 'petition'),
    'consultations', (select jsonb_build_object(
        'closed', count(*) filter (where c.closes_at < now()),
        'reported', count(*) filter (where c.closes_at < now() and c.report_at is not null),
        'report_owed', count(*) filter (where c.closes_at < now() - interval '30 days' and c.report_at is null))
      from public.consultations c),
    'erasure', (select jsonb_build_object(
        'done', count(*) filter (where e.done_at is not null),
        'on_time', count(*) filter (where e.done_at is not null and e.done_at <= e.due_at),
        'late_now', count(*) filter (where e.done_at is null and e.due_at < now()))
      from private.erasure_requests e),
    'promises', (select jsonb_build_object(
        'total', count(*),
        'delivered', count(*) filter (where m.status = 'delivered'),
        'past_due', count(*) filter (where m.due_on < current_date and m.status not in ('delivered', 'dropped')))
      from public.commitments m)
  );
$$;
create function public.legal_deadlines()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.legal_deadlines() $$;
revoke all on function public.legal_deadlines() from public;
grant execute on function public.legal_deadlines() to anon, authenticated, service_role;
grant execute on function internal.legal_deadlines() to anon, authenticated, service_role;

-- ==== 20260930002200_round_two_civic.sql ====

-- 0022  What the best civic platforms elsewhere do that this one did not yet:
--   * one visit, several problems: up to five issues filed together become linked cases, each routed to its own team
--   * before and after photos to close a case (staff-taken, public), so "fixed" can be seen
--   * a secure two-way whistleblower inbox: anonymous, reached only with a secret key the reporter keeps
--   * ward champions: verified residents whose project checks carry a badge (after Nigeria's Tracka monitors)
--   * procurement concerns against a tender, answered within 14 days or escalated (after Ukraine's DOZORRO)
--   * county finance and audit figures for all 47 counties, entered from Controller of Budget and Auditor-General reports
--   * agree / disagree statements on consultations, without replies (after Taiwan's Pol.is)
--   * quick polls with results by ward (after U-Report)
--   * flagging of abusive public content, hidden for review after three flags

-- ===================================================================================================================
-- 1. Several issues in one report
-- ===================================================================================================================
alter table public.reports add column group_id uuid;
create index reports_group_idx on public.reports (group_id) where group_id is not null;

-- Idempotent on the client key of the first issue: a retry returns the whole group, never a second one.
create function public.svc_create_report_group(
  p_id uuid, p_client_key uuid, p_ward text, p_categories text[], p_description text,
  p_lat numeric, p_lng numeric, p_language text, p_channel text,
  p_callback_phone text default null, p_photo_paths text[] default '{}'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cats text[];
  v_first public.reports;
  r public.reports;
  v_group uuid := coalesce(p_id, gen_random_uuid());
  v_out jsonb := '[]'::jsonb;
  c text;
  p text;
  i int := 0;
begin
  -- distinct issues, in the order the resident chose them: the first is the main one
  select array_agg(x order by o) into v_cats
    from (select t.x, min(t.o) as o from unnest(p_categories) with ordinality t(x, o) where t.x is not null group by t.x) d;
  if v_cats is null or array_length(v_cats, 1) > 5 then
    raise exception 'Choose between one and five issues' using errcode = '22023';
  end if;

  if p_client_key is not null then
    select * into v_first from public.reports where client_key = p_client_key;
    if found then
      select coalesce(jsonb_agg(jsonb_build_object('reference', g.reference, 'category_id', g.category_id) order by g.created_at, g.reference), '[]'::jsonb)
        into v_out from public.reports g where g.group_id = coalesce(v_first.group_id, v_first.id) or g.id = v_first.id;
      return jsonb_build_object('reference', v_first.reference, 'ward_id', v_first.ward_id, 'status', v_first.status, 'duplicate', true, 'reports', v_out);
    end if;
  end if;

  foreach c in array v_cats loop
    i := i + 1;
    insert into public.reports (id, client_key, ward_id, category_id, description, lat, lng, language, channel, group_id)
    values (case when i = 1 then v_group else gen_random_uuid() end, case when i = 1 then p_client_key end,
            p_ward, c, p_description, p_lat, p_lng, p_language, p_channel, case when array_length(v_cats, 1) > 1 then v_group end)
    returning * into r;
    if i = 1 then v_first := r; end if;
    foreach p in array coalesce(p_photo_paths, '{}') loop
      insert into public.report_photos (report_id, storage_path) values (r.id, p);
    end loop;
    if p_callback_phone is not null then
      insert into private.report_contacts (report_id, phone_e164) values (r.id, p_callback_phone);
    end if;
    v_out := v_out || jsonb_build_array(jsonb_build_object('reference', r.reference, 'category_id', r.category_id));
  end loop;
  return jsonb_build_object('reference', v_first.reference, 'ward_id', v_first.ward_id, 'status', v_first.status, 'duplicate', false, 'reports', v_out);
exception when unique_violation then
  select * into v_first from public.reports where client_key = p_client_key;
  if found then
    select coalesce(jsonb_agg(jsonb_build_object('reference', g.reference, 'category_id', g.category_id) order by g.created_at, g.reference), '[]'::jsonb)
      into v_out from public.reports g where g.group_id = coalesce(v_first.group_id, v_first.id) or g.id = v_first.id;
    return jsonb_build_object('reference', v_first.reference, 'ward_id', v_first.ward_id, 'status', v_first.status, 'duplicate', true, 'reports', v_out);
  end if;
  raise;
end;
$$;
revoke all on function public.svc_create_report_group(uuid, uuid, text, text[], text, numeric, numeric, text, text, text, text[]) from public, anon, authenticated;
grant execute on function public.svc_create_report_group(uuid, uuid, text, text[], text, numeric, numeric, text, text, text, text[]) to service_role;

-- ===================================================================================================================
-- 2. Before and after photos
-- ===================================================================================================================
-- Taken by staff at the site and public on purpose: residents' own photos stay private, these show the work.
create table public.fix_photos (
  id          uuid primary key default gen_random_uuid(),
  report_id   uuid not null references public.reports (id) on delete cascade,
  kind        text not null check (kind in ('before', 'after')),
  path        text not null check (char_length(path) between 5 and 300),
  caption     text check (char_length(caption) <= 200),
  uploaded_by uuid references auth.users (id) default auth.uid(),
  created_at  timestamptz not null default now()
);
create index fix_photos_report_idx on public.fix_photos (report_id);
alter table public.fix_photos enable row level security;
create policy "fix photos: public read" on public.fix_photos for select to anon, authenticated
  using (exists (select 1 from public.reports r join public.report_categories c on c.id = r.category_id where r.id = report_id and not c.sensitive));
create policy "fix photos: staff on their cases" on public.fix_photos for insert to authenticated
  with check (exists (select 1 from public.reports r where r.id = report_id and private.can_work_case(r.ward_id, r.department_id, r.assigned_to)));
create policy "fix photos: admins delete" on public.fix_photos for delete to authenticated using (private.is_admin());
grant select on public.fix_photos to anon, authenticated;
grant insert, delete on public.fix_photos to authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('fix-photos', 'fix-photos', true, 4194304, array['image/webp', 'image/jpeg', 'image/png'])
on conflict (id) do nothing;
create policy "fix photos: staff upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'fix-photos' and private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin', 'officer']));

-- A physical problem is closed with proof. Staff resolving it through the app must first add an "after" photo.
-- (Reports that are not physical, such as suspected misuse of funds, and changes made by the system are exempt.)
create function private.reports_need_after_photo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'resolved' and old.status <> 'resolved' and (select auth.uid()) is not null
     and new.category_id not in ('missing_funds', 'other')
     and not exists (select 1 from public.fix_photos f where f.report_id = new.id and f.kind = 'after') then
    raise exception 'Add an after photo before marking this fixed' using errcode = '22023';
  end if;
  return new;
end;
$$;
create trigger reports_need_after_photo before update of status on public.reports
  for each row execute function private.reports_need_after_photo();

-- The public "fixed" gallery: recently resolved cases with an after photo.
create function internal.fixed_gallery(p_limit int default 24)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by x ->> 'resolved_at' desc), '[]'::jsonb) from (
    select jsonb_build_object('reference', r.reference, 'category_id', r.category_id, 'category', c.name, 'category_sw', c.name_sw,
             'ward', w.name, 'ward_id', r.ward_id, 'reported_at', r.created_at, 'resolved_at', coalesce(r.resolved_at, r.updated_at),
             'before', (select f.path from public.fix_photos f where f.report_id = r.id and f.kind = 'before' order by f.created_at desc limit 1),
             'after', (select f.path from public.fix_photos f where f.report_id = r.id and f.kind = 'after' order by f.created_at desc limit 1)) as x
      from public.reports r
      join public.wards w on w.id = r.ward_id
      join public.report_categories c on c.id = r.category_id
     where r.status in ('resolved', 'closed') and not c.sensitive
       and exists (select 1 from public.fix_photos f where f.report_id = r.id and f.kind = 'after')
     order by coalesce(r.resolved_at, r.updated_at) desc
     limit least(greatest(p_limit, 1), 100)
  ) t;
$$;
create function public.fixed_gallery(p_limit int default 24)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.fixed_gallery(p_limit => p_limit) $$;
revoke all on function public.fixed_gallery(int) from public;
grant execute on function public.fixed_gallery(int) to anon, authenticated, service_role;
grant execute on function internal.fixed_gallery(int) to anon, authenticated, service_role;

-- The public status page also lists the other issues filed in the same visit, and the before / after photos.
create or replace function internal.case_status(p_reference text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'reference', r.reference,
    'status', r.status,
    'category_id', r.category_id,
    'category', c.name,
    'category_sw', c.name_sw,
    'ward', w.name,
    'ward_id', r.ward_id,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'resolve_due_at', r.resolve_due_at,
    'project_slug', p.slug,
    'reopened_count', r.reopened_count,
    'supporters', r.supporters,
    'feedback_given', exists (select 1 from public.case_feedback f where f.report_id = r.id and f.created_at >= coalesce(r.resolved_at, r.created_at) and r.status in ('resolved', 'closed')),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('kind', e.kind, 'message', e.message, 'at', e.created_at) order by e.created_at)
      from public.report_events e where e.report_id = r.id and e.is_public), '[]'::jsonb),
    'group', coalesce((
      select jsonb_agg(jsonb_build_object('reference', g.reference, 'category_id', g.category_id, 'status', g.status) order by g.created_at, g.reference)
      from public.reports g where r.group_id is not null and g.group_id = r.group_id and g.id <> r.id), '[]'::jsonb),
    'fix_photos', case when c.sensitive then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object('kind', f.kind, 'path', f.path, 'caption', f.caption, 'at', f.created_at) order by f.created_at)
      from public.fix_photos f where f.report_id = r.id), '[]'::jsonb) end)
  from public.reports r
  join public.wards w on w.id = r.ward_id
  left join public.report_categories c on c.id = r.category_id
  left join public.projects p on p.id = r.project_id and p.published
  where r.reference = upper(trim(p_reference));
$$;

-- ===================================================================================================================
-- 3. Whistleblower inbox
-- ===================================================================================================================
-- Nothing here can identify the reporter: no account, no phone, no address. The reporter holds a secret key; only a
-- keyed hash of it is stored. The Edge Function `disclosure` is the only way in for the reporter.
create table private.disclosures (
  id          uuid primary key default gen_random_uuid(),
  reference   text not null unique default private.new_reference('W'),
  key_hash    bytea not null unique,
  topic       text not null check (topic in ('bribery', 'procurement', 'payroll', 'theft', 'abuse_of_office', 'other')),
  ward_id     text references public.wards (id),
  status      text not null default 'received' check (status in ('received', 'reviewing', 'referred', 'closed')),
  referred_to text check (char_length(referred_to) <= 120),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create table private.disclosure_messages (
  id            bigint generated always as identity primary key,
  disclosure_id uuid not null references private.disclosures (id) on delete cascade,
  from_reporter boolean not null,
  body          text not null check (char_length(body) between 2 and 6000),
  created_at    timestamptz not null default now()
);
create index disclosure_messages_idx on private.disclosure_messages (disclosure_id, created_at);

create function public.svc_disclosure_create(p_key_hash bytea, p_topic text, p_ward text, p_body text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  d private.disclosures;
begin
  insert into private.disclosures (key_hash, topic, ward_id) values (p_key_hash, p_topic, p_ward) returning * into d;
  insert into private.disclosure_messages (disclosure_id, from_reporter, body) values (d.id, true, p_body);
  insert into public.notifications (user_id, title, message, kind, link)
  select distinct r.user_id, 'New protected disclosure', 'A whistleblower report (' || replace(p_topic, '_', ' ') || ') is waiting. ' || d.reference, 'warning', '/console/disclosures'
    from public.staff_roles r where r.active and (r.expires_at is null or r.expires_at > now()) and r.role in ('super_admin', 'admin');
  return d.reference;
end;
$$;

create function public.svc_disclosure_thread(p_key_hash bytea)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('reference', d.reference, 'topic', d.topic, 'status', d.status, 'referred_to', d.referred_to, 'created_at', d.created_at,
           'messages', coalesce((select jsonb_agg(jsonb_build_object('from_reporter', m.from_reporter, 'body', m.body, 'at', m.created_at) order by m.created_at)
                                   from private.disclosure_messages m where m.disclosure_id = d.id), '[]'::jsonb))
    from private.disclosures d where d.key_hash = p_key_hash;
$$;

create function public.svc_disclosure_reply(p_key_hash bytea, p_body text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  d private.disclosures;
begin
  select * into d from private.disclosures where key_hash = p_key_hash;
  if not found then return 'not_found'; end if;
  if d.status = 'closed' then return 'closed'; end if;
  if (select count(*) from private.disclosure_messages m where m.disclosure_id = d.id and m.from_reporter and m.created_at > now() - interval '1 day') >= 10 then
    return 'limit';
  end if;
  insert into private.disclosure_messages (disclosure_id, from_reporter, body) values (d.id, true, p_body);
  update private.disclosures set updated_at = now() where id = d.id;
  return 'ok';
end;
$$;
revoke all on function public.svc_disclosure_create(bytea, text, text, text) from public, anon, authenticated;
revoke all on function public.svc_disclosure_thread(bytea) from public, anon, authenticated;
revoke all on function public.svc_disclosure_reply(bytea, text) from public, anon, authenticated;
grant execute on function public.svc_disclosure_create(bytea, text, text, text) to service_role;
grant execute on function public.svc_disclosure_thread(bytea) to service_role;
grant execute on function public.svc_disclosure_reply(bytea, text) to service_role;

-- The integrity desk: county administrators, and auditors so that a report about an administrator has another reader.
create function private.integrity_reader()
returns boolean language sql stable security definer set search_path = ''
as $$ select private.has_role(array['super_admin', 'admin', 'auditor']) $$;

create function internal.disclosure_inbox()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when private.integrity_reader() then coalesce(jsonb_agg(jsonb_build_object(
      'id', d.id, 'reference', d.reference, 'topic', d.topic, 'ward_id', d.ward_id, 'status', d.status, 'referred_to', d.referred_to,
      'created_at', d.created_at, 'updated_at', d.updated_at,
      'messages', (select jsonb_agg(jsonb_build_object('from_reporter', m.from_reporter, 'body', m.body, 'at', m.created_at) order by m.created_at)
                     from private.disclosure_messages m where m.disclosure_id = d.id)) order by d.updated_at desc), '[]'::jsonb)
    else '[]'::jsonb end
  from private.disclosures d;
$$;
create function public.disclosure_inbox()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.disclosure_inbox() $$;

create function internal.disclosure_answer(p_id uuid, p_body text default null, p_status text default null, p_referred_to text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.integrity_reader() then raise exception 'Only the integrity desk can do this' using errcode = '42501'; end if;
  if p_status is not null and p_status not in ('received', 'reviewing', 'referred', 'closed') then raise exception 'Invalid status' using errcode = '22023'; end if;
  if nullif(trim(coalesce(p_body, '')), '') is not null then
    insert into private.disclosure_messages (disclosure_id, from_reporter, body) values (p_id, false, left(trim(p_body), 6000));
  end if;
  update private.disclosures set status = coalesce(p_status, status), referred_to = coalesce(nullif(trim(p_referred_to), ''), referred_to), updated_at = now() where id = p_id;
  if not found then raise exception 'Not found' using errcode = 'P0002'; end if;
end;
$$;
create function public.disclosure_answer(p_id uuid, p_body text default null, p_status text default null, p_referred_to text default null)
returns void language sql volatile security invoker set search_path = ''
as $$ select internal.disclosure_answer(p_id => p_id, p_body => p_body, p_status => p_status, p_referred_to => p_referred_to) $$;
revoke all on function public.disclosure_inbox() from public, anon;
revoke all on function internal.disclosure_inbox() from public, anon;
revoke all on function public.disclosure_answer(uuid, text, text, text) from public, anon;
revoke all on function internal.disclosure_answer(uuid, text, text, text) from public, anon;
grant execute on function public.disclosure_inbox() to authenticated, service_role;
grant execute on function internal.disclosure_inbox() to authenticated, service_role;
grant execute on function public.disclosure_answer(uuid, text, text, text) to authenticated, service_role;
grant execute on function internal.disclosure_answer(uuid, text, text, text) to authenticated, service_role;

-- ===================================================================================================================
-- 4. Ward champions
-- ===================================================================================================================
create table public.ward_champions (
  user_id      uuid primary key references auth.users (id) on delete cascade default auth.uid(),
  ward_id      text not null references public.wards (id),
  display_name text not null check (char_length(display_name) between 2 and 60),
  motivation   text check (char_length(motivation) <= 600),
  status       text not null default 'applied' check (status in ('applied', 'active', 'paused', 'declined')),
  approved_by  uuid references auth.users (id),
  approved_at  timestamptz,
  created_at   timestamptz not null default now()
);
alter table public.ward_champions enable row level security;
create policy "champions: active are public" on public.ward_champions for select to anon using (status = 'active');
create policy "champions: own, active and ward staff" on public.ward_champions for select to authenticated
  using (status = 'active' or user_id = (select auth.uid()) or private.can_manage_ward(ward_id));
create policy "champions: apply for yourself" on public.ward_champions for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'applied');
create policy "champions: ward staff decide" on public.ward_champions for update to authenticated
  using (private.can_manage_ward(ward_id)) with check (private.can_manage_ward(ward_id));
revoke all on public.ward_champions from anon, authenticated;
grant select (ward_id, display_name, status, approved_at, created_at) on public.ward_champions to anon;
grant select on public.ward_champions to authenticated;
grant insert (ward_id, display_name, motivation) on public.ward_champions to authenticated;
grant update (status) on public.ward_champions to authenticated;

create function private.champions_stamp()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is distinct from old.status then
    new.approved_by := auth.uid();
    new.approved_at := now();
    insert into public.notifications (user_id, title, message, kind, link)
    values (new.user_id, case new.status when 'active' then 'You are now a ward champion' when 'declined' then 'Ward champion application' else 'Ward champion status changed' end,
            case new.status when 'active' then 'Your project checks now carry the champion badge. Thank you for keeping an eye on your ward.'
                            when 'declined' then 'Your application was not approved this time.' else 'Your champion status is now ' || new.status || '.' end,
            case new.status when 'active' then 'success' else 'info' end, '/champions');
  end if;
  return new;
end;
$$;
create trigger ward_champions_stamp before update of status on public.ward_champions
  for each row execute function private.champions_stamp();

-- A champion's check on a project in their ward: named, public, and a doubt reaches staff at once.
create table public.champion_checks (
  id          bigint generated always as identity primary key,
  project_id  uuid not null references public.projects (id) on delete cascade,
  user_id     uuid not null references auth.users (id) on delete cascade default auth.uid(),
  verdict     text not null check (verdict in ('as_shown', 'not_as_shown')),
  comment     text check (char_length(comment) <= 600),
  created_at  timestamptz not null default now()
);
create index champion_checks_project_idx on public.champion_checks (project_id, created_at desc);
alter table public.champion_checks enable row level security;
create policy "champion checks: public read" on public.champion_checks for select to anon, authenticated using (true);
create policy "champion checks: active champions in the project's ward" on public.champion_checks for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (
    select 1 from public.ward_champions w join public.projects p on p.id = project_id
     where w.user_id = (select auth.uid()) and w.status = 'active' and w.ward_id = p.ward_id and p.published));
revoke all on public.champion_checks from anon, authenticated;
grant select (id, project_id, verdict, comment, created_at) on public.champion_checks to anon, authenticated;
grant insert (project_id, verdict, comment) on public.champion_checks to authenticated;

create function private.champion_checks_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_p public.projects;
begin
  if (select count(*) from public.champion_checks c where c.user_id = new.user_id and c.project_id = new.project_id and c.created_at > now() - interval '7 days') > 1 then
    raise exception 'One check per project per week' using errcode = '54000';
  end if;
  if new.verdict = 'not_as_shown' then
    select * into v_p from public.projects where id = new.project_id;
    insert into public.notifications (user_id, title, message, kind, link)
    select distinct r.user_id, 'A ward champion questions a project', '"' || v_p.title || '" does not look as published, says a ward champion.', 'warning', null
      from public.staff_roles r where r.active and (r.expires_at is null or r.expires_at > now())
       and (r.role in ('super_admin', 'admin', 'chief_officer') or (r.role in ('sub_county_admin', 'ward_admin') and r.ward_id = v_p.ward_id));
  end if;
  return new;
end;
$$;
create trigger champion_checks_notify after insert on public.champion_checks
  for each row execute function private.champion_checks_notify();

create function internal.champion_checks(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('verdict', c.verdict, 'comment', c.comment, 'at', c.created_at, 'champion', w.display_name) order by c.created_at desc), '[]'::jsonb)
    from public.champion_checks c
    join public.projects p on p.id = c.project_id and p.published
    join public.ward_champions w on w.user_id = c.user_id
   where p.slug = p_slug;
$$;
create function public.champion_checks_for(p_slug text)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.champion_checks(p_slug => p_slug) $$;
revoke all on function public.champion_checks_for(text) from public;
grant execute on function public.champion_checks_for(text) to anon, authenticated, service_role;
grant execute on function internal.champion_checks(text) to anon, authenticated, service_role;

-- ===================================================================================================================
-- 5. Procurement concerns
-- ===================================================================================================================
create table public.tender_concerns (
  id           uuid primary key default gen_random_uuid(),
  reference    text not null unique default private.new_reference('C'),
  tender_id    uuid not null references public.tenders (id) on delete cascade,
  user_id      uuid not null references auth.users (id) on delete cascade default auth.uid(),
  kind         text not null check (kind in ('specs_tailored', 'short_deadline', 'single_bid', 'price_inflated', 'conflict_of_interest', 'not_delivered', 'other')),
  body         text not null check (char_length(body) between 20 and 3000),
  status       text not null default 'submitted' check (status in ('submitted', 'answered', 'fixed', 'dismissed', 'escalated')),
  response     text check (char_length(response) <= 4000),
  escalated_to text check (escalated_to in ('PPRA', 'EACC', 'Auditor-General')),
  due_at       timestamptz not null default now() + interval '14 days',
  answered_at  timestamptz,
  created_at   timestamptz not null default now()
);
create index tender_concerns_tender_idx on public.tender_concerns (tender_id);
alter table public.tender_concerns enable row level security;
create policy "concerns: public read" on public.tender_concerns for select to anon, authenticated using (true);
create policy "concerns: residents file" on public.tender_concerns for insert to authenticated with check (user_id = (select auth.uid()));
create policy "concerns: county answers" on public.tender_concerns for update to authenticated
  using (private.has_role(array['super_admin', 'admin', 'chief_officer']) or user_id = (select auth.uid()))
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer']) or user_id = (select auth.uid()));
revoke all on public.tender_concerns from anon, authenticated;
grant select (id, reference, tender_id, kind, body, status, response, escalated_to, due_at, answered_at, created_at) on public.tender_concerns to anon, authenticated;
grant insert (tender_id, kind, body) on public.tender_concerns to authenticated;
grant update (status, response, escalated_to) on public.tender_concerns to authenticated;
create trigger audit_tender_concerns after insert or update or delete on public.tender_concerns
  for each row execute function private.audit_row();

create function private.concerns_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_staff boolean := private.has_role(array['super_admin', 'admin', 'chief_officer']);
  v_title text;
begin
  if tg_op = 'INSERT' then
    if (select count(*) from public.tender_concerns c where c.user_id = new.user_id and c.created_at > now() - interval '1 day') >= 5 then
      raise exception 'You can raise up to 5 concerns a day' using errcode = '54000';
    end if;
    new.status := 'submitted'; new.response := null; new.escalated_to := null; new.answered_at := null;
    new.created_at := now(); new.due_at := now() + interval '14 days';
    select t.reference || ': ' || t.title into v_title from public.tenders t where t.id = new.tender_id;
    insert into public.notifications (user_id, title, message, kind, link)
    select distinct r.user_id, 'Procurement concern ' || new.reference, coalesce(v_title, 'A tender') || '. Answer by ' || to_char(new.due_at at time zone 'Africa/Nairobi', 'DD Mon YYYY') || '.', 'warning', '/console/concerns'
      from public.staff_roles r where r.active and (r.expires_at is null or r.expires_at > now()) and r.role in ('super_admin', 'admin', 'chief_officer');
    return new;
  end if;
  -- the person who raised it may only escalate, and only once the county is late or has dismissed it
  if not v_staff then
    if new.response is distinct from old.response or new.status not in (old.status, 'escalated') then
      raise exception 'Only the county can answer a concern' using errcode = '42501';
    end if;
    if new.status = 'escalated' and old.status <> 'escalated' then
      if not (old.status = 'dismissed' or (old.status = 'submitted' and old.due_at < now())) then
        raise exception 'You can escalate once the county is late or has dismissed the concern' using errcode = '22023';
      end if;
      if new.escalated_to is null then raise exception 'Say where it was escalated' using errcode = '22023'; end if;
    end if;
    return new;
  end if;
  if new.status in ('answered', 'fixed', 'dismissed') and coalesce(trim(new.response), '') = '' then
    raise exception 'Give the answer in public' using errcode = '22023';
  end if;
  if new.status <> old.status and new.status in ('answered', 'fixed', 'dismissed') then
    new.answered_at := now();
    insert into public.notifications (user_id, title, message, kind, link)
    values (new.user_id, 'Your procurement concern was answered', new.reference || ': ' || left(new.response, 200), case when new.status = 'fixed' then 'success' else 'info' end, '/open#concerns');
  end if;
  new.due_at := old.due_at;
  return new;
end;
$$;
create trigger tender_concerns_rules before insert or update on public.tender_concerns
  for each row execute function private.concerns_rules();

-- ===================================================================================================================
-- 6. County finance and audit, all 47 counties
-- ===================================================================================================================
-- Entered by the county (or a researcher with an admin role) from the Controller of Budget's budget implementation
-- reviews and the Auditor-General's county reports. Every row carries its source.
create table public.county_finance (
  county_code      int not null check (county_code between 1 and 47),
  fiscal_year      text not null check (fiscal_year ~ '^20[0-9]{2}/[0-9]{2}$'),
  dev_budget       numeric(16, 2) check (dev_budget >= 0),
  dev_spent        numeric(16, 2) check (dev_spent >= 0),
  rec_budget       numeric(16, 2) check (rec_budget >= 0),
  rec_spent        numeric(16, 2) check (rec_spent >= 0),
  osr_target       numeric(16, 2) check (osr_target >= 0),
  osr_actual       numeric(16, 2) check (osr_actual >= 0),
  pending_bills    numeric(16, 2) check (pending_bills >= 0),
  audit_opinion    text check (audit_opinion in ('unqualified', 'qualified', 'adverse', 'disclaimer')),
  source           text not null check (char_length(source) between 3 and 300),
  source_url       text check (source_url ~ '^https://'),
  updated_at       timestamptz not null default now(),
  primary key (county_code, fiscal_year)
);
alter table public.county_finance enable row level security;
create policy "finance: public read" on public.county_finance for select to anon, authenticated using (true);
create policy "finance: admins write" on public.county_finance for insert to authenticated with check (private.is_admin());
create policy "finance: admins update" on public.county_finance for update to authenticated using (private.is_admin()) with check (private.is_admin());
create policy "finance: admins delete" on public.county_finance for delete to authenticated using (private.is_admin());
grant select on public.county_finance to anon, authenticated;
grant insert, update, delete on public.county_finance to authenticated;
create trigger audit_county_finance after insert or update or delete on public.county_finance
  for each row execute function private.audit_row();
create trigger county_finance_touch before update on public.county_finance
  for each row execute function private.touch_updated_at();

-- ===================================================================================================================
-- 7. Agree / disagree statements on consultations
-- ===================================================================================================================
create table public.consultation_statements (
  id              bigint generated always as identity primary key,
  consultation_id uuid not null references public.consultations (id) on delete cascade,
  user_id         uuid not null references auth.users (id) on delete cascade default auth.uid(),
  body            text not null check (char_length(body) between 10 and 160),
  hidden          boolean not null default false,
  created_at      timestamptz not null default now()
);
create index consultation_statements_idx on public.consultation_statements (consultation_id);
alter table public.consultation_statements enable row level security;
create policy "statements: public read" on public.consultation_statements for select to anon using (not hidden);
create policy "statements: read, admins see hidden" on public.consultation_statements for select to authenticated using (not hidden or private.is_admin());
create policy "statements: residents while open" on public.consultation_statements for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (select 1 from public.consultations c where c.id = consultation_id and now() between c.opens_at and c.closes_at));
create policy "statements: admins moderate" on public.consultation_statements for update to authenticated using (private.is_admin()) with check (private.is_admin());
revoke all on public.consultation_statements from anon, authenticated;
grant select (id, consultation_id, body, hidden, created_at) on public.consultation_statements to anon, authenticated;
grant insert (consultation_id, body) on public.consultation_statements to authenticated;
grant update (hidden) on public.consultation_statements to authenticated;

create table public.statement_votes (
  statement_id bigint not null references public.consultation_statements (id) on delete cascade,
  user_id      uuid not null references auth.users (id) on delete cascade default auth.uid(),
  vote         smallint not null check (vote in (-1, 0, 1)),
  created_at   timestamptz not null default now(),
  primary key (statement_id, user_id)
);
alter table public.statement_votes enable row level security;
create policy "votes: own" on public.statement_votes for select to authenticated using (user_id = (select auth.uid()));
create policy "votes: cast while open" on public.statement_votes for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (
    select 1 from public.consultation_statements s join public.consultations c on c.id = s.consultation_id
     where s.id = statement_id and not s.hidden and now() between c.opens_at and c.closes_at));
create policy "votes: change own while open" on public.statement_votes for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant select, insert, update on public.statement_votes to authenticated;

create function private.statements_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select count(*) from public.consultation_statements s where s.user_id = new.user_id and s.consultation_id = new.consultation_id) >= 3 then
    raise exception 'You can add up to 3 statements to one consultation' using errcode = '54000';
  end if;
  new.created_at := now();
  return new;
end;
$$;
create trigger consultation_statements_limit before insert on public.consultation_statements
  for each row execute function private.statements_limit();

-- Totals per statement, and a pseudonymous vote matrix (participant numbers, not people) so the page can find
-- opinion groups the way Pol.is does.
create function internal.statement_results(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with c as (select id from public.consultations where slug = p_slug),
  s as (select st.* from public.consultation_statements st join c on c.id = st.consultation_id where not st.hidden),
  v as (select sv.* from public.statement_votes sv join s on s.id = sv.statement_id),
  p as (select user_id, row_number() over (order by min(created_at)) as n from v group by user_id)
  select jsonb_build_object(
    'statements', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'body', s.body, 'created_at', s.created_at,
        'agree', (select count(*) from v where v.statement_id = s.id and v.vote = 1),
        'disagree', (select count(*) from v where v.statement_id = s.id and v.vote = -1),
        'pass', (select count(*) from v where v.statement_id = s.id and v.vote = 0)) order by s.id) from s), '[]'::jsonb),
    'participants', (select count(*) from p),
    'votes', coalesce((select jsonb_agg(jsonb_build_array(p.n, v.statement_id, v.vote)) from v join p on p.user_id = v.user_id), '[]'::jsonb));
$$;
create function public.statement_results(p_slug text)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.statement_results(p_slug => p_slug) $$;
revoke all on function public.statement_results(text) from public;
grant execute on function public.statement_results(text) to anon, authenticated, service_role;
grant execute on function internal.statement_results(text) to anon, authenticated, service_role;

-- ===================================================================================================================
-- 8. Quick polls
-- ===================================================================================================================
create table public.polls (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{2,78}$'),
  question    text not null check (char_length(question) between 8 and 200),
  question_sw text check (char_length(question_sw) <= 200),
  options     jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) between 2 and 6),
  ward_id     text references public.wards (id),
  opens_at    timestamptz not null default now(),
  closes_at   timestamptz not null,
  created_by  uuid references auth.users (id) default auth.uid(),
  created_at  timestamptz not null default now(),
  check (closes_at > opens_at)
);
alter table public.polls enable row level security;
create policy "polls: public read" on public.polls for select to anon, authenticated using (true);
create policy "polls: publishers create" on public.polls for insert to authenticated
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']));
create policy "polls: publishers update" on public.polls for update to authenticated
  using (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']))
  with check (private.has_role(array['super_admin', 'admin', 'chief_officer', 'sub_county_admin', 'ward_admin']));
grant select on public.polls to anon, authenticated;
grant insert, update on public.polls to authenticated;

create table public.poll_votes (
  poll_id    uuid not null references public.polls (id) on delete cascade,
  user_id    uuid not null references auth.users (id) on delete cascade default auth.uid(),
  option_id  text not null check (char_length(option_id) between 1 and 40),
  ward_id    text references public.wards (id),
  channel    text not null default 'web' check (channel in ('web', 'sms', 'ussd')),
  created_at timestamptz not null default now(),
  primary key (poll_id, user_id)
);
alter table public.poll_votes enable row level security;
create policy "poll votes: own" on public.poll_votes for select to authenticated using (user_id = (select auth.uid()));
create policy "poll votes: once while open" on public.poll_votes for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (
    select 1 from public.polls p where p.id = poll_id and now() between p.opens_at and p.closes_at
       and exists (select 1 from jsonb_array_elements(p.options) o where o ->> 'id' = option_id)));
grant select, insert on public.poll_votes to authenticated;

create function internal.poll_results(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('total', count(v.*),
    'by_option', coalesce((select jsonb_object_agg(x.option_id, x.n) from (select v2.option_id, count(*) n from public.poll_votes v2 where v2.poll_id = p.id group by v2.option_id) x), '{}'::jsonb),
    'by_ward', coalesce((select jsonb_agg(jsonb_build_object('ward_id', x.ward_id, 'option_id', x.option_id, 'n', x.n)) from (
        select v3.ward_id, v3.option_id, count(*) n from public.poll_votes v3 where v3.poll_id = p.id and v3.ward_id is not null group by 1, 2) x), '[]'::jsonb))
  from public.polls p left join public.poll_votes v on v.poll_id = p.id
  where p.slug = p_slug
  group by p.id;
$$;
create function public.poll_results(p_slug text)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.poll_results(p_slug => p_slug) $$;
revoke all on function public.poll_results(text) from public;
grant execute on function public.poll_results(text) to anon, authenticated, service_role;
grant execute on function internal.poll_results(text) to anon, authenticated, service_role;

-- ===================================================================================================================
-- 9. Flagging abusive public content
-- ===================================================================================================================
alter table public.consultation_comments add column hidden boolean not null default false;
drop policy "comments: public read" on public.consultation_comments;
create policy "comments: public read" on public.consultation_comments for select to anon using (not hidden);
create policy "comments: read, admins see hidden" on public.consultation_comments for select to authenticated using (not hidden or private.is_admin());
create policy "comments: admins moderate" on public.consultation_comments for update to authenticated using (private.is_admin()) with check (private.is_admin());
grant select (hidden) on public.consultation_comments to anon, authenticated;
grant update (hidden) on public.consultation_comments to authenticated;

create table public.content_flags (
  id          bigint generated always as identity primary key,
  kind        text not null check (kind in ('consultation_comment', 'statement', 'champion_check', 'concern')),
  target_id   text not null check (char_length(target_id) between 1 and 60),
  reason      text not null check (reason in ('abuse', 'personal_details', 'false', 'spam', 'other')),
  user_id     uuid not null references auth.users (id) on delete cascade default auth.uid(),
  status      text not null default 'open' check (status in ('open', 'kept', 'removed')),
  created_at  timestamptz not null default now(),
  unique (kind, target_id, user_id)
);
alter table public.content_flags enable row level security;
create policy "flags: anyone signed in" on public.content_flags for insert to authenticated with check (user_id = (select auth.uid()));
create policy "flags: admins read" on public.content_flags for select to authenticated using (private.is_admin());
create policy "flags: admins decide" on public.content_flags for update to authenticated using (private.is_admin()) with check (private.is_admin());
revoke all on public.content_flags from anon, authenticated;
grant insert (kind, target_id, reason) on public.content_flags to authenticated;
grant select, update (status) on public.content_flags to authenticated;

-- Three different people flagging the same thing hides it until an administrator decides.
create function private.flags_autohide()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select count(*) from public.content_flags f where f.kind = new.kind and f.target_id = new.target_id and f.status = 'open') >= 3 then
    if new.kind = 'consultation_comment' then update public.consultation_comments set hidden = true where id::text = new.target_id;
    elsif new.kind = 'statement' then update public.consultation_statements set hidden = true where id::text = new.target_id;
    end if;
  end if;
  return new;
end;
$$;
create trigger content_flags_autohide after insert on public.content_flags
  for each row execute function private.flags_autohide();

-- The moderation queue: what was flagged, why, and what it says.
create function internal.moderation_queue()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when private.is_admin() then coalesce(jsonb_agg(x order by x ->> 'last' desc), '[]'::jsonb) else '[]'::jsonb end from (
    select jsonb_build_object('kind', f.kind, 'target_id', f.target_id, 'flags', count(*), 'reasons', jsonb_agg(distinct f.reason), 'last', max(f.created_at),
      'text', case f.kind
        when 'consultation_comment' then (select c.body from public.consultation_comments c where c.id::text = f.target_id)
        when 'statement' then (select s.body from public.consultation_statements s where s.id::text = f.target_id)
        when 'champion_check' then (select c.comment from public.champion_checks c where c.id::text = f.target_id)
        when 'concern' then (select c.body from public.tender_concerns c where c.id::text = f.target_id) end,
      'hidden', case f.kind
        when 'consultation_comment' then (select c.hidden from public.consultation_comments c where c.id::text = f.target_id)
        when 'statement' then (select s.hidden from public.consultation_statements s where s.id::text = f.target_id) end) as x
      from public.content_flags f where f.status = 'open' group by f.kind, f.target_id
  ) t;
$$;
create function public.moderation_queue()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.moderation_queue() $$;

create function internal.moderate(p_kind text, p_target text, p_remove boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_admin() then raise exception 'Only administrators can do this' using errcode = '42501'; end if;
  if p_kind = 'consultation_comment' then update public.consultation_comments set hidden = p_remove where id::text = p_target;
  elsif p_kind = 'statement' then update public.consultation_statements set hidden = p_remove where id::text = p_target;
  elsif p_kind = 'champion_check' and p_remove then delete from public.champion_checks where id::text = p_target;
  end if;
  update public.content_flags set status = case when p_remove then 'removed' else 'kept' end where kind = p_kind and target_id = p_target and status = 'open';
end;
$$;
create function public.moderate(p_kind text, p_target text, p_remove boolean)
returns void language sql volatile security invoker set search_path = ''
as $$ select internal.moderate(p_kind => p_kind, p_target => p_target, p_remove => p_remove) $$;
revoke all on function public.moderation_queue() from public, anon;
revoke all on function internal.moderation_queue() from public, anon;
revoke all on function public.moderate(text, text, boolean) from public, anon;
revoke all on function internal.moderate(text, text, boolean) from public, anon;
grant execute on function public.moderation_queue() to authenticated, service_role;
grant execute on function internal.moderation_queue() to authenticated, service_role;
grant execute on function public.moderate(text, text, boolean) to authenticated, service_role;
grant execute on function internal.moderate(text, text, boolean) to authenticated, service_role;

-- ===================================================================================================================
-- 10. The deadline scoreboard counts procurement concerns too
-- ===================================================================================================================
create or replace function internal.legal_deadlines()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'generated_at', now(),
    'info', (select jsonb_build_object(
        'decided', count(*) filter (where i.answered_at is not null),
        'on_time', count(*) filter (where i.answered_at is not null and i.answered_at <= coalesce(i.extended_to, i.due_at)),
        'waiting', count(*) filter (where i.status in ('submitted', 'extended')),
        'late_now', count(*) filter (where i.status in ('submitted', 'extended') and coalesce(i.extended_to, i.due_at) < now()))
      from public.info_requests i),
    'petitions', (select jsonb_build_object(
        'due', count(*) filter (where p.response_due_at is not null),
        'answered_on_time', count(*) filter (where p.responded_at is not null and p.responded_at <= p.response_due_at),
        'answered_late', count(*) filter (where p.responded_at > p.response_due_at),
        'late_now', count(*) filter (where p.responded_at is null and p.response_due_at < now()))
      from public.proposals p where p.kind = 'petition'),
    'consultations', (select jsonb_build_object(
        'closed', count(*) filter (where c.closes_at < now()),
        'reported', count(*) filter (where c.closes_at < now() and c.report_at is not null),
        'report_owed', count(*) filter (where c.closes_at < now() - interval '30 days' and c.report_at is null))
      from public.consultations c),
    'erasure', (select jsonb_build_object(
        'done', count(*) filter (where e.done_at is not null),
        'on_time', count(*) filter (where e.done_at is not null and e.done_at <= e.due_at),
        'late_now', count(*) filter (where e.done_at is null and e.due_at < now()))
      from private.erasure_requests e),
    'concerns', (select jsonb_build_object(
        'answered', count(*) filter (where t.answered_at is not null),
        'on_time', count(*) filter (where t.answered_at is not null and t.answered_at <= t.due_at),
        'fixed', count(*) filter (where t.status = 'fixed'),
        'late_now', count(*) filter (where t.answered_at is null and t.status = 'submitted' and t.due_at < now()))
      from public.tender_concerns t),
    'promises', (select jsonb_build_object(
        'total', count(*),
        'delivered', count(*) filter (where m.status = 'delivered'),
        'past_due', count(*) filter (where m.due_on < current_date and m.status not in ('delivered', 'dropped')))
      from public.commitments m)
  );
$$;

-- ===================================================================================================================
-- 11. A new ward poll reaches the ward's followers
-- ===================================================================================================================
create function private.polls_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.ward_id is not null then
    perform private.tell_followers('ward_tenders', new.ward_id, 'Quick poll: ' || left(new.question, 120),
      'Closes ' || to_char(new.closes_at at time zone 'Africa/Nairobi', 'DD Mon') || '.', '/polls#' || new.slug);
  end if;
  return new;
end;
$$;
create trigger polls_notify after insert on public.polls for each row execute function private.polls_notify();

-- ==== 20260930002300_engagement.sql ====

-- Migration 0023: things that bring residents back, built on outcomes rather than volume.
--   1. "It's fixed" SMS says how many days it took and points to the before and after photos
--   2. Ward league: wards (never people) ranked on fixing on time, answering on time and taking part
--   3. A public live feed of what is happening (no descriptions, no reporters, no sensitive categories)
--   4. Community clean-ups: champions and ward staff post them, residents say they are going
--   5. Ask your MCA: public questions, upvotes, answers and an answer rate per ward
--   6. Promise deadlines: followers are told when a promise passes its due date
--   7. The weekly ward SMS becomes three lines: fixed, late, one thing you can do

-- ===================================================================================================================
-- 1. "It's fixed" message
-- ===================================================================================================================
create or replace function private.notify_report_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text;
  v_r public.reports;
  v_url text;
  v_line text;
  v_days int;
begin
  if not new.is_public or new.kind not in ('status', 'public_message', 'reopened') then return new; end if;
  select c.phone_e164 into v_phone from private.report_contacts c where c.report_id = new.report_id;
  if v_phone is null then return new; end if;
  select * into v_r from public.reports r where r.id = new.report_id;
  select c.settings ->> 'web_url' into v_url from public.county c limit 1;
  if new.kind = 'status' and new.data ->> 'status' = 'resolved' then
    v_days := greatest(0, floor(extract(epoch from (coalesce(v_r.resolved_at, now()) - v_r.created_at)) / 86400)::int);
    insert into private.outbox (channel, recipient, body, related)
    values ('sms', v_phone,
            left('Fixed! ' || v_r.reference || ' was fixed ' || case when v_days = 0 then 'the same day.' when v_days = 1 then 'in 1 day.' else 'in ' || v_days || ' days.' end
              || coalesce(' ' || new.message, '')
              || case when v_url is not null then ' See the before and after, and tell us if it is really fixed: ' || v_url || '/case/' || v_r.reference else '' end, 480),
            jsonb_build_object('report_id', new.report_id, 'event', 'fixed'));
    return new;
  end if;
  v_line := case when new.kind = 'status' then initcap(replace(coalesce(new.data ->> 'status', 'updated'), '_', ' ')) else null end;
  insert into private.outbox (channel, recipient, body, related)
  values ('sms', v_phone,
          'County update ' || v_r.reference || ': ' || coalesce(v_line, '') || case when v_line is not null and new.message is not null then ' - ' else '' end
            || coalesce(new.message, '') || case when v_url is not null then ' ' || v_url || '/case/' || v_r.reference else '' end,
          jsonb_build_object('report_id', new.report_id, 'event', new.kind));
  return new;
end;
$$;

-- ===================================================================================================================
-- 2. Ward league
-- ===================================================================================================================
-- Score 0 to 100 for a window of p_days, and the same for the window before it so "most improved" is fair:
--   45% problems fixed on time (of those due in the window), 30% acknowledged on time, 25% residents taking part
--   (reports, budget votes, poll answers and consultation comments per 1,000 residents; 5 per 1,000 counts as full).
-- A ward needs at least 3 reports in a window to be scored, so one lucky fix cannot top the table.
create function internal.ward_league(p_days int default 30)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with win as (
    select 0 as w, now() - make_interval(days => p_days) as a, now() as b
    union all select 1, now() - make_interval(days => 2 * p_days), now() - make_interval(days => p_days)
  ), rep as (
    select win.w, r.ward_id,
           count(*) filter (where r.created_at >= win.a and r.created_at < win.b) as reports,
           count(*) filter (where r.created_at >= win.a and r.created_at < win.b and r.acknowledged_at is not null and r.acknowledged_at <= r.ack_due_at) as acked_on_time,
           count(*) filter (where r.resolve_due_at >= win.a and r.resolve_due_at < win.b) as due,
           count(*) filter (where r.resolve_due_at >= win.a and r.resolve_due_at < win.b and r.resolved_at is not null and r.resolved_at <= r.resolve_due_at) as fixed_on_time,
           count(*) filter (where r.resolved_at >= win.a and r.resolved_at < win.b) as fixed,
           percentile_cont(0.5) within group (order by extract(epoch from r.resolved_at - r.created_at) / 86400)
             filter (where r.resolved_at >= win.a and r.resolved_at < win.b) as median_days
      from win cross join public.reports r
     where r.status <> 'rejected'
     group by win.w, r.ward_id
  ), part as (
    select win.w, x.ward_id, count(*) as n
      from win cross join lateral (
        select v.ward_id, v.created_at from public.votes v
        union all select p.ward_id, p.created_at from public.poll_votes p where p.ward_id is not null
        union all select c.ward_id, c.created_at from public.consultation_comments c where c.ward_id is not null
        union all select r.ward_id, r.created_at from public.reports r
      ) x
     where x.created_at >= win.a and x.created_at < win.b
     group by win.w, x.ward_id
  ), scored as (
    select wd.id as ward_id, wd.name, wd.population, win.w,
           coalesce(rep.reports, 0) as reports, coalesce(rep.fixed, 0) as fixed, coalesce(rep.due, 0) as due,
           coalesce(rep.fixed_on_time, 0) as fixed_on_time, coalesce(rep.acked_on_time, 0) as acked_on_time,
           rep.median_days, coalesce(part.n, 0) as taking_part,
           case when coalesce(rep.reports, 0) < 3 then null else round(100 * (
               0.45 * case when coalesce(rep.due, 0) = 0 then 0.5 else rep.fixed_on_time::numeric / rep.due end
             + 0.30 * rep.acked_on_time::numeric / rep.reports
             + 0.25 * least(1, coalesce(part.n, 0) * 1000.0 / greatest(coalesce(wd.population, 30000), 1) / 5)), 1) end as score
      from public.wards wd cross join win
      left join rep on rep.ward_id = wd.id and rep.w = win.w
      left join part on part.ward_id = wd.id and part.w = win.w
  )
  select jsonb_build_object('days', p_days, 'generated_at', now(), 'wards', coalesce(jsonb_agg(jsonb_build_object(
      'ward_id', c.ward_id, 'name', c.name, 'score', c.score, 'previous', p.score,
      'change', case when c.score is not null and p.score is not null then round(c.score - p.score, 1) end,
      'reports', c.reports, 'fixed', c.fixed, 'due', c.due, 'fixed_on_time', c.fixed_on_time, 'acked_on_time', c.acked_on_time,
      'median_days', round(c.median_days::numeric, 1), 'taking_part', c.taking_part)
      order by c.score desc nulls last, c.name), '[]'::jsonb))
    from scored c join scored p on p.ward_id = c.ward_id and p.w = 1
   where c.w = 0;
$$;
create function public.ward_league(p_days int default 30)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.ward_league(p_days => least(greatest(coalesce(p_days, 30), 7), 365)) $$;
revoke all on function public.ward_league(int) from public;
revoke all on function internal.ward_league(int) from public;
grant execute on function public.ward_league(int) to anon, authenticated, service_role;
grant execute on function internal.ward_league(int) to anon, authenticated, service_role;

-- ===================================================================================================================
-- 3. Live public feed
-- ===================================================================================================================
create function internal.live_activity(p_limit int default 30)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by (x ->> 'at') desc), '[]'::jsonb) from (
    select * from (
      select jsonb_build_object('kind', 'report', 'ward', w.name, 'ward_id', w.id, 'category', c.name, 'category_sw', c.name_sw, 'at', r.created_at) as x
        from public.reports r join public.wards w on w.id = r.ward_id join public.report_categories c on c.id = r.category_id
       where not c.sensitive and r.status <> 'rejected' and r.created_at > now() - interval '14 days'
      union all
      select jsonb_build_object('kind', 'resolved', 'ward', w.name, 'ward_id', w.id, 'category', c.name, 'category_sw', c.name_sw, 'at', r.resolved_at,
                                'reference', r.reference, 'days', greatest(0, floor(extract(epoch from r.resolved_at - r.created_at) / 86400))::int)
        from public.reports r join public.wards w on w.id = r.ward_id join public.report_categories c on c.id = r.category_id
       where not c.sensitive and r.resolved_at > now() - interval '14 days' and r.status in ('resolved', 'closed')
      union all
      select jsonb_build_object('kind', 'milestone', 'ward', w.name, 'ward_id', w.id, 'title', m.title, 'project', p.title, 'slug', p.slug, 'at', m.completed_at::timestamptz)
        from public.project_milestones m join public.projects p on p.id = m.project_id join public.wards w on w.id = p.ward_id
       where p.published and m.completed_at > now() - interval '30 days'
      union all
      select jsonb_build_object('kind', 'poll', 'title', p.question, 'slug', p.slug, 'at', p.opens_at)
        from public.polls p where p.opens_at <= now() and p.opens_at > now() - interval '30 days'
      union all
      select jsonb_build_object('kind', 'notice', 'ward', w.name, 'title', n.title, 'at', n.starts_at)
        from public.service_notices n left join public.wards w on w.id = n.ward_id
       where n.status = 'active' and n.starts_at <= now() and n.starts_at > now() - interval '14 days'
    ) y order by (x ->> 'at') desc limit least(greatest(coalesce(p_limit, 30), 1), 100)
  ) z;
$$;
create function public.live_activity(p_limit int default 30)
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.live_activity(p_limit => p_limit) $$;
revoke all on function public.live_activity(int) from public;
revoke all on function internal.live_activity(int) from public;
grant execute on function public.live_activity(int) to anon, authenticated, service_role;
grant execute on function internal.live_activity(int) to anon, authenticated, service_role;

-- ===================================================================================================================
-- 4. Community clean-ups and other neighbourhood events
-- ===================================================================================================================
create table public.community_events (
  id          uuid primary key default gen_random_uuid(),
  ward_id     text not null references public.wards (id),
  kind        text not null default 'cleanup' check (kind in ('cleanup', 'tree_planting', 'drainage', 'other')),
  title       text not null check (char_length(title) between 5 and 120),
  details     text check (char_length(details) <= 1000),
  meet_at     text not null check (char_length(meet_at) between 3 and 200),
  starts_at   timestamptz not null,
  ends_at     timestamptz not null,
  status      text not null default 'scheduled' check (status in ('scheduled', 'cancelled', 'held')),
  going       int not null default 0,
  attended    int check (attended >= 0),
  outcome     text check (char_length(outcome) <= 1000),
  created_by  uuid not null references auth.users (id) on delete cascade default auth.uid(),
  created_at  timestamptz not null default now(),
  check (ends_at > starts_at)
);
create index community_events_when_idx on public.community_events (starts_at);
alter table public.community_events enable row level security;
create policy "events: public read" on public.community_events for select to anon, authenticated using (true);
create policy "events: champions and ward staff post" on public.community_events for insert to authenticated
  with check (created_by = (select auth.uid()) and (
    exists (select 1 from public.ward_champions c where c.user_id = (select auth.uid()) and c.ward_id = community_events.ward_id and c.status = 'active')
    or private.can_manage_ward(ward_id)));
create policy "events: organiser and ward staff update" on public.community_events for update to authenticated
  using (created_by = (select auth.uid()) or private.can_manage_ward(ward_id))
  with check (created_by = (select auth.uid()) or private.can_manage_ward(ward_id));
revoke all on public.community_events from anon, authenticated;
grant select (id, ward_id, kind, title, details, meet_at, starts_at, ends_at, status, going, attended, outcome, created_at) on public.community_events to anon, authenticated;
grant insert (ward_id, kind, title, details, meet_at, starts_at, ends_at) on public.community_events to authenticated;
grant update (title, details, meet_at, starts_at, ends_at, status, attended, outcome) on public.community_events to authenticated;

create table public.event_rsvps (
  event_id   uuid not null references public.community_events (id) on delete cascade,
  user_id    uuid not null references auth.users (id) on delete cascade default auth.uid(),
  created_at timestamptz not null default now(),
  primary key (event_id, user_id)
);
alter table public.event_rsvps enable row level security;
create policy "rsvps: own" on public.event_rsvps for select to authenticated using (user_id = (select auth.uid()));
create policy "rsvps: say you are going" on public.event_rsvps for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (select 1 from public.community_events e where e.id = event_id and e.status = 'scheduled' and e.ends_at > now()));
create policy "rsvps: change your mind" on public.event_rsvps for delete to authenticated using (user_id = (select auth.uid()));
grant select, insert, delete on public.event_rsvps to authenticated;

create function private.events_going()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.community_events e set going = (select count(*) from public.event_rsvps r where r.event_id = e.id)
   where e.id = coalesce(new.event_id, old.event_id);
  return null;
end;
$$;
create trigger event_rsvps_count after insert or delete on public.event_rsvps for each row execute function private.events_going();

create function private.events_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform private.tell_followers('ward_tenders', new.ward_id, 'Neighbourhood event: ' || left(new.title, 100),
      to_char(new.starts_at at time zone 'Africa/Nairobi', 'Dy DD Mon HH24:MI') || ', ' || left(new.meet_at, 80) || '.', '/events#' || new.id);
  elsif new.status = 'cancelled' and old.status <> 'cancelled' then
    insert into public.notifications (user_id, title, message, kind, link)
    select r.user_id, 'Event cancelled: ' || left(new.title, 100), 'The organiser cancelled it.', 'warning', '/events#' || new.id
      from public.event_rsvps r where r.event_id = new.id;
  end if;
  return new;
end;
$$;
create trigger community_events_notify after insert or update of status on public.community_events
  for each row execute function private.events_notify();

-- ===================================================================================================================
-- 5. Ask your MCA
-- ===================================================================================================================
create table public.mca_questions (
  id          uuid primary key default gen_random_uuid(),
  ward_id     text not null references public.wards (id),
  user_id     uuid not null references auth.users (id) on delete cascade default auth.uid(),
  body        text not null check (char_length(body) between 10 and 600),
  votes       int not null default 0,
  status      text not null default 'open' check (status in ('open', 'answered')),
  hidden      boolean not null default false,
  answer      text check (char_length(answer) <= 3000),
  answered_by uuid references auth.users (id),
  answered_at timestamptz,
  created_at  timestamptz not null default now()
);
create index mca_questions_ward_idx on public.mca_questions (ward_id, created_at desc);
alter table public.mca_questions enable row level security;
create policy "mca questions: public" on public.mca_questions for select to anon using (not hidden);
create policy "mca questions: signed in" on public.mca_questions for select to authenticated
  using (not hidden or user_id = (select auth.uid()) or private.is_admin());
create policy "mca questions: residents ask" on public.mca_questions for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'open' and answer is null);
create policy "mca questions: the ward's MCA answers" on public.mca_questions for update to authenticated
  using (exists (select 1 from public.staff_roles s where s.user_id = (select auth.uid()) and s.active and s.role = 'assembly_member' and s.ward_id = mca_questions.ward_id)
         or private.is_admin())
  with check (exists (select 1 from public.staff_roles s where s.user_id = (select auth.uid()) and s.active and s.role = 'assembly_member' and s.ward_id = mca_questions.ward_id)
         or private.is_admin());
revoke all on public.mca_questions from anon, authenticated;
grant select (id, ward_id, body, votes, status, hidden, answer, answered_at, created_at) on public.mca_questions to anon, authenticated;
grant insert (ward_id, body) on public.mca_questions to authenticated;
grant update (answer, hidden) on public.mca_questions to authenticated;

create table public.mca_question_votes (
  question_id uuid not null references public.mca_questions (id) on delete cascade,
  user_id     uuid not null references auth.users (id) on delete cascade default auth.uid(),
  created_at  timestamptz not null default now(),
  primary key (question_id, user_id)
);
alter table public.mca_question_votes enable row level security;
create policy "mca votes: own" on public.mca_question_votes for select to authenticated using (user_id = (select auth.uid()));
create policy "mca votes: one each" on public.mca_question_votes for insert to authenticated with check (user_id = (select auth.uid()));
create policy "mca votes: take back" on public.mca_question_votes for delete to authenticated using (user_id = (select auth.uid()));
grant select, insert, delete on public.mca_question_votes to authenticated;

create function private.mca_votes_count()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.mca_questions q set votes = (select count(*) from public.mca_question_votes v where v.question_id = q.id)
   where q.id = coalesce(new.question_id, old.question_id);
  return null;
end;
$$;
create trigger mca_question_votes_count after insert or delete on public.mca_question_votes for each row execute function private.mca_votes_count();

create function private.mca_questions_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select count(*) from public.mca_questions q where q.user_id = new.user_id and q.created_at > now() - interval '1 day') >= 3 then
      raise exception 'You can ask up to 3 questions a day' using errcode = '54000';
    end if;
    new.votes := 0;
    insert into public.notifications (user_id, title, message, kind, link)
    select s.user_id, 'New question from a resident', left(new.body, 140), 'info', '/console/questions'
      from public.staff_roles s where s.active and s.role = 'assembly_member' and s.ward_id = new.ward_id;
    return new;
  end if;
  if new.answer is distinct from old.answer then
    if coalesce(btrim(new.answer), '') = '' then raise exception 'An answer cannot be empty' using errcode = '22023'; end if;
    if old.answered_at is null then
      new.answered_at := now();
      insert into public.notifications (user_id, title, message, kind, link)
      values (new.user_id, 'Your MCA answered', left(new.answer, 140), 'success', '/ask#' || new.id);
    end if;
    new.answered_by := (select auth.uid());
    new.status := 'answered';
  end if;
  new.body := old.body; new.ward_id := old.ward_id; new.user_id := old.user_id; new.created_at := old.created_at;
  return new;
end;
$$;
create trigger mca_questions_rules before insert or update on public.mca_questions for each row execute function private.mca_questions_rules();

-- Hiding is for administrators (or the three-flag rule, which runs with owner rights). This guard runs with the
-- caller's rights so it can tell a direct update by a signed-in user from the automatic one.
create function private.mca_hide_guard()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.hidden is distinct from old.hidden and current_user = 'authenticated' and not private.is_admin() then
    raise exception 'Only administrators can hide a question' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger mca_questions_hide_guard before update of hidden on public.mca_questions for each row execute function private.mca_hide_guard();

-- Answer rate per ward: asked, answered, answered within 14 days, waiting.
create function internal.mca_scoreboard()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('ward_id', x.ward_id, 'asked', x.asked, 'answered', x.answered, 'on_time', x.on_time, 'waiting', x.waiting)
         order by x.asked desc), '[]'::jsonb)
    from (select q.ward_id, count(*) asked, count(*) filter (where q.answered_at is not null) answered,
                 count(*) filter (where q.answered_at is not null and q.answered_at <= q.created_at + interval '14 days') on_time,
                 count(*) filter (where q.answered_at is null) waiting
            from public.mca_questions q where not q.hidden group by q.ward_id) x;
$$;
create function public.mca_scoreboard()
returns jsonb language sql stable security invoker set search_path = ''
as $$ select internal.mca_scoreboard() $$;
revoke all on function public.mca_scoreboard() from public;
revoke all on function internal.mca_scoreboard() from public;
grant execute on function public.mca_scoreboard() to anon, authenticated, service_role;
grant execute on function internal.mca_scoreboard() to anon, authenticated, service_role;

-- Questions can be flagged like comments; three flags hide one until an administrator decides.
alter table public.content_flags drop constraint content_flags_kind_check;
alter table public.content_flags add constraint content_flags_kind_check
  check (kind in ('consultation_comment', 'statement', 'champion_check', 'concern', 'mca_question'));

create or replace function private.flags_autohide()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select count(*) from public.content_flags f where f.kind = new.kind and f.target_id = new.target_id and f.status = 'open') >= 3 then
    if new.kind = 'consultation_comment' then update public.consultation_comments set hidden = true where id::text = new.target_id;
    elsif new.kind = 'statement' then update public.consultation_statements set hidden = true where id::text = new.target_id;
    elsif new.kind = 'mca_question' then update public.mca_questions set hidden = true where id::text = new.target_id;
    end if;
  end if;
  return new;
end;
$$;

create or replace function internal.moderation_queue()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when private.is_admin() then coalesce(jsonb_agg(x order by x ->> 'last' desc), '[]'::jsonb) else '[]'::jsonb end from (
    select jsonb_build_object('kind', f.kind, 'target_id', f.target_id, 'flags', count(*), 'reasons', jsonb_agg(distinct f.reason), 'last', max(f.created_at),
      'text', case f.kind
        when 'consultation_comment' then (select c.body from public.consultation_comments c where c.id::text = f.target_id)
        when 'statement' then (select s.body from public.consultation_statements s where s.id::text = f.target_id)
        when 'champion_check' then (select c.comment from public.champion_checks c where c.id::text = f.target_id)
        when 'concern' then (select c.body from public.tender_concerns c where c.id::text = f.target_id)
        when 'mca_question' then (select q.body from public.mca_questions q where q.id::text = f.target_id) end,
      'hidden', case f.kind
        when 'consultation_comment' then (select c.hidden from public.consultation_comments c where c.id::text = f.target_id)
        when 'statement' then (select s.hidden from public.consultation_statements s where s.id::text = f.target_id)
        when 'mca_question' then (select q.hidden from public.mca_questions q where q.id::text = f.target_id) end) as x
      from public.content_flags f where f.status = 'open' group by f.kind, f.target_id
  ) t;
$$;

create or replace function internal.moderate(p_kind text, p_target text, p_remove boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_admin() then raise exception 'Only administrators can do this' using errcode = '42501'; end if;
  if p_kind = 'consultation_comment' then update public.consultation_comments set hidden = p_remove where id::text = p_target;
  elsif p_kind = 'statement' then update public.consultation_statements set hidden = p_remove where id::text = p_target;
  elsif p_kind = 'mca_question' then update public.mca_questions set hidden = p_remove where id::text = p_target;
  elsif p_kind = 'champion_check' and p_remove then delete from public.champion_checks where id::text = p_target;
  end if;
  update public.content_flags set status = case when p_remove then 'removed' else 'kept' end where kind = p_kind and target_id = p_target and status = 'open';
end;
$$;

-- ===================================================================================================================
-- 6. Promise deadlines
-- ===================================================================================================================
alter table public.commitments add column deadline_told_on date;

create function public.svc_promise_deadlines()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  c record;
  n int := 0;
begin
  for c in
    select * from public.commitments
     where due_on < (now() at time zone 'Africa/Nairobi')::date and status in ('not_started', 'in_progress', 'delayed')
       and (deadline_told_on is null or deadline_told_on < due_on)
  loop
    perform private.tell_followers('commitment', c.slug, 'Promise deadline passed: ' || left(c.title, 100),
      'It was due on ' || to_char(c.due_on, 'DD Mon YYYY') || ' and is not delivered.', '/promises#' || c.slug, 'warning');
    update public.commitments set deadline_told_on = (now() at time zone 'Africa/Nairobi')::date where id = c.id;
    n := n + 1;
  end loop;
  return n;
end;
$$;
revoke all on function public.svc_promise_deadlines() from public, anon, authenticated;
grant execute on function public.svc_promise_deadlines() to service_role;

-- ===================================================================================================================
-- 7. The weekly ward SMS: fixed, late, one thing to do
-- ===================================================================================================================
create or replace function public.svc_ward_updates(p_frequency text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_days int := case p_frequency when 'daily' then 1 when 'weekly' then 7 else null end;
  v_name text;
  v_url text;
  w record;
  v_do text;
  n int;
  total int := 0;
begin
  if v_days is null then return 0; end if;
  select c.name, c.settings ->> 'web_url' into v_name, v_url from public.county c limit 1;
  for w in
    select ward.id, ward.name,
           (select count(*) from public.reports r where r.ward_id = ward.id and r.resolved_at >= now() - make_interval(days => v_days)) as fixed,
           (select count(*) from public.reports r where r.ward_id = ward.id and r.status not in ('resolved', 'closed', 'rejected')) as open_now,
           (select count(*) from public.reports r where r.ward_id = ward.id and r.status not in ('resolved', 'closed', 'rejected') and r.resolve_due_at < now()) as late
      from public.wards ward
     where exists (select 1 from private.subscribers s
                    where s.ward_id = ward.id and s.frequency = p_frequency and s.verified_at is not null and s.opted_out_at is null)
  loop
    -- one thing to do, the most useful first
    select coalesce(
      (select 'Clean-up ' || to_char(e.starts_at at time zone 'Africa/Nairobi', 'Dy DD Mon') || ' at ' || left(e.meet_at, 40) || '.'
         from public.community_events e where e.ward_id = w.id and e.status = 'scheduled' and e.starts_at > now() order by e.starts_at limit 1),
      (select 'Meeting ' || to_char(m.starts_at at time zone 'Africa/Nairobi', 'Dy DD Mon') || ': ' || left(m.title, 50) || '.'
         from public.public_meetings m where (m.ward_id = w.id or m.ward_id is null) and m.status = 'scheduled' and m.starts_at > now() order by m.starts_at limit 1),
      (select 'Answer the poll: ' || left(p.question, 60) from public.polls p
        where (p.ward_id = w.id or p.ward_id is null) and now() between p.opens_at and p.closes_at order by p.closes_at limit 1),
      (select 'Have your say on ' || left(c.title, 50) || ' by ' || to_char(c.closes_at, 'DD Mon') || '.' from public.consultations c
        where (c.ward_id = w.id or c.ward_id is null) and now() between c.opens_at and c.closes_at order by c.closes_at limit 1),
      'Report a problem: dial the county code or visit the site.') into v_do;
    insert into private.outbox (channel, recipient, body, related)
    select 'sms', s.phone_e164,
           left(format(E'%s %s:\nFixed: %s. Late: %s of %s open.\nDo: %s%s Reply STOP to opt out.',
                       w.name, case p_frequency when 'daily' then 'today' else 'this week' end,
                       w.fixed, w.late, w.open_now, v_do,
                       case when v_url is null then '' else ' ' || v_url end), 480),
           jsonb_build_object('ward_id', w.id, 'frequency', p_frequency)
      from private.subscribers s
     where s.ward_id = w.id and s.frequency = p_frequency and s.verified_at is not null and s.opted_out_at is null;
    get diagnostics n = row_count;
    total := total + n;
  end loop;
  return total;
end;
$$;
